INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u6-C1','kor',4,2,'u6',2,'원인과 결과의 뜻 — 원인은 일이 일어난 까닭, 결과는 그래서 벌어진 일',ARRAY['원인과 결과를 생각하며 보고 듣기(성취기준 번호 확인 필요)']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u6-C2','kor',4,2,'u6',2,'결과가 다시 원인이 됨 — 어떤 일의 결과는 다음 일의 원인이 되기도 해서 이야기가 한 줄로 길게 이어짐',ARRAY['원인과 결과를 생각하며 보고 듣기(성취기준 번호 확인 필요)']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u6-C3','kor',4,2,'u6',2,'예상의 까닭은 드러난 것에서 — 다음 일을 예상한 까닭은 앞 장면에 이미 나와 있는 것에서 댐 — 「그냥 그럴 것 같아서」·「더 재미있어서」 ✗',ARRAY['원인과 결과를 생각하며 보고 듣기(성취기준 번호 확인 필요)']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u6-C4','kor',4,2,'u6',2,'소식에 빠지면 안 되는 두 가지 — 일을 옮길 때 왜 일어났는지(원인)와 그래서 어떻게 되었는지(결과)가 빠지면 듣는 사람이 되묻게 됨',ARRAY['원인과 결과를 생각하며 보고 듣기(성취기준 번호 확인 필요)']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u6-C5','kor',4,2,'u6',2,'상상할 때 가장 먼저 생각할 것 — 이어질 내용을 상상할 때는 앞에서 어떤 일이 왜 일어났는지부터 봄 — 가장 놀라운 일 · 가장 길게 쓰는 법 ✗',ARRAY['이어질 내용을 상상해 쓰기(성취기준 번호 확인 필요)']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u6-C6','kor',4,2,'u6',2,'이 단원에서 배울 두 가지 — 원인과 결과를 생각하며 보고 듣기 · 이어질 내용을 상상해 쓰기 — 둘 다 까닭을 따져 보는 일에서 시작',ARRAY['원인과 결과를 생각하며 보고 듣기(성취기준 번호 확인 필요)']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u6-C7','kor',4,2,'u6',2,'영상은 따져 보는 것 — 영상은 넘기는 것이 아니라 무슨 일이 일어났는지 → 왜 일어났는지 → 그래서 어떻게 되었는지를 따져 보는 것',ARRAY['원인과 결과를 생각하며 보고 듣기(성취기준 번호 확인 필요)']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u6-C8','kor',4,2,'u6',2,'일어난 일 먼저 붙잡기 — 장면에 그대로 나와 있는 것만 일어난 일로 고름 — 짐작을 덧붙이지 않음',ARRAY['원인과 결과를 생각하며 보고 듣기(성취기준 번호 확인 필요)']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u6-C9','kor',4,2,'u6',2,'까닭이 달라지면 다음도 달라짐 — 있을 법한 까닭은 여럿일 수 있고, 어떤 까닭으로 보느냐에 따라 그래서 할 일이 달라짐',ARRAY['원인과 결과를 생각하며 보고 듣기(성취기준 번호 확인 필요)']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u6-C10','kor',4,2,'u6',2,'예상과 견주어 말하기 — 「무엇을 까닭으로 이렇게 예상했는데 그 부분이 같았다/달랐다」처럼 말함 — 「같아서 좋았다·달라서 아쉬웠다」 같은 느낌만 ✗',ARRAY['원인과 결과를 생각하며 보고 듣기(성취기준 번호 확인 필요)']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u6-C11','kor',4,2,'u6',2,'중심 사건의 앞과 뒤 — 가운데 사건을 붙잡고 앞(그 일의 원인)과 뒤(그 일의 결과)로 뻗어 나감 — 있을 만한 곳이 아닌 데에 있으면 까닭이 궁금해짐',ARRAY['원인과 결과를 생각하며 보고 듣기(성취기준 번호 확인 필요)']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u6-C12','kor',4,2,'u6',2,'예상은 달라도 까닭은 장면 안에서 — 친구와 다른 예상을 해도 되지만 그렇게 생각한 까닭을 장면 안에서 찾을 수 있어야 함 — 까닭을 댈 수 없으면 아무 말',ARRAY['원인과 결과를 생각하며 보고 듣기(성취기준 번호 확인 필요)']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u6-C13','kor',4,2,'u6',2,'보면서 메모하기 — 가장 큰 사건 · 그 일이 왜 생겼는지 · 그래서 어떻게 되었는지 — 글자를 다 쓰지 않고 화살표와 그림으로 적어도 됨',ARRAY['원인과 결과를 생각하며 보고 듣기(성취기준 번호 확인 필요)']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u6-C14','kor',4,2,'u6',4,'결과이면서 원인인 일 — 사슬 가운데의 일은 앞 일의 결과이면서 동시에 뒤 일의 원인 — 하나의 일이 두 몫을 함께 맡음',ARRAY['원인과 결과를 생각하며 보고 듣기(성취기준 번호 확인 필요)']::text[],14) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u6-C15','kor',4,2,'u6',4,'「두레박 줄」 — 끊어진 까닭 — 두레박 줄이 자꾸 끊어진 것은 줄이 나빠서가 아니라 우물 턱의 거칠게 깨진 돌에 쓸렸기 때문',ARRAY['원인과 결과를 생각하며 보고 듣기(성취기준 번호 확인 필요)']::text[],15) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u6-C16','kor',4,2,'u6',4,'까닭을 없애면 그 일도 없어짐 — 범수가 거친 돌을 헝겊으로 감싸자 줄이 끊어지지 않음 — 겉으로 드러난 일만 덮지 않고 까닭을 없앰',ARRAY['원인과 결과를 생각하며 보고 듣기(성취기준 번호 확인 필요)']::text[],16) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u6-C17','kor',4,2,'u6',4,'일이 일어난 차례대로 정리 — 일을 차례대로 놓고 보면 어디가 까닭이었는지가 드러남',ARRAY['원인과 결과를 생각하며 보고 듣기(성취기준 번호 확인 필요)']::text[],17) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u6-C18','kor',4,2,'u6',4,'짝은 여러 겹 — 한 이야기 안에 원인과 결과의 짝이 여러 개 들어 있음 — 짝을 여러 개 찾을수록 이야기가 더 잘 보임',ARRAY['원인과 결과를 생각하며 보고 듣기(성취기준 번호 확인 필요)']::text[],18) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u6-C19','kor',4,2,'u6',4,'원인이 하나뿐인 것은 아님 — 줄이 끊어진 데에는 거친 돌도 있었고, 까닭을 찾지 않고 줄만 바꾼 일도 있었음',ARRAY['원인과 결과를 생각하며 보고 듣기(성취기준 번호 확인 필요)']::text[],19) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u6-C20','kor',4,2,'u6',4,'이야기에 나온 일끼리만 잇기 — 원인과 결과의 짝은 이야기에 실제로 나온 일끼리만 이음 — 그럴듯해도 나오지 않은 일을 끌어오지 않음',ARRAY['원인과 결과를 생각하며 보고 듣기(성취기준 번호 확인 필요)']::text[],20) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u6-C21','kor',4,2,'u6',4,'말과 행동에 드러난 성격 — 한 말이 없어도 행동에서 성격이 보임 — 범수는 까닭을 찾을 때까지 꼼꼼히 살펴보는 아이',ARRAY['원인과 결과를 생각하며 보고 듣기(성취기준 번호 확인 필요)']::text[],21) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u6-C22','kor',4,2,'u6',4,'들으며 짧게 메모하기 — 나오는 사람 · 일어난 일 · 그 일의 까닭과 그다음을 짧게 — 화살표만 그어 두어도 나중에 되살아남',ARRAY['원인과 결과를 생각하며 보고 듣기(성취기준 번호 확인 필요)']::text[],22) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u6-C23','kor',4,2,'u6',4,'다른 이야기에도 세 물음 — 읽을 때마다 무슨 일이 일어났나 · 왜 일어났나 · 그래서 어떻게 되었나를 물음',ARRAY['원인과 결과를 생각하며 보고 듣기(성취기준 번호 확인 필요)']::text[],23) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u6-C24','kor',4,2,'u6',4,'스스로 확인하기 표 — 「아니요」가 나온 줄로 돌아가 다시 읽는 표 — 점수가 없음(「예」로 고치기 · 넘기기 ✗)',ARRAY['원인과 결과를 생각하며 보고 듣기(성취기준 번호 확인 필요)']::text[],24) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u6-C25','kor',4,2,'u6',6,'「연을 놓친 날」 — 앞 이야기의 까닭 — 바람이 세게 불어 실이 끊어졌고, 그래서 연이 미루나무 꼭대기 가지에 걸림',ARRAY['이어질 내용을 상상해 쓰기(성취기준 번호 확인 필요)']::text[],25) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u6-C26','kor',4,2,'u6',6,'방법 ① 인물의 성격 — 인물의 성격을 알면 앞으로 할 행동이 그려짐 — 성격은 따로 적혀 있지 않고 말과 행동 속에 있음',ARRAY['이어질 내용을 상상해 쓰기(성취기준 번호 확인 필요)']::text[],26) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u6-C27','kor',4,2,'u6',6,'방법 ② 이야기의 흐름 — 처음 · 가운데 · 지금을 차례대로 늘어놓으면 다음 칸이 보이기 시작함',ARRAY['이어질 내용을 상상해 쓰기(성취기준 번호 확인 필요)']::text[],27) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u6-C28','kor',4,2,'u6',6,'흐름에 맞는 다음 일 — 앞에서 이어져 온 이야기가 지금 묻고 있는 일(저 연을 어떻게 할까)로 이어짐 — 흐름과 상관없는 일 ✗',ARRAY['이어질 내용을 상상해 쓰기(성취기준 번호 확인 필요)']::text[],28) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u6-C29','kor',4,2,'u6',6,'방법 ③ 원인과 결과 — 상상한 일도 까닭이 있어야 이야기가 됨 — 「그래서」·「왜냐하면」을 넣어 말이 되면 이어진 것',ARRAY['이어질 내용을 상상해 쓰기(성취기준 번호 확인 필요)']::text[],29) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u6-C30','kor',4,2,'u6',6,'정답은 없지만 아무거나도 아님 — 이어질 내용에는 정답이 없어 친구와 아주 달라도 되지만, 앞에서 일어난 일이 까닭이 되어 그 일이 생겨야 함',ARRAY['이어질 내용을 상상해 쓰기(성취기준 번호 확인 필요)']::text[],30) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u6-C31','kor',4,2,'u6',6,'알맞지 않은 상상의 까닭 — 평범한지 · 글자 수가 적은지가 아니라 앞에 나온 성격·행동과 이어지지 않는지를 봄',ARRAY['이어질 내용을 상상해 쓰기(성취기준 번호 확인 필요)']::text[],31) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u6-C32','kor',4,2,'u6',6,'두 상상 견주기 — 더 놀라운 쪽이 아니라 성격도 흐름도 까닭도 앞과 더 이어지는 쪽을 고름',ARRAY['이어질 내용을 상상해 쓰기(성취기준 번호 확인 필요)']::text[],32) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u6-C33','kor',4,2,'u6',8,'끊긴 대목에서 시작 — 앞 이야기 칸으로 여기까지 있었던 일을 먼저 붙잡고, 인물의 성격 · 이야기의 흐름 · 원인과 결과 셋을 한꺼번에 씀',ARRAY['이어질 내용을 상상해 쓰기(성취기준 번호 확인 필요)']::text[],33) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u6-C34','kor',4,2,'u6',8,'「돌아온 우산」 — 일어난 일 — 잃어버린 우산이 교문 앞 은행나무에 걸려 돌아왔는데 손잡이에 없던 빨간 실 매듭이 묶여 있었음',ARRAY['이어질 내용을 상상해 쓰기(성취기준 번호 확인 필요)']::text[],34) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u6-C35','kor',4,2,'u6',8,'이야기 속 세 낱말 — 눈여겨보다(주의 깊게 자세히 보다) · 어리둥절하다(무슨 영문인지 몰라 얼떨떨하다) · 머뭇거리다(선뜻 하지 못하고 자꾸 망설이다) — 셋 다 인물의 마음',ARRAY['낱말의 뜻 알고 쓰기(성취기준 번호 확인 필요)']::text[],35) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u6-C36','kor',4,2,'u6',8,'누구를 따라가느냐 — 같은 일을 보고도 두 인물이 다르게 움직여서, 누구를 따라가느냐에 따라 이어질 내용이 달라짐',ARRAY['이어질 내용을 상상해 쓰기(성취기준 번호 확인 필요)']::text[],36) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u6-C37','kor',4,2,'u6',8,'성격을 이용한 상상 — 궁금하면 확인해야 잠이 오는 동규이라면 매듭을 맬 줄 아는 사람을 찾아 나섬 — 앞의 행동과 같은 결',ARRAY['이어질 내용을 상상해 쓰기(성취기준 번호 확인 필요)']::text[],37) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u6-C38','kor',4,2,'u6',8,'「돌아온 우산」의 원인과 결과 — 이름표가 없음 → 주운 사람이 임자를 바로 알 수 없음 · 매듭을 묶어 둠 → 임자가 알아볼 표시 · 효주가 알아봄 → 실마리',ARRAY['이어질 내용을 상상해 쓰기(성취기준 번호 확인 필요)']::text[],38) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u6-C39','kor',4,2,'u6',8,'가장 자연스러운 상상 고르기 — 인물이 앞의 모습 그대로 움직이는가 · 흐름에서 이어지는가 · 까닭이 앞에 있는가 — 「가장 놀라운 것」은 기준이 아님',ARRAY['이어질 내용을 상상해 쓰기(성취기준 번호 확인 필요)']::text[],39) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u6-C40','kor',4,2,'u6',8,'성격을 바꾸려면 까닭도 — 앞과 다른 성격으로 움직이게 하려면 왜 바뀌었는지를 함께 써야 함 — 바꾸었다고 선언만 하고 까닭을 안 쓰면 끊김',ARRAY['이어질 내용을 상상해 쓰기(성취기준 번호 확인 필요)']::text[],40) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
