INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u6-X03','kor',4,'u6',ARRAY['K4-2-u6-C3']::text[],'예상한 까닭을 앞 장면에서 찾지 않고 「그냥 그럴 것 같아서」·「더 재미있어서」로 댄다','이미 나와 있는 것') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u6-X04','kor',4,'u6',ARRAY['K4-2-u6-C4']::text[],'일을 옮길 때 빠진 것을 때와 곳·꾸미는 표현에서 찾고, 원인과 결과가 빠진 것은 보지 못한다','왜? 그래서?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u6-X05','kor',4,'u6',ARRAY['K4-2-u6-C5','K4-2-u6-C39']::text[],'이어질 내용을 상상할 때 「가장 놀라운 일이 무엇일까」를 가장 먼저 생각한다','앞 이야기에서 시작') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u6-X06','kor',4,'u6',ARRAY['K4-2-u6-C5']::text[],'이어질 내용을 상상할 때 「어떻게 하면 가장 길게 쓸까」를 가장 먼저 생각한다','길이가 아니라 까닭') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u6-X07','kor',4,'u6',ARRAY['K4-2-u6-C6','K4-2-u6-C7','K4-2-u6-C23']::text[],'영상이나 이야기를 넘기며 무슨 일이 일어났는지만 보고 왜·그래서는 따지지 않는다','넘기지 말고 따져요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u6-X08','kor',4,'u6',ARRAY['K4-2-u6-C8','K4-2-u6-C34']::text[],'장면이나 이야기에 나오지 않은 일을 짐작으로 덧붙여 일어난 일로 고른다','나와 있는 것만') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u6-X09','kor',4,'u6',ARRAY['K4-2-u6-C9','K4-2-u6-C38']::text[],'까닭이 달라져도 그다음 일은 같다고 여기거나, 원인과 그다음 일을 엇갈리게 잇는다','까닭에 맞는 다음 일') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u6-X10','kor',4,'u6',ARRAY['K4-2-u6-C9','K4-2-u6-C12']::text[],'있을 법한 까닭이 여럿인데도 정답인 까닭이 하나만 있다고 여긴다','까닭은 여럿일 수 있어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u6-X11','kor',4,'u6',ARRAY['K4-2-u6-C10']::text[],'예상과 견줄 때 「같아서 좋았다·달라서 아쉬웠다」처럼 느낌만 말한다','무엇을 까닭으로?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u6-X12','kor',4,'u6',ARRAY['K4-2-u6-C11']::text[],'장면을 보고 놀란 까닭을 장소가 아닌 엉뚱한 데(무서워서·조용해서)에서 찾는다','있을 만한 곳인가요?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u6-X13','kor',4,'u6',ARRAY['K4-2-u6-C12','K4-2-u6-C30']::text[],'장면에서 근거를 댈 수 없는 예상(마법·책을 읽고 싶어서)도 알맞은 예상이라 여긴다','까닭은 장면 안에') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u6-X14','kor',4,'u6',ARRAY['K4-2-u6-C13','K4-2-u6-C22']::text[],'메모는 보거나 들은 것을 한 글자도 빼지 않고 모두 받아 적는 것이라 여긴다','짧게 · 화살표') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u6-X15','kor',4,'u6',ARRAY['K4-2-u6-C18','K4-2-u6-C19']::text[],'원인과 결과의 짝을 하나만 찾고 끝내거나, 한 일의 원인은 하나뿐이라고 여긴다','짝은 여러 겹') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u6-X16','kor',4,'u6',ARRAY['K4-2-u6-C15','K4-2-u6-C19']::text[],'일이 일어난 까닭을 겉으로 보이는 것(줄이 나빠서·솜씨가 나빠서)에서만 찾는다','같은 곳에 난 자국') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u6-X17','kor',4,'u6',ARRAY['K4-2-u6-C16']::text[],'까닭을 없애려고 한 행동을 꾸미기처럼 엉뚱한 목적으로 여긴다','무엇을 없애려고?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u6-X18','kor',4,'u6',ARRAY['K4-2-u6-C20']::text[],'이야기에 나오지 않은 일을 끌어와 원인과 결과의 짝으로 잇는다','나온 일끼리만') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u6-X19','kor',4,'u6',ARRAY['K4-2-u6-C17']::text[],'일이 일어난 차례를 뒤섞어 놓는다','무엇이 먼저였나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u6-X20','kor',4,'u6',ARRAY['K4-2-u6-C21','K4-2-u6-C26']::text[],'성격을 말과 행동이 아닌 데서 짐작하거나, 한 말이 없으면 성격을 알 수 없다고 여긴다','행동에도 성격이') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u6-X21','kor',4,'u6',ARRAY['K4-2-u6-C24']::text[],'스스로 확인하기 표에서 「아니요」를 「예」로 고치거나 넘기거나 점수를 매긴다','그 줄로 돌아가요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u6-X22','kor',4,'u6',ARRAY['K4-2-u6-C25']::text[],'앞 이야기에서 일이 생긴 까닭을 바로 앞에 나온 일이 아닌 데서 찾는다','바로 앞에 무슨 일이?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u6-X23','kor',4,'u6',ARRAY['K4-2-u6-C26','K4-2-u6-C36']::text[],'인물의 말·행동과 성격을 엇갈리게 잇거나, 성격과 반대되는 행동을 그 인물다운 행동으로 고른다','이 사람이라면?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u6-X24','kor',4,'u6',ARRAY['K4-2-u6-C27','K4-2-u6-C28','K4-2-u6-C33']::text[],'지금까지의 흐름과 상관없는 일을 다음 일로 고르거나, 앞 이야기를 건너뛴다','지금 무엇을 묻나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u6-X25','kor',4,'u6',ARRAY['K4-2-u6-C30','K4-2-u6-C53']::text[],'이어질 내용에는 정답이 없으니 까닭 없이 아무거나 상상해도 된다고 여긴다','아무거나도 아니에요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u6-X26','kor',4,'u6',ARRAY['K4-2-u6-C30','K4-2-u6-C53']::text[],'이어질 내용에도 정해진 답이 하나 있어서 친구와 다르면 틀린 것이라 여긴다','정답은 없어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u6-X27','kor',4,'u6',ARRAY['K4-2-u6-C31']::text[],'상상이 알맞지 않은 까닭을 「너무 평범해서」에서 찾는다','평범함은 기준이 아니에요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u6-X28','kor',4,'u6',ARRAY['K4-2-u6-C31']::text[],'상상이 알맞은지를 글자 수나 문장 길이로 따진다','길이는 기준이 아니에요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u6-X29','kor',4,'u6',ARRAY['K4-2-u6-C32','K4-2-u6-C39']::text[],'더 놀랍고 신기한 상상이 더 알맞은 상상이라고 여긴다','더 이어지는 쪽') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u6-X30','kor',4,'u6',ARRAY['K4-2-u6-C35']::text[],'눈여겨보다 · 어리둥절하다 · 머뭇거리다의 뜻을 엇갈리게 안다','이야기 속 대목') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u6-X31','kor',4,'u6',ARRAY['K4-2-u6-C36']::text[],'같은 일을 보면 누구나 똑같이 움직여서 누구를 따라가도 이어질 내용이 같다고 여긴다','사람마다 달라요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u6-X32','kor',4,'u6',ARRAY['K4-2-u6-C40','K4-2-u6-C37']::text[],'인물의 성격을 바꾸어 놓고 왜 바뀌었는지는 쓰지 않은 상상을 알맞다고 여긴다','바뀐 까닭은?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u6-X33','kor',4,'u6',ARRAY['K4-2-u6-C41','K4-2-u6-C29']::text[],'뒷이야기에 그렇게 할 까닭이 앞에 없어도 까닭을 만들어 넣지 않고 그대로 쓴다','까닭을 먼저 넣어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u6-X34','kor',4,'u6',ARRAY['K4-2-u6-C42']::text[],'이야기 이어 말하기를 길게 말하는 사람이 이기는 놀이로 여긴다','끊기지 않게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u6-X35','kor',4,'u6',ARRAY['K4-2-u6-C43']::text[],'앞과 아무 상관 없는 일을 새로 꺼내도 이어진 것이라 여긴다','앞 문장이 까닭?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u6-X36','kor',4,'u6',ARRAY['K4-2-u6-C43']::text[],'까닭 없이 갑자기 큰일이 벌어지는 문장도 이어진 것이라 여긴다','갑자기는 까닭이 아니에요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u6-X37','kor',4,'u6',ARRAY['K4-2-u6-C43']::text[],'앞에서 이미 일어난 일을 없던 일로 돌리는 문장도 이어진 것이라 여긴다','끝난 일은 그대로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u6-X38','kor',4,'u6',ARRAY['K4-2-u6-C44']::text[],'역할놀이의 다음 대사를 인물의 성격과 상관없이 짓는다','그 인물이라면?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u6-X39','kor',4,'u6',ARRAY['K4-2-u6-C46']::text[],'역할놀이에서 가장 웃긴 모둠을 가장 먼저 살펴볼 것으로 여긴다','웃음보다 이어짐') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u6-X40','kor',4,'u6',ARRAY['K4-2-u6-C46','K4-2-u6-C45']::text[],'역할놀이에서 대사가 가장 긴 것을 가장 잘한 것으로 여긴다','길이는 기준이 아니에요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u6-X41','kor',4,'u6',ARRAY['K4-2-u6-C47','K4-2-u6-C48']::text[],'재료·수단·도구를 나타낼 자리에 (으)로서를 쓴다','무엇을 써서?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u6-X42','kor',4,'u6',ARRAY['K4-2-u6-C47','K4-2-u6-C48']::text[],'자격·신분을 나타낼 자리에 (으)로써를 쓴다','누구인가?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u6-X43','kor',4,'u6',ARRAY['K4-2-u6-C49']::text[],'눈여겨보다 · 어리둥절하다 · 머뭇거리다를 뜻에 맞지 않는 문장에 쓴다','뜻을 넣어 읽어 봐요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u6-X44','kor',4,'u6',ARRAY['K4-2-u6-C50']::text[],'겹받침 ㄵ을 [ㅈ]으로 읽거나 두 소리를 모두 내어 읽는다','ㄵ은 [ㄴ]') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u6-X45','kor',4,'u6',ARRAY['K4-2-u6-C51']::text[],'겹받침 ㄶ의 ㅎ을 빼고 읽어 뒤 소리와 합치지 않는다','ㅎ이 뒤 소리와 합쳐져요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u6-X46','kor',4,'u6',ARRAY['K4-2-u6-C52']::text[],'겹받침 낱말을 소리 나는 대로 적는다(안따 · 만타 · 괜찬타)','쓸 때는 그대로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u6-X47','kor',4,'u6',ARRAY['K4-2-u6-C52']::text[],'앉다(자리에 앉다)와 않다(하지 않다)를 섞어 쓴다','뜻이 달라요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u6-X48','kor',4,'u6',ARRAY['K4-2-u6-C54']::text[],'원인과 결과는 이야기 속에만 있다고 여기거나, 까닭을 찾지 않고 겉만 바꾸면 된다고 여긴다','생활 속에도 까닭') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u6-X49','kor',4,'u6',ARRAY['K4-2-u6-C53']::text[],'이어지려면 뻔한 일만 써야 하고, 새로우려면 앞과 달라져야 한다고 둘을 맞바꾸는 것으로 여긴다','함께 갈 수 있어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u6-X50','kor',4,'u6',ARRAY['K4-2-u6-C45']::text[],'역할놀이는 대사만 외우면 된다고 여겨 성격·까닭·몸짓을 정하지 않는다','성격 · 까닭 · 몸짓') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u6-X51','kor',4,'u6',ARRAY['K4-2-u6-C29','K4-2-u6-C42']::text[],'「그래서」를 넣어 읽어 어색한데도 이어진 것이라 여긴다','넣어서 말이 되나요?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_L02_basic#1','kor',4,2,'u6','L02','g4_2_kor_u6_L02_basic','lesson_basic','K4-2-u6-C1',1,'mc','auto','원인과 결과 가운데 「원인」의 뜻으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u6-X01','K4-2-u6-X04']::text[],false,'{"seq":1,"concept":"K4-2-u6-C1","difficulty":1,"kind":"mc","stem":"원인과 결과 가운데 「원인」의 뜻으로 알맞은 것은 무엇인가요?","options":[{"t":"일이 일어난 까닭","correct":true},{"t":"그래서 벌어진 일","mis":"K4-2-u6-X01"},{"t":"일이 일어난 때와 곳","mis":"K4-2-u6-X04"},{"t":"이야기를 재미있게 꾸미는 말","mis":"K4-2-u6-X04"}],"explanation":["「왜?」에 답하는 쪽이에요.","결과는 그래서 벌어진 일이에요.","원인은 까닭이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_L02_basic#2','kor',4,2,'u6','L02','g4_2_kor_u6_L02_basic','lesson_basic','K4-2-u6-C3',1,'mc','auto','㉰에 「효주가 비를 맞았다」를 예상했어요. 그렇게 생각한 까닭으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u6-X03','K4-2-u6-X13']::text[],false,'{"seq":2,"concept":"K4-2-u6-C3","difficulty":1,"kind":"mc","stem":"㉰에 「효주가 비를 맞았다」를 예상했어요. 그렇게 생각한 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"우산이 없는데 먹구름이 몰려왔다고 나와 있어서","correct":true},{"t":"그냥 그럴 것 같아서","mis":"K4-2-u6-X03"},{"t":"비 오는 이야기가 더 재미있어서","mis":"K4-2-u6-X03"},{"t":"효주가 비를 좋아할 것 같아서","mis":"K4-2-u6-X13"}],"explanation":["앞 장면을 다시 봐요.","우산 · 먹구름이 나와 있어요.","드러난 것에서 까닭을 대요."],"asset":{"type":"passage","lines":["㉮ 효주가 우산 없이 학교 문을 나섰다.","㉯ 하늘에 먹구름이 몰려오고 바람이 불었다.","㉰ ( ? )"],"title":"다음에 어떤 일이 일어날까요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_L02_basic#3','kor',4,2,'u6','L02','g4_2_kor_u6_L02_basic','lesson_basic','K4-2-u6-C4',1,'mc','auto','정후가 옮긴 학교 소식에서 빠진 것은 무엇인가요?',ARRAY['K4-2-u6-X04']::text[],false,'{"seq":3,"concept":"K4-2-u6-C4","difficulty":1,"kind":"mc","stem":"정후가 옮긴 학교 소식에서 빠진 것은 무엇인가요?","options":[{"t":"왜 그런 일이 생겼는지, 그래서 어떻게 되었는지","correct":true},{"t":"언제 어디에서 일어난 일인지","mis":"K4-2-u6-X04"},{"t":"재미있게 꾸며 주는 표현","mis":"K4-2-u6-X04"},{"t":"소방차가 무슨 색이었는지","mis":"K4-2-u6-X04"}],"explanation":["친구들이 무엇을 되물었나요?","「왜?」와 「그래서?」예요.","원인과 결과가 빠졌어요."],"asset":{"type":"speech","turns":[{"who":"정후","text":"얘들아, 어제 우리 학교 운동장에 소방차가 왔대!"},{"who":"동규","text":"왜? 무슨 일이 있었는데?"},{"who":"찬욱","text":"그래서 어떻게 됐는데?"},{"who":"정후","text":"그게⋯⋯ 그건 못 들었어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_L02_basic#4','kor',4,2,'u6','L02','g4_2_kor_u6_L02_basic','lesson_basic','K4-2-u6-C8',1,'ox','auto','영상 ㉮에서 「복도에서 물통이 깨졌다」는 이미 일어난 일로 나와 있어요.',ARRAY['K4-2-u6-X08']::text[],false,'{"seq":4,"concept":"K4-2-u6-C8","difficulty":1,"kind":"ox","stem":"영상 ㉮에서 「복도에서 물통이 깨졌다」는 이미 일어난 일로 나와 있어요.","answer":"X","reason_options":[{"t":"장면에는 젖은 발자국이 길게 이어져 있다는 것만 나와 있기 때문에","correct":true},{"t":"바닥이 젖었으니 물통이 깨진 것이 틀림없기 때문에","mis":"K4-2-u6-X08"}],"mis":"K4-2-u6-X08","explanation":["장면에 그대로 나와 있나요?","발자국만 나와 있어요.","그래서 X예요."],"asset":{"type":"passage","lines":["[장면] 점심시간이 끝난 급식실 앞 복도.","바닥에 젖은 발자국이 길게 이어져 있다.","지나가던 아이가 발을 멈추고 바닥을 내려다본다.","[말] \"어? 여기가 왜 이렇게 젖었지?\""],"title":"영상 ㉮ 급식실 앞 복도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_L02_basic#5','kor',4,2,'u6','L02','g4_2_kor_u6_L02_basic','lesson_basic','K4-2-u6-C1',2,'match','auto','원인과 결과를 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K4-2-u6-C1","difficulty":2,"kind":"match","stem":"원인과 결과를 알맞게 이으세요.","pairs":[{"l":"밤새 비가 많이 왔다","r":"운동장 구석에 웅덩이가 생겼다"},{"l":"교실 창문을 열어 두고 갔다","r":"아침에 책상 위 종이가 흩어져 있었다"},{"l":"화분을 볕이 드는 창가로 옮겼다","r":"시들던 잎이 다시 살아났다"}],"mis":"K4-2-u6-X01","explanation":["「그래서 어떻게 되었나」를 붙여 봐요.","비 → 웅덩이","볕 → 잎"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_L02_basic#6','kor',4,2,'u6','L02','g4_2_kor_u6_L02_basic','lesson_basic','K4-2-u6-C9',2,'mc','auto','영상 ㉮에서 바닥이 젖은 까닭을 「닦아 놓은 물이 아직 마르지 않았다」로 본다면, 그래서 할 일로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u6-X09']::text[],false,'{"seq":6,"concept":"K4-2-u6-C9","difficulty":2,"kind":"mc","stem":"영상 ㉮에서 바닥이 젖은 까닭을 「닦아 놓은 물이 아직 마르지 않았다」로 본다면, 그래서 할 일로 알맞은 것은 무엇인가요?","options":[{"t":"마를 때까지 미끄럼 조심 표시를 세운다","correct":true},{"t":"문 앞에 우산을 두는 곳을 만든다","mis":"K4-2-u6-X09"},{"t":"물통을 세워 담는 방법을 알려 준다","mis":"K4-2-u6-X09"},{"t":"까닭이 무엇이든 할 일은 똑같다","mis":"K4-2-u6-X09"}],"explanation":["그 까닭을 없애려면?","덜 마른 물이에요.","마를 때까지 조심해요."],"asset":{"type":"passage","lines":["[장면] 점심시간이 끝난 급식실 앞 복도.","바닥에 젖은 발자국이 길게 이어져 있다.","지나가던 아이가 발을 멈추고 바닥을 내려다본다.","[말] \"어? 여기가 왜 이렇게 젖었지?\""],"title":"영상 ㉮ 급식실 앞 복도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_L02_basic#7','kor',4,2,'u6','L02','g4_2_kor_u6_L02_basic','lesson_basic','K4-2-u6-C10',2,'mc','auto','영상 ㉮의 뒷부분을 보고 예상과 견주어 말한 것으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u6-X11','K4-2-u6-X10']::text[],false,'{"seq":7,"concept":"K4-2-u6-C10","difficulty":2,"kind":"mc","stem":"영상 ㉮의 뒷부분을 보고 예상과 견주어 말한 것으로 알맞은 것은 무엇인가요?","options":[{"t":"\"비가 왔을 거라고 예상했는데, 물통이 샌 것이어서 그 부분이 달랐다.\"","correct":true},{"t":"\"같아서 좋았다.\"","mis":"K4-2-u6-X11"},{"t":"\"달라서 아쉬웠다.\"","mis":"K4-2-u6-X11"},{"t":"\"예상이 틀렸으니 다음에는 예상하지 않겠다.\"","mis":"K4-2-u6-X10"}],"explanation":["느낌만 말하면 안 돼요.","무엇을 까닭으로 예상했나요?","어느 부분이 달랐나요?"],"asset":{"type":"passage","lines":["[장면] 아이가 발자국을 따라 걸어간다.","앞서 가던 아이의 가방 밑에서 물이 한 방울씩 떨어진다.","[말] \"물통 뚜껑이 열렸나 봐. 가방 좀 열어 봐.\""],"title":"영상 ㉮의 뒷부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_L02_basic#8','kor',4,2,'u6','L02','g4_2_kor_u6_L02_basic','lesson_basic','K4-2-u6-C11',2,'mc','auto','영상 ㉯를 보고 놀란 까닭으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u6-X12','K4-2-u6-X08']::text[],false,'{"seq":8,"concept":"K4-2-u6-C11","difficulty":2,"kind":"mc","stem":"영상 ㉯를 보고 놀란 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"도서관은 고양이가 있을 만한 곳이 아니어서","correct":true},{"t":"고양이가 무섭기 때문에","mis":"K4-2-u6-X12"},{"t":"도서관이 조용하기 때문에","mis":"K4-2-u6-X12"},{"t":"고양이가 책을 읽고 있었기 때문에","mis":"K4-2-u6-X08"}],"explanation":["고양이가 어디에 있나요?","있을 만한 곳인가요?","그래서 까닭이 궁금해져요."],"asset":{"type":"passage","lines":["[장면] 조용한 학교 도서관. 책꽂이가 줄지어 서 있다.","책꽂이 사이에 낯선 고양이 한 마리가 앉아 있다.","창문 하나가 한 뼘쯤 열려 있다.","[말] \"어⋯⋯ 어떻게 들어왔지?\""],"title":"영상 ㉯ 도서관 책꽂이 사이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_L02_basic#9','kor',4,2,'u6','L02','g4_2_kor_u6_L02_basic','lesson_basic','K4-2-u6-C2',2,'mc','auto','「창문을 한 뼘 열어 두었다 → ㉠ → 아이들이 창문을 열고 고양이를 내보냈다」에서 ㉠에 알맞은 것은 무엇인가요?',ARRAY['K4-2-u6-X02','K4-2-u6-X18','K4-2-u6-X37']::text[],false,'{"seq":9,"concept":"K4-2-u6-C2","difficulty":2,"kind":"mc","stem":"「창문을 한 뼘 열어 두었다 → ㉠ → 아이들이 창문을 열고 고양이를 내보냈다」에서 ㉠에 알맞은 것은 무엇인가요?","options":[{"t":"고양이가 그 틈으로 도서관에 들어왔다","correct":true},{"t":"그날 비가 많이 내렸다","mis":"K4-2-u6-X02"},{"t":"도서관에 새 책이 들어왔다","mis":"K4-2-u6-X18"},{"t":"아이들이 창문을 꼭 닫아 두었다","mis":"K4-2-u6-X37"}],"explanation":["㉠은 앞 일 때문에 생겼어요.","그리고 뒤의 일을 생기게 했어요.","고양이가 들어왔어요."],"asset":{"type":"passage","lines":["[장면] 조용한 학교 도서관. 책꽂이가 줄지어 서 있다.","책꽂이 사이에 낯선 고양이 한 마리가 앉아 있다.","창문 하나가 한 뼘쯤 열려 있다.","[말] \"어⋯⋯ 어떻게 들어왔지?\""],"title":"영상 ㉯ 도서관 책꽂이 사이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_L02_basic#10','kor',4,2,'u6','L02','g4_2_kor_u6_L02_basic','lesson_basic','K4-2-u6-C5',3,'mc','auto','이어질 내용을 상상할 때 가장 먼저 생각할 것은 무엇인가요?',ARRAY['K4-2-u6-X05','K4-2-u6-X06','K4-2-u6-X26']::text[],false,'{"seq":10,"concept":"K4-2-u6-C5","difficulty":3,"kind":"mc","stem":"이어질 내용을 상상할 때 가장 먼저 생각할 것은 무엇인가요?","options":[{"t":"앞에서 어떤 일이 왜 일어났나","correct":true},{"t":"가장 놀라운 일이 무엇일까","mis":"K4-2-u6-X05"},{"t":"어떻게 하면 가장 길게 쓸 수 있을까","mis":"K4-2-u6-X06"},{"t":"친구들이 가장 많이 고를 일이 무엇일까","mis":"K4-2-u6-X26"}],"explanation":["상상은 어디에서 시작하나요?","앞 이야기예요.","무슨 일이 왜 일어났는지 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_L02_challenge#1','kor',4,2,'u6','L02','g4_2_kor_u6_L02_challenge','lesson_challenge','K4-2-u6-C1',2,'sa','auto','일이 일어난 까닭을 「(  )」, 그래서 벌어진 일을 「결과」라고 해요. 빈칸에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K4-2-u6-C1","difficulty":2,"kind":"sa","stem":"일이 일어난 까닭을 「(  )」, 그래서 벌어진 일을 「결과」라고 해요. 빈칸에 알맞은 말을 쓰세요.","answer":["원인"],"explanation":["까닭을 부르는 말이에요.","결과와 짝이에요.","‘원인’이에요."],"mis":"K4-2-u6-X01"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_L02_challenge#2','kor',4,2,'u6','L02','g4_2_kor_u6_L02_challenge','lesson_challenge','K4-2-u6-C6',2,'mc','auto','이 단원에서 배울 두 가지(보고 들으며 원인과 결과 생각하기 · 이어질 내용 상상해 쓰기)가 함께 시작하는 곳은 어디인가요?',ARRAY['K4-2-u6-X07','K4-2-u6-X06','K4-2-u6-X05']::text[],false,'{"seq":2,"concept":"K4-2-u6-C6","difficulty":2,"kind":"mc","stem":"이 단원에서 배울 두 가지(보고 들으며 원인과 결과 생각하기 · 이어질 내용 상상해 쓰기)가 함께 시작하는 곳은 어디인가요?","options":[{"t":"까닭을 따져 보는 일","correct":true},{"t":"영상을 빠르게 넘기는 일","mis":"K4-2-u6-X07"},{"t":"이야기를 길게 쓰는 일","mis":"K4-2-u6-X06"},{"t":"가장 놀라운 일을 떠올리는 일","mis":"K4-2-u6-X05"}],"explanation":["두 가지 모두 「왜?」를 물어요.","까닭을 봐요.","까닭을 따져 보는 일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_L02_challenge#3','kor',4,2,'u6','L02','g4_2_kor_u6_L02_challenge','lesson_challenge','K4-2-u6-C12',3,'mc','auto','영상 ㉯를 보고 한 예상 가운데 장면에 드러난 것을 바탕으로 한 것은 무엇인가요?',ARRAY['K4-2-u6-X13','K4-2-u6-X25']::text[],false,'{"seq":3,"concept":"K4-2-u6-C12","difficulty":3,"kind":"mc","stem":"영상 ㉯를 보고 한 예상 가운데 장면에 드러난 것을 바탕으로 한 것은 무엇인가요?","options":[{"t":"열린 창문으로 들어왔을 것이다","correct":true},{"t":"고양이가 책을 읽고 싶어서 왔을 것이다","mis":"K4-2-u6-X13"},{"t":"고양이가 마법으로 벽을 지나왔을 것이다","mis":"K4-2-u6-X13"},{"t":"예상은 저마다 다르니 무엇을 골라도 까닭이 있는 것이다","mis":"K4-2-u6-X25"}],"explanation":["예상은 달라도 돼요.","까닭은 장면 안에서 찾아요.","창문이 열려 있었어요."],"asset":{"type":"passage","lines":["[장면] 조용한 학교 도서관. 책꽂이가 줄지어 서 있다.","책꽂이 사이에 낯선 고양이 한 마리가 앉아 있다.","창문 하나가 한 뼘쯤 열려 있다.","[말] \"어⋯⋯ 어떻게 들어왔지?\""],"title":"영상 ㉯ 도서관 책꽂이 사이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_L02_challenge#4','kor',4,2,'u6','L02','g4_2_kor_u6_L02_challenge','lesson_challenge','K4-2-u6-C9',3,'ox','auto','영상 ㉮에서 복도가 젖은 까닭은 하나로 정해져 있으니 그 하나만 맞히면 돼요.',ARRAY['K4-2-u6-X10']::text[],false,'{"seq":4,"concept":"K4-2-u6-C9","difficulty":3,"kind":"ox","stem":"영상 ㉮에서 복도가 젖은 까닭은 하나로 정해져 있으니 그 하나만 맞히면 돼요.","answer":"X","reason_options":[{"t":"비를 맞은 사람 · 새는 물통 · 덜 마른 물처럼 있을 법한 까닭이 여럿이기 때문에","correct":true},{"t":"영상에는 언제나 정답인 까닭이 하나만 있기 때문에","mis":"K4-2-u6-X10"}],"mis":"K4-2-u6-X10","explanation":["있을 법한 까닭을 떠올려요.","셋 다 있을 법해요.","그래서 X예요."],"asset":{"type":"passage","lines":["[장면] 점심시간이 끝난 급식실 앞 복도.","바닥에 젖은 발자국이 길게 이어져 있다.","지나가던 아이가 발을 멈추고 바닥을 내려다본다.","[말] \"어? 여기가 왜 이렇게 젖었지?\""],"title":"영상 ㉮ 급식실 앞 복도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_L02_challenge#5','kor',4,2,'u6','L02','g4_2_kor_u6_L02_challenge','lesson_challenge','K4-2-u6-C7',3,'mc','auto','영상을 보는 방법으로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-2-u6-X07','K4-2-u6-X14','K4-2-u6-X11']::text[],false,'{"seq":5,"concept":"K4-2-u6-C7","difficulty":3,"kind":"mc","stem":"영상을 보는 방법으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"무슨 일이 일어났는지, 왜 일어났는지, 그래서 어떻게 되었는지를 따져 본다","correct":true},{"t":"장면을 빠르게 넘기며 무슨 일인지만 본다","mis":"K4-2-u6-X07"},{"t":"본 것을 한 글자도 빼지 않고 공책에 옮겨 적는다","mis":"K4-2-u6-X14"},{"t":"예상한 것과 같으면 좋았다고만 말한다","mis":"K4-2-u6-X11"}],"explanation":["넘기는 것이 아니에요.","따져 보는 것이에요.","무슨 일 → 왜 → 그래서"],"asset":{"type":"passage","lines":["[장면] 아침 교실. 칠판 아래 바닥에 하얀 분필 가루가 흩어져 있다.","창문 하나가 활짝 열려 있고 커튼이 크게 펄럭인다.","[말] \"어제 분명히 깨끗하게 치웠는데⋯⋯.\""],"title":"영상 ㉰ 아침 교실"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_L02_challenge#6','kor',4,2,'u6','L02','g4_2_kor_u6_L02_challenge','lesson_challenge','K4-2-u6-C13',3,'mc','auto','영상 ㉰를 보면서 메모한 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-2-u6-X14','K4-2-u6-X07']::text[],false,'{"seq":6,"concept":"K4-2-u6-C13","difficulty":3,"kind":"mc","stem":"영상 ㉰를 보면서 메모한 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"분필 가루 흩어짐 ← 창문 열림·바람? → 창문 닫고 받침 닦기","correct":true},{"t":"말과 장면을 한 글자도 빼지 않고 모두 받아 적었다","mis":"K4-2-u6-X14"},{"t":"글자를 다 쓸 수 없어서 아무것도 적지 않았다","mis":"K4-2-u6-X14"},{"t":"커튼 색깔과 무늬만 그림으로 그렸다","mis":"K4-2-u6-X07"}],"explanation":["큰 사건 · 왜 · 그래서","짧게 적어요.","화살표도 좋아요."],"asset":{"type":"passage","lines":["[장면] 아침 교실. 칠판 아래 바닥에 하얀 분필 가루가 흩어져 있다.","창문 하나가 활짝 열려 있고 커튼이 크게 펄럭인다.","[말] \"어제 분명히 깨끗하게 치웠는데⋯⋯.\""],"title":"영상 ㉰ 아침 교실"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_L02_challenge#7','kor',4,2,'u6','L02','g4_2_kor_u6_L02_challenge','lesson_challenge','K4-2-u6-C2',3,'mc','auto','「밤새 비가 많이 왔다 → 운동장 구석에 웅덩이가 생겼다 → 체육 시간을 강당에서 했다」에서 「웅덩이가 생겼다」를 바르게 말한 것은 무엇인가요?',ARRAY['K4-2-u6-X02','K4-2-u6-X18']::text[],false,'{"seq":7,"concept":"K4-2-u6-C2","difficulty":3,"kind":"mc","stem":"「밤새 비가 많이 왔다 → 운동장 구석에 웅덩이가 생겼다 → 체육 시간을 강당에서 했다」에서 「웅덩이가 생겼다」를 바르게 말한 것은 무엇인가요?","options":[{"t":"앞 일의 결과이면서 뒤 일의 원인이다","correct":true},{"t":"원인일 뿐 결과는 아니다","mis":"K4-2-u6-X02"},{"t":"결과일 뿐 원인은 아니다","mis":"K4-2-u6-X02"},{"t":"앞뒤 일과 상관없는 일이다","mis":"K4-2-u6-X18"}],"explanation":["앞을 보고 한 번","뒤를 보고 한 번","두 몫을 함께 맡아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_L02_challenge#8','kor',4,2,'u6','L02','g4_2_kor_u6_L02_challenge','lesson_challenge','K4-2-u6-C10',4,'essay','teacher','영상 ㉮의 앞부분만 보고 「비를 맞고 들어온 사람이 지나갔다」고 예상했어요. 뒷부분을 본 뒤 예상과 견주어 말하는 문장을 쓰고, 「달라서 아쉬웠다」라고만 말하면 안 되는 까닭을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K4-2-u6-C10","difficulty":4,"kind":"essay","stem":"영상 ㉮의 앞부분만 보고 「비를 맞고 들어온 사람이 지나갔다」고 예상했어요. 뒷부분을 본 뒤 예상과 견주어 말하는 문장을 쓰고, 「달라서 아쉬웠다」라고만 말하면 안 되는 까닭을 쓰세요.","answer_guide":{"answer":"예: 「젖은 발자국을 까닭으로 비 맞은 사람이 지나갔다고 예상했는데, 가방 속 물통이 새서 생긴 것이어서 그 부분이 달랐다.」 「달라서 아쉬웠다」는 느낌만 말해서 무엇을 까닭으로 예상했는지, 어느 부분이 달랐는지가 드러나지 않기 때문이다.","scoring_points":["무엇을 까닭으로 예상했는지 썼는가","어느 부분이 같았는지·달랐는지 썼는가","느낌만 말하면 안 되는 까닭을 썼는가"]},"explanation":["무엇을 까닭으로?","어느 부분이 달랐나?","느낌만으로는 안 돼요."],"asset":{"type":"passage","lines":["[장면] 아이가 발자국을 따라 걸어간다.","앞서 가던 아이의 가방 밑에서 물이 한 방울씩 떨어진다.","[말] \"물통 뚜껑이 열렸나 봐. 가방 좀 열어 봐.\""],"title":"영상 ㉮의 뒷부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_L02_challenge#9','kor',4,2,'u6','L02','g4_2_kor_u6_L02_challenge','lesson_challenge','K4-2-u6-C11',4,'essay','teacher','영상 ㉯의 중심 사건(책꽂이 사이에 고양이가 앉아 있었다)을 가운데에 두고, 앞에 있었을 일(원인)과 뒤에 벌어질 일(결과)을 하나씩 쓰세요. 원인은 장면에서 근거를 들어 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K4-2-u6-C11","difficulty":4,"kind":"essay","stem":"영상 ㉯의 중심 사건(책꽂이 사이에 고양이가 앉아 있었다)을 가운데에 두고, 앞에 있었을 일(원인)과 뒤에 벌어질 일(결과)을 하나씩 쓰세요. 원인은 장면에서 근거를 들어 쓰세요.","answer_guide":{"answer":"예: 앞 — 한 뼘쯤 열린 창문 틈으로 고양이가 들어왔다(장면에 창문이 열려 있다고 나와 있다). 뒤 — 아이들이 선생님께 알리고 창문을 넓게 열어 고양이가 밖으로 나가게 했다.","scoring_points":["앞에 있었을 일(원인)을 썼는가","원인의 근거를 장면에서 찾았는가","뒤에 벌어질 일(결과)을 썼는가"]},"explanation":["가운데를 붙잡아요.","앞으로 한 번, 뒤로 한 번","근거는 장면 안에"],"asset":{"type":"passage","lines":["[장면] 조용한 학교 도서관. 책꽂이가 줄지어 서 있다.","책꽂이 사이에 낯선 고양이 한 마리가 앉아 있다.","창문 하나가 한 뼘쯤 열려 있다.","[말] \"어⋯⋯ 어떻게 들어왔지?\""],"title":"영상 ㉯ 도서관 책꽂이 사이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_L02_challenge#10','kor',4,2,'u6','L02','g4_2_kor_u6_L02_challenge','lesson_challenge','K4-2-u6-C4',4,'essay','teacher','기억에 남는 학교 소식을 하나 골라 원인과 결과가 모두 드러나게 두 문장으로 쓰세요. 그리고 정후처럼 원인과 결과를 빼고 말하면 친구가 무엇을 되물을지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K4-2-u6-C4","difficulty":4,"kind":"essay","stem":"기억에 남는 학교 소식을 하나 골라 원인과 결과가 모두 드러나게 두 문장으로 쓰세요. 그리고 정후처럼 원인과 결과를 빼고 말하면 친구가 무엇을 되물을지 쓰세요.","answer_guide":{"answer":"예: 「어제 체육 창고 문이 고장 나서 잠기지 않았다. 그래서 오늘 체육 시간 전에 선생님께서 공을 다시 세어 보셨다.」 원인과 결과를 빼고 「어제 체육 창고에 무슨 일이 있었대」라고만 하면 친구는 「왜?」, 「그래서 어떻게 됐는데?」 하고 되물을 것이다.","scoring_points":["원인이 드러나게 썼는가","결과가 드러나게 썼는가","친구가 되물을 말(왜?·그래서?)을 썼는가"]},"explanation":["왜 일어났나요?","그래서 어떻게 되었나요?","빠지면 되물어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_L04_basic#1','kor',4,2,'u6','L04','g4_2_kor_u6_L04_basic','lesson_basic','K4-2-u6-C15',1,'mc','auto','「두레박 줄」에서 두레박 줄이 자꾸 끊어진 까닭은 무엇인가요?',ARRAY['K4-2-u6-X16','K4-2-u6-X18']::text[],false,'{"seq":1,"concept":"K4-2-u6-C15","difficulty":1,"kind":"mc","stem":"「두레박 줄」에서 두레박 줄이 자꾸 끊어진 까닭은 무엇인가요?","options":[{"t":"우물 턱의 거칠게 깨진 돌에 줄이 쓸렸기 때문에","correct":true},{"t":"줄을 만든 솜씨가 나빴기 때문에","mis":"K4-2-u6-X16"},{"t":"두레박이 너무 무거웠기 때문에","mis":"K4-2-u6-X16"},{"t":"우물이 너무 깊었기 때문에","mis":"K4-2-u6-X18"}],"explanation":["끊어진 자국이 어디에 났나요?","늘 같은 곳이에요.","거친 돌에 쓸렸어요."],"asset":{"type":"passage","lines":["옛날 어느 마을 한가운데에 깊은 우물이 하나 있었어요.","언제부터인가 두레박 줄이 자꾸 끊어졌어요. 새 줄도 열흘을 못 갔어요.","\"줄이 나쁜가 보다.\" 사람들은 줄만 바꾸고 또 바꾸었어요.","범수는 끊어진 자국이 늘 같은 곳에 나 있는 것을 눈여겨보았어요.","우물 턱의 돌 한 귀퉁이가 칼날처럼 거칠게 깨져 있었지요.","범수는 헌 옷을 잘라 그 돌을 두껍게 감쌌어요.","그 뒤로 줄은 한 해가 지나도 끊어지지 않았어요."],"title":"두레박 줄"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_L04_basic#2','kor',4,2,'u6','L04','g4_2_kor_u6_L04_basic','lesson_basic','K4-2-u6-C16',1,'mc','auto','범수가 우물 턱의 돌을 헝겊으로 두껍게 감싼 까닭은 무엇인가요?',ARRAY['K4-2-u6-X17']::text[],false,'{"seq":2,"concept":"K4-2-u6-C16","difficulty":1,"kind":"mc","stem":"범수가 우물 턱의 돌을 헝겊으로 두껍게 감싼 까닭은 무엇인가요?","options":[{"t":"줄이 거친 돌에 쓸리지 않게 하려고","correct":true},{"t":"우물을 보기 좋게 꾸미려고","mis":"K4-2-u6-X17"},{"t":"우물물이 얼지 않게 하려고","mis":"K4-2-u6-X17"},{"t":"사람들이 우물에 오지 못하게 하려고","mis":"K4-2-u6-X17"}],"explanation":["무엇을 없애려고 했나요?","줄을 끊는 것은 거친 돌이에요.","까닭을 없앴어요."],"asset":{"type":"passage","lines":["옛날 어느 마을 한가운데에 깊은 우물이 하나 있었어요.","언제부터인가 두레박 줄이 자꾸 끊어졌어요. 새 줄도 열흘을 못 갔어요.","\"줄이 나쁜가 보다.\" 사람들은 줄만 바꾸고 또 바꾸었어요.","범수는 끊어진 자국이 늘 같은 곳에 나 있는 것을 눈여겨보았어요.","우물 턱의 돌 한 귀퉁이가 칼날처럼 거칠게 깨져 있었지요.","범수는 헌 옷을 잘라 그 돌을 두껍게 감쌌어요.","그 뒤로 줄은 한 해가 지나도 끊어지지 않았어요."],"title":"두레박 줄"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_L04_basic#3','kor',4,2,'u6','L04','g4_2_kor_u6_L04_basic','lesson_basic','K4-2-u6-C21',1,'ox','auto','「두레박 줄」에서 범수가 한 말은 하나도 없으니 범수가 어떤 아이인지 알 수 없어요.',ARRAY['K4-2-u6-X20']::text[],false,'{"seq":3,"concept":"K4-2-u6-C21","difficulty":1,"kind":"ox","stem":"「두레박 줄」에서 범수가 한 말은 하나도 없으니 범수가 어떤 아이인지 알 수 없어요.","answer":"X","reason_options":[{"t":"끊어진 줄을 눈여겨보고 돌을 살핀 행동에서 성격이 보이기 때문에","correct":true},{"t":"성격은 인물이 한 말에만 드러나기 때문에","mis":"K4-2-u6-X20"}],"mis":"K4-2-u6-X20","explanation":["범수가 한 행동을 봐요.","행동에도 성격이 있어요.","그래서 X예요."],"asset":{"type":"passage","lines":["옛날 어느 마을 한가운데에 깊은 우물이 하나 있었어요.","언제부터인가 두레박 줄이 자꾸 끊어졌어요. 새 줄도 열흘을 못 갔어요.","\"줄이 나쁜가 보다.\" 사람들은 줄만 바꾸고 또 바꾸었어요.","범수는 끊어진 자국이 늘 같은 곳에 나 있는 것을 눈여겨보았어요.","우물 턱의 돌 한 귀퉁이가 칼날처럼 거칠게 깨져 있었지요.","범수는 헌 옷을 잘라 그 돌을 두껍게 감쌌어요.","그 뒤로 줄은 한 해가 지나도 끊어지지 않았어요."],"title":"두레박 줄"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_L04_basic#4','kor',4,2,'u6','L04','g4_2_kor_u6_L04_basic','lesson_basic','K4-2-u6-C14',1,'mc','auto','①~④에서 ②를 바르게 말한 것은 무엇인가요?',ARRAY['K4-2-u6-X02','K4-2-u6-X18']::text[],false,'{"seq":4,"concept":"K4-2-u6-C14","difficulty":1,"kind":"mc","stem":"①~④에서 ②를 바르게 말한 것은 무엇인가요?","options":[{"t":"①의 결과이면서 ③의 원인이다","correct":true},{"t":"원인이기만 하다","mis":"K4-2-u6-X02"},{"t":"결과이기만 하다","mis":"K4-2-u6-X02"},{"t":"①, ③과 상관없는 일이다","mis":"K4-2-u6-X18"}],"explanation":["②의 앞을 봐요.","②의 뒤를 봐요.","두 몫을 함께 맡아요."],"asset":{"type":"passage","lines":["① 밤새 비가 많이 내렸다.","② 아침 등굣길 흙길이 질척였다.","③ 신발과 양말이 흠뻑 젖었다.","④ 교실 뒤에 신문지를 깔고 신발을 말렸다."]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_L04_basic#5','kor',4,2,'u6','L04','g4_2_kor_u6_L04_basic','lesson_basic','K4-2-u6-C18',2,'match','auto','「두레박 줄」에서 원인과 결과를 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K4-2-u6-C18","difficulty":2,"kind":"match","stem":"「두레박 줄」에서 원인과 결과를 알맞게 이으세요.","pairs":[{"l":"우물 턱의 돌이 거칠게 깨졌다","r":"두레박 줄이 같은 곳에서 쓸려 끊어졌다"},{"l":"사람들이 까닭을 찾지 않고 줄만 바꾸었다","r":"열흘마다 같은 일이 되풀이되었다"},{"l":"범수가 거친 돌을 헝겊으로 감쌌다","r":"한 해가 지나도 줄이 끊어지지 않았다"}],"mis":"K4-2-u6-X15","explanation":["「그래서 어떻게 되었나」를 붙여요.","한 이야기에 짝이 여러 겹이에요.","셋 다 이어요."],"asset":{"type":"passage","lines":["옛날 어느 마을 한가운데에 깊은 우물이 하나 있었어요.","언제부터인가 두레박 줄이 자꾸 끊어졌어요. 새 줄도 열흘을 못 갔어요.","\"줄이 나쁜가 보다.\" 사람들은 줄만 바꾸고 또 바꾸었어요.","범수는 끊어진 자국이 늘 같은 곳에 나 있는 것을 눈여겨보았어요.","우물 턱의 돌 한 귀퉁이가 칼날처럼 거칠게 깨져 있었지요.","범수는 헌 옷을 잘라 그 돌을 두껍게 감쌌어요.","그 뒤로 줄은 한 해가 지나도 끊어지지 않았어요."],"title":"두레박 줄"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_L04_basic#6','kor',4,2,'u6','L04','g4_2_kor_u6_L04_basic','lesson_basic','K4-2-u6-C17',2,'mc','auto','「두레박 줄」에서 일이 일어난 차례로 가장 먼저 일어난 일은 무엇인가요?',ARRAY['K4-2-u6-X19']::text[],false,'{"seq":6,"concept":"K4-2-u6-C17","difficulty":2,"kind":"mc","stem":"「두레박 줄」에서 일이 일어난 차례로 가장 먼저 일어난 일은 무엇인가요?","options":[{"t":"우물 턱의 돌 한 귀퉁이가 거칠게 깨졌다","correct":true},{"t":"두레박 줄이 그 돌에 쓸려 자꾸 끊어졌다","mis":"K4-2-u6-X19"},{"t":"마을 사람들이 줄만 바꾸었다","mis":"K4-2-u6-X19"},{"t":"범수가 끊어진 자국을 눈여겨보았다","mis":"K4-2-u6-X19"}],"explanation":["줄이 끊어지기 전에 무엇이 있었나요?","깨진 돌이 먼저예요.","차례로 놓으면 까닭이 보여요."],"asset":{"type":"passage","lines":["옛날 어느 마을 한가운데에 깊은 우물이 하나 있었어요.","언제부터인가 두레박 줄이 자꾸 끊어졌어요. 새 줄도 열흘을 못 갔어요.","\"줄이 나쁜가 보다.\" 사람들은 줄만 바꾸고 또 바꾸었어요.","범수는 끊어진 자국이 늘 같은 곳에 나 있는 것을 눈여겨보았어요.","우물 턱의 돌 한 귀퉁이가 칼날처럼 거칠게 깨져 있었지요.","범수는 헌 옷을 잘라 그 돌을 두껍게 감쌌어요.","그 뒤로 줄은 한 해가 지나도 끊어지지 않았어요."],"title":"두레박 줄"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_L04_basic#7','kor',4,2,'u6','L04','g4_2_kor_u6_L04_basic','lesson_basic','K4-2-u6-C20',2,'mc','auto','「두레박 줄」에서 찾을 수 있는 원인과 결과의 짝은 무엇인가요?',ARRAY['K4-2-u6-X18']::text[],false,'{"seq":7,"concept":"K4-2-u6-C20","difficulty":2,"kind":"mc","stem":"「두레박 줄」에서 찾을 수 있는 원인과 결과의 짝은 무엇인가요?","options":[{"t":"줄이 쓸려서 → 열흘마다 끊어졌다","correct":true},{"t":"우물이 깊어서 → 돌이 깨졌다","mis":"K4-2-u6-X18"},{"t":"헝겊이 두꺼워서 → 우물물이 늘었다","mis":"K4-2-u6-X18"},{"t":"두레박이 무거워서 → 우물 턱이 깨졌다","mis":"K4-2-u6-X18"}],"explanation":["이야기에 실제로 나온 일인가요?","나온 일끼리만 이어요.","쓸림 → 끊어짐"],"asset":{"type":"passage","lines":["옛날 어느 마을 한가운데에 깊은 우물이 하나 있었어요.","언제부터인가 두레박 줄이 자꾸 끊어졌어요. 새 줄도 열흘을 못 갔어요.","\"줄이 나쁜가 보다.\" 사람들은 줄만 바꾸고 또 바꾸었어요.","범수는 끊어진 자국이 늘 같은 곳에 나 있는 것을 눈여겨보았어요.","우물 턱의 돌 한 귀퉁이가 칼날처럼 거칠게 깨져 있었지요.","범수는 헌 옷을 잘라 그 돌을 두껍게 감쌌어요.","그 뒤로 줄은 한 해가 지나도 끊어지지 않았어요."],"title":"두레박 줄"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_L04_basic#8','kor',4,2,'u6','L04','g4_2_kor_u6_L04_basic','lesson_basic','K4-2-u6-C21',2,'mc','auto','「두레박 줄」의 범수는 어떤 성격의 아이인가요?',ARRAY['K4-2-u6-X20','K4-2-u6-X23']::text[],false,'{"seq":8,"concept":"K4-2-u6-C21","difficulty":2,"kind":"mc","stem":"「두레박 줄」의 범수는 어떤 성격의 아이인가요?","options":[{"t":"까닭을 찾을 때까지 꼼꼼히 살펴본다","correct":true},{"t":"힘이 세고 겁이 없다","mis":"K4-2-u6-X20"},{"t":"장난치는 것을 좋아한다","mis":"K4-2-u6-X20"},{"t":"남이 하는 대로 줄만 바꾼다","mis":"K4-2-u6-X23"}],"explanation":["범수가 무엇을 했나요?","자국을 눈여겨보고 돌을 쓸어 보았어요.","꼼꼼히 살피는 아이예요."],"asset":{"type":"passage","lines":["옛날 어느 마을 한가운데에 깊은 우물이 하나 있었어요.","언제부터인가 두레박 줄이 자꾸 끊어졌어요. 새 줄도 열흘을 못 갔어요.","\"줄이 나쁜가 보다.\" 사람들은 줄만 바꾸고 또 바꾸었어요.","범수는 끊어진 자국이 늘 같은 곳에 나 있는 것을 눈여겨보았어요.","우물 턱의 돌 한 귀퉁이가 칼날처럼 거칠게 깨져 있었지요.","범수는 헌 옷을 잘라 그 돌을 두껍게 감쌌어요.","그 뒤로 줄은 한 해가 지나도 끊어지지 않았어요."],"title":"두레박 줄"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_L04_basic#9','kor',4,2,'u6','L04','g4_2_kor_u6_L04_basic','lesson_basic','K4-2-u6-C22',2,'mc','auto','이야기를 들으며 메모할 때 적어 두면 좋은 것은 무엇인가요?',ARRAY['K4-2-u6-X14','K4-2-u6-X07','K4-2-u6-X15']::text[],false,'{"seq":9,"concept":"K4-2-u6-C22","difficulty":2,"kind":"mc","stem":"이야기를 들으며 메모할 때 적어 두면 좋은 것은 무엇인가요?","options":[{"t":"나오는 사람, 일어난 일, 그 일의 까닭과 그다음","correct":true},{"t":"들은 문장을 처음부터 끝까지 그대로","mis":"K4-2-u6-X14"},{"t":"읽어 주는 사람의 목소리가 어땠는지","mis":"K4-2-u6-X07"},{"t":"일어난 일 하나만","mis":"K4-2-u6-X15"}],"explanation":["이야기는 지나가 버려요.","짧게 적어요.","사람 · 일 · 까닭 · 그다음"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_L04_basic#10','kor',4,2,'u6','L04','g4_2_kor_u6_L04_basic','lesson_basic','K4-2-u6-C19',3,'mc','auto','「두레박 줄」에서 줄이 자꾸 끊어진 까닭을 가장 알맞게 말한 것은 무엇인가요?',ARRAY['K4-2-u6-X15','K4-2-u6-X16']::text[],false,'{"seq":10,"concept":"K4-2-u6-C19","difficulty":3,"kind":"mc","stem":"「두레박 줄」에서 줄이 자꾸 끊어진 까닭을 가장 알맞게 말한 것은 무엇인가요?","options":[{"t":"거친 돌도 까닭이고, 까닭을 찾지 않고 줄만 바꾼 일도 까닭이다","correct":true},{"t":"까닭은 거친 돌 하나뿐이다","mis":"K4-2-u6-X15"},{"t":"까닭은 줄이 나쁜 것 하나뿐이다","mis":"K4-2-u6-X16"},{"t":"까닭이 여럿이면 잘못 쓴 이야기다","mis":"K4-2-u6-X15"}],"explanation":["까닭이 하나뿐일까요?","열흘마다 되풀이된 까닭도 있어요.","둘 다 까닭이에요."],"asset":{"type":"passage","lines":["옛날 어느 마을 한가운데에 깊은 우물이 하나 있었어요.","언제부터인가 두레박 줄이 자꾸 끊어졌어요. 새 줄도 열흘을 못 갔어요.","\"줄이 나쁜가 보다.\" 사람들은 줄만 바꾸고 또 바꾸었어요.","범수는 끊어진 자국이 늘 같은 곳에 나 있는 것을 눈여겨보았어요.","우물 턱의 돌 한 귀퉁이가 칼날처럼 거칠게 깨져 있었지요.","범수는 헌 옷을 잘라 그 돌을 두껍게 감쌌어요.","그 뒤로 줄은 한 해가 지나도 끊어지지 않았어요."],"title":"두레박 줄"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_L04_challenge#1','kor',4,2,'u6','L04','g4_2_kor_u6_L04_challenge','lesson_challenge','K4-2-u6-C14',2,'sa','auto','①~④ 가운데 앞 일의 결과이면서 뒤 일의 원인이 되는 것을 하나 골라 번호로 쓰세요(① 말고).','{}'::text[],false,'{"seq":1,"concept":"K4-2-u6-C14","difficulty":2,"kind":"sa","stem":"①~④ 가운데 앞 일의 결과이면서 뒤 일의 원인이 되는 것을 하나 골라 번호로 쓰세요(① 말고).","answer":["②","③","2","3","②번","③번","2번","3번"],"explanation":["맨 앞은 결과가 아니에요.","맨 끝은 원인이 아니에요.","가운데 둘이에요."],"asset":{"type":"passage","lines":["① 밤새 비가 많이 내렸다.","② 아침 등굣길 흙길이 질척였다.","③ 신발과 양말이 흠뻑 젖었다.","④ 교실 뒤에 신문지를 깔고 신발을 말렸다."]},"mis":"K4-2-u6-X02"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_L04_challenge#2','kor',4,2,'u6','L04','g4_2_kor_u6_L04_challenge','lesson_challenge','K4-2-u6-C23',2,'mc','auto','다른 이야기를 읽을 때에도 원인과 결과를 찾으려면 무엇을 물으면 되나요?',ARRAY['K4-2-u6-X07','K4-2-u6-X15']::text[],false,'{"seq":2,"concept":"K4-2-u6-C23","difficulty":2,"kind":"mc","stem":"다른 이야기를 읽을 때에도 원인과 결과를 찾으려면 무엇을 물으면 되나요?","options":[{"t":"무슨 일이 일어났나 · 왜 일어났나 · 그래서 어떻게 되었나","correct":true},{"t":"누가 나왔나 · 몇 쪽인가 · 누가 썼나","mis":"K4-2-u6-X07"},{"t":"어디가 웃긴가 · 어디가 슬픈가 · 어디가 긴가","mis":"K4-2-u6-X07"},{"t":"무슨 일이 일어났나, 하나만","mis":"K4-2-u6-X15"}],"explanation":["세 가지를 물어요.","왜? 그래서?","어느 이야기에도 똑같이요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_L04_challenge#3','kor',4,2,'u6','L04','g4_2_kor_u6_L04_challenge','lesson_challenge','K4-2-u6-C18',3,'mc','auto','「늦게 가는 시계」에서 찾을 수 있는 원인과 결과의 짝은 무엇인가요?',ARRAY['K4-2-u6-X18','K4-2-u6-X01','K4-2-u6-X09']::text[],false,'{"seq":3,"concept":"K4-2-u6-C18","difficulty":3,"kind":"mc","stem":"「늦게 가는 시계」에서 찾을 수 있는 원인과 결과의 짝은 무엇인가요?","options":[{"t":"건전지가 헐겁게 빠져 있어서 → 시계가 늦게 갔다","correct":true},{"t":"시계가 오래돼서 → 건전지가 빠졌다","mis":"K4-2-u6-X18"},{"t":"급식실에 늦게 도착해서 → 시계가 늦게 갔다","mis":"K4-2-u6-X01"},{"t":"다은이가 부탁해서 → 시계가 늦게 갔다","mis":"K4-2-u6-X09"}],"explanation":["이야기에 나온 일인가요?","무엇이 먼저였나요?","건전지 → 늦은 시계"],"asset":{"type":"passage","lines":["우리 반 벽시계는 언제부터인가 조금씩 늦게 갔어요.","그래서 시계를 보고 움직인 날은 급식실에 늘 꼴찌로 도착했지요.","\"시계가 오래돼서 그래.\" 아이들은 그렇게만 말했어요.","다은이는 선생님께 시계를 내려 달라고 부탁해 뒤쪽 건전지 칸을 열어 보았어요.","건전지 한 개가 헐겁게 빠져 있었어요.","다은이가 건전지를 꾹 눌러 끼우자 초바늘이 다시 힘차게 돌았어요."],"title":"늦게 가는 시계"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_L04_challenge#4','kor',4,2,'u6','L04','g4_2_kor_u6_L04_challenge','lesson_challenge','K4-2-u6-C16',3,'mc','auto','다은이가 건전지를 꾹 눌러 끼운 일과 같은 방법은 무엇인가요?',ARRAY['K4-2-u6-X17','K4-2-u6-X16','K4-2-u6-X48']::text[],false,'{"seq":4,"concept":"K4-2-u6-C16","difficulty":3,"kind":"mc","stem":"다은이가 건전지를 꾹 눌러 끼운 일과 같은 방법은 무엇인가요?","options":[{"t":"까닭을 없애서 그 일이 다시 일어나지 않게 했다","correct":true},{"t":"겉모습을 바꾸어 보기 좋게 했다","mis":"K4-2-u6-X17"},{"t":"까닭은 그대로 두고 늦게 간 시간만 맞추어 두었다","mis":"K4-2-u6-X16"},{"t":"까닭을 찾지 않고 새 시계를 사 오자고 했다","mis":"K4-2-u6-X48"}],"explanation":["범수가 한 일과 견주어 봐요.","헐거운 건전지가 까닭이에요.","까닭을 없앴어요."],"asset":{"type":"passage","lines":["우리 반 벽시계는 언제부터인가 조금씩 늦게 갔어요.","그래서 시계를 보고 움직인 날은 급식실에 늘 꼴찌로 도착했지요.","\"시계가 오래돼서 그래.\" 아이들은 그렇게만 말했어요.","다은이는 선생님께 시계를 내려 달라고 부탁해 뒤쪽 건전지 칸을 열어 보았어요.","건전지 한 개가 헐겁게 빠져 있었어요.","다은이가 건전지를 꾹 눌러 끼우자 초바늘이 다시 힘차게 돌았어요."],"title":"늦게 가는 시계"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_L04_challenge#5','kor',4,2,'u6','L04','g4_2_kor_u6_L04_challenge','lesson_challenge','K4-2-u6-C21',3,'mc','auto','「늦게 가는 시계」의 다은이는 어떤 아이인가요?',ARRAY['K4-2-u6-X20']::text[],false,'{"seq":5,"concept":"K4-2-u6-C21","difficulty":3,"kind":"mc","stem":"「늦게 가는 시계」의 다은이는 어떤 아이인가요?","options":[{"t":"말로만 넘기지 않고 직접 까닭을 살펴보는 아이","correct":true},{"t":"남의 말을 그대로 따르는 아이","mis":"K4-2-u6-X20"},{"t":"겁이 많아 아무것도 하지 않는 아이","mis":"K4-2-u6-X20"},{"t":"시계를 싫어하는 아이","mis":"K4-2-u6-X20"}],"explanation":["아이들은 「오래돼서」라고만 했어요.","다은이는 무엇을 했나요?","건전지 칸을 열어 보았어요."],"asset":{"type":"passage","lines":["우리 반 벽시계는 언제부터인가 조금씩 늦게 갔어요.","그래서 시계를 보고 움직인 날은 급식실에 늘 꼴찌로 도착했지요.","\"시계가 오래돼서 그래.\" 아이들은 그렇게만 말했어요.","다은이는 선생님께 시계를 내려 달라고 부탁해 뒤쪽 건전지 칸을 열어 보았어요.","건전지 한 개가 헐겁게 빠져 있었어요.","다은이가 건전지를 꾹 눌러 끼우자 초바늘이 다시 힘차게 돌았어요."],"title":"늦게 가는 시계"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_L04_challenge#6','kor',4,2,'u6','L04','g4_2_kor_u6_L04_challenge','lesson_challenge','K4-2-u6-C24',3,'mc','auto','「한 이야기에서 원인과 결과의 짝을 여러 개 찾을 수 있다」에 「아니요」가 나왔어요. 다음에 할 일로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u6-X21']::text[],false,'{"seq":6,"concept":"K4-2-u6-C24","difficulty":3,"kind":"mc","stem":"「한 이야기에서 원인과 결과의 짝을 여러 개 찾을 수 있다」에 「아니요」가 나왔어요. 다음에 할 일로 알맞은 것은 무엇인가요?","options":[{"t":"그 줄로 돌아가 이야기를 다시 읽으며 짝을 더 찾아본다","correct":true},{"t":"「예」로 고쳐 표시해 둔다","mis":"K4-2-u6-X21"},{"t":"그 줄은 넘기고 다음 줄만 본다","mis":"K4-2-u6-X21"},{"t":"점수를 매겨 친구 것과 견준다","mis":"K4-2-u6-X21"}],"explanation":["이 표는 점수가 없어요.","고칠 곳을 찾는 표예요.","그 줄로 돌아가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_L04_challenge#7','kor',4,2,'u6','L04','g4_2_kor_u6_L04_challenge','lesson_challenge','K4-2-u6-C17',3,'mc','auto','「늦게 가는 시계」의 일을 일어난 차례대로 알맞게 놓은 것은 무엇인가요?',ARRAY['K4-2-u6-X19','K4-2-u6-X01']::text[],false,'{"seq":7,"concept":"K4-2-u6-C17","difficulty":3,"kind":"mc","stem":"「늦게 가는 시계」의 일을 일어난 차례대로 알맞게 놓은 것은 무엇인가요?","options":[{"t":"건전지가 헐거워졌다 → 시계가 늦게 갔다 → 급식실에 늘 꼴찌로 도착했다","correct":true},{"t":"시계가 늦게 갔다 → 건전지가 헐거워졌다 → 급식실에 꼴찌로 도착했다","mis":"K4-2-u6-X19"},{"t":"급식실에 꼴찌로 도착했다 → 시계가 늦게 갔다 → 건전지가 헐거워졌다","mis":"K4-2-u6-X01"},{"t":"건전지가 헐거워졌다 → 급식실에 꼴찌로 도착했다 → 시계가 늦게 갔다","mis":"K4-2-u6-X19"}],"explanation":["무엇이 먼저였나요?","까닭이 앞에 와요.","건전지 → 시계 → 급식실"],"asset":{"type":"passage","lines":["우리 반 벽시계는 언제부터인가 조금씩 늦게 갔어요.","그래서 시계를 보고 움직인 날은 급식실에 늘 꼴찌로 도착했지요.","\"시계가 오래돼서 그래.\" 아이들은 그렇게만 말했어요.","다은이는 선생님께 시계를 내려 달라고 부탁해 뒤쪽 건전지 칸을 열어 보았어요.","건전지 한 개가 헐겁게 빠져 있었어요.","다은이가 건전지를 꾹 눌러 끼우자 초바늘이 다시 힘차게 돌았어요."],"title":"늦게 가는 시계"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_L04_challenge#8','kor',4,2,'u6','L04','g4_2_kor_u6_L04_challenge','lesson_challenge','K4-2-u6-C19',4,'essay','teacher','「두레박 줄」에서 줄이 끊어진 까닭을 두 가지 쓰고, 줄만 바꾼 마을 사람들과 범수가 어떻게 달랐는지 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K4-2-u6-C19","difficulty":4,"kind":"essay","stem":"「두레박 줄」에서 줄이 끊어진 까닭을 두 가지 쓰고, 줄만 바꾼 마을 사람들과 범수가 어떻게 달랐는지 쓰세요.","answer_guide":{"answer":"예: 첫째, 우물 턱의 돌이 거칠게 깨져 줄이 쓸렸다. 둘째, 사람들이 까닭을 찾지 않고 줄만 바꾸어 같은 일이 되풀이되었다. 마을 사람들은 끊어진 줄만 보았지만, 범수는 끊어진 자국이 같은 곳에 난 것을 보고 까닭을 찾아 없앴다.","scoring_points":["까닭 두 가지를 썼는가","마을 사람들이 한 일을 썼는가","범수가 까닭을 찾아 없앤 점을 견주어 썼는가"]},"explanation":["까닭은 하나뿐이 아니에요.","줄만 바꾸면?","까닭을 찾으면?"],"asset":{"type":"passage","lines":["옛날 어느 마을 한가운데에 깊은 우물이 하나 있었어요.","언제부터인가 두레박 줄이 자꾸 끊어졌어요. 새 줄도 열흘을 못 갔어요.","\"줄이 나쁜가 보다.\" 사람들은 줄만 바꾸고 또 바꾸었어요.","범수는 끊어진 자국이 늘 같은 곳에 나 있는 것을 눈여겨보았어요.","우물 턱의 돌 한 귀퉁이가 칼날처럼 거칠게 깨져 있었지요.","범수는 헌 옷을 잘라 그 돌을 두껍게 감쌌어요.","그 뒤로 줄은 한 해가 지나도 끊어지지 않았어요."],"title":"두레박 줄"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_L04_challenge#9','kor',4,2,'u6','L04','g4_2_kor_u6_L04_challenge','lesson_challenge','K4-2-u6-C18',4,'essay','teacher','「늦게 가는 시계」에서 원인과 결과의 짝을 두 개 이상 찾아 「~해서 → ~했다」 꼴로 쓰고, 그 가운데 결과가 다시 원인이 된 것을 하나 골라 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K4-2-u6-C18","difficulty":4,"kind":"essay","stem":"「늦게 가는 시계」에서 원인과 결과의 짝을 두 개 이상 찾아 「~해서 → ~했다」 꼴로 쓰고, 그 가운데 결과가 다시 원인이 된 것을 하나 골라 쓰세요.","answer_guide":{"answer":"예: 건전지가 헐겁게 빠져 있어서 → 시계가 늦게 갔다. 시계가 늦게 가서 → 급식실에 늘 꼴찌로 도착했다. 다은이가 건전지를 눌러 끼워서 → 초바늘이 다시 힘차게 돌았다. 「시계가 늦게 갔다」는 앞 일의 결과이면서 급식실에 늦은 일의 원인이다.","scoring_points":["짝을 두 개 이상 썼는가","이야기에 나온 일끼리 이었는가","결과이면서 원인인 일을 골랐는가"]},"explanation":["짝은 여러 겹이에요.","나온 일끼리 이어요.","두 몫을 맡은 일을 찾아요."],"asset":{"type":"passage","lines":["우리 반 벽시계는 언제부터인가 조금씩 늦게 갔어요.","그래서 시계를 보고 움직인 날은 급식실에 늘 꼴찌로 도착했지요.","\"시계가 오래돼서 그래.\" 아이들은 그렇게만 말했어요.","다은이는 선생님께 시계를 내려 달라고 부탁해 뒤쪽 건전지 칸을 열어 보았어요.","건전지 한 개가 헐겁게 빠져 있었어요.","다은이가 건전지를 꾹 눌러 끼우자 초바늘이 다시 힘차게 돌았어요."],"title":"늦게 가는 시계"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_L04_challenge#10','kor',4,2,'u6','L04','g4_2_kor_u6_L04_challenge','lesson_challenge','K4-2-u6-C22',4,'essay','teacher','「두레박 줄」을 선생님이 읽어 주신다고 생각하고, 들으며 적을 메모를 화살표를 써서 짧게 쓰세요. 그리고 짧게 적어도 되는 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K4-2-u6-C22","difficulty":4,"kind":"essay","stem":"「두레박 줄」을 선생님이 읽어 주신다고 생각하고, 들으며 적을 메모를 화살표를 써서 짧게 쓰세요. 그리고 짧게 적어도 되는 까닭을 쓰세요.","answer_guide":{"answer":"예: 범수 / 두레박 줄 자꾸 끊어짐 ← 우물 턱 돌 깨짐 / 줄만 바꿈 → 되풀이 / 범수 돌 감쌈 → 안 끊어짐. 이야기는 지나가 버리지만 화살표만 그어 두어도 나중에 무슨 일이 왜 일어났는지 되살아나기 때문이다.","scoring_points":["나오는 사람과 일어난 일을 적었는가","까닭과 그다음을 화살표로 이었는가","짧게 적어도 되는 까닭을 썼는가"]},"explanation":["사람 · 일 · 까닭 · 그다음","화살표를 써요.","나중에 되살아나요."],"asset":{"type":"passage","lines":["옛날 어느 마을 한가운데에 깊은 우물이 하나 있었어요.","언제부터인가 두레박 줄이 자꾸 끊어졌어요. 새 줄도 열흘을 못 갔어요.","\"줄이 나쁜가 보다.\" 사람들은 줄만 바꾸고 또 바꾸었어요.","범수는 끊어진 자국이 늘 같은 곳에 나 있는 것을 눈여겨보았어요.","우물 턱의 돌 한 귀퉁이가 칼날처럼 거칠게 깨져 있었지요.","범수는 헌 옷을 잘라 그 돌을 두껍게 감쌌어요.","그 뒤로 줄은 한 해가 지나도 끊어지지 않았어요."],"title":"두레박 줄"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_L06_basic#1','kor',4,2,'u6','L06','g4_2_kor_u6_L06_basic','lesson_basic','K4-2-u6-C25',1,'mc','auto','「연을 놓친 날」에서 연이 미루나무에 걸린 까닭은 무엇인가요?',ARRAY['K4-2-u6-X22']::text[],false,'{"seq":1,"concept":"K4-2-u6-C25","difficulty":1,"kind":"mc","stem":"「연을 놓친 날」에서 연이 미루나무에 걸린 까닭은 무엇인가요?","options":[{"t":"바람이 세게 불어 실이 끊어졌기 때문에","correct":true},{"t":"연을 잘못 만들었기 때문에","mis":"K4-2-u6-X22"},{"t":"미루나무가 너무 높기 때문에","mis":"K4-2-u6-X22"},{"t":"경민이가 연을 일부러 놓았기 때문에","mis":"K4-2-u6-X22"}],"explanation":["연이 걸리기 바로 앞을 봐요.","실이 끊어졌어요.","바람이 셌어요."],"asset":{"type":"passage","lines":["경민이는 한번 하기로 한 것은 끝을 봐야 하는 아이였어요.","겨울 방학 내내 연살을 곱게 깎아 연 하나를 만들었지요.","\"이번엔 저 미루나무보다 높이 올릴 거야.\"","바람이 유난히 세게 불던 날, 경민이는 둑에 나가 연을 올렸어요.","얼레를 더 풀었을 때, 툭. 실이 끊어졌어요.","연은 빙글빙글 돌더니 미루나무 꼭대기 가지에 걸리고 말았어요.","경민이는 나무 아래에서 한참을 올려다보기만 했어요.","해는 벌써 둑 너머로 기울고 있었지요."],"title":"연을 놓친 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_L06_basic#2','kor',4,2,'u6','L06','g4_2_kor_u6_L06_basic','lesson_basic','K4-2-u6-C26',1,'mc','auto','이야기에서 인물의 성격은 주로 어디에서 알 수 있나요?',ARRAY['K4-2-u6-X20','K4-2-u6-X28']::text[],false,'{"seq":2,"concept":"K4-2-u6-C26","difficulty":1,"kind":"mc","stem":"이야기에서 인물의 성격은 주로 어디에서 알 수 있나요?","options":[{"t":"인물의 말과 행동 속에서","correct":true},{"t":"이야기의 제목에서","mis":"K4-2-u6-X20"},{"t":"이야기의 길이에서","mis":"K4-2-u6-X28"},{"t":"글 맨 끝에 따로 적힌 설명에서만","mis":"K4-2-u6-X20"}],"explanation":["성격은 따로 적혀 있지 않아요.","무엇을 말하고 했나요?","말과 행동 속에 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_L06_basic#3','kor',4,2,'u6','L06','g4_2_kor_u6_L06_basic','lesson_basic','K4-2-u6-C30',1,'ox','auto','이어질 내용에는 정답이 없으니 아무거나 써도 돼요.',ARRAY['K4-2-u6-X25']::text[],false,'{"seq":3,"concept":"K4-2-u6-C30","difficulty":1,"kind":"ox","stem":"이어질 내용에는 정답이 없으니 아무거나 써도 돼요.","answer":"X","reason_options":[{"t":"정답은 없지만 앞에서 일어난 일이 까닭이 되어 이어져야 하기 때문에","correct":true},{"t":"상상은 앞 이야기와 상관없을수록 좋기 때문에","mis":"K4-2-u6-X25"}],"mis":"K4-2-u6-X25","explanation":["정답은 없어요.","그런데 아무거나도 아니에요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_L06_basic#4','kor',4,2,'u6','L06','g4_2_kor_u6_L06_basic','lesson_basic','K4-2-u6-C29',1,'mc','auto','상상한 일이 앞 이야기와 이어지는지 알아보는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u6-X28','K4-2-u6-X29','K4-2-u6-X26']::text[],false,'{"seq":4,"concept":"K4-2-u6-C29","difficulty":1,"kind":"mc","stem":"상상한 일이 앞 이야기와 이어지는지 알아보는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"「그래서」나 「왜냐하면」을 넣어 말이 되는지 본다","correct":true},{"t":"글자 수를 세어 본다","mis":"K4-2-u6-X28"},{"t":"가장 놀라운지 따져 본다","mis":"K4-2-u6-X29"},{"t":"친구들이 몇 명이나 같은 생각인지 센다","mis":"K4-2-u6-X26"}],"explanation":["속으로 넣어 봐요.","말이 되면 이어진 것이에요.","어색하면 끊어진 것이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_L06_basic#5','kor',4,2,'u6','L06','g4_2_kor_u6_L06_basic','lesson_basic','K4-2-u6-C26',2,'match','auto','경민이의 말이나 행동과 짐작되는 성격을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K4-2-u6-C26","difficulty":2,"kind":"match","stem":"경민이의 말이나 행동과 짐작되는 성격을 알맞게 이으세요.","pairs":[{"l":"겨울 방학 내내 연 하나를 만들었다","r":"한번 시작하면 끝까지 한다"},{"l":"나무 아래에서 한참을 올려다보기만 했다","r":"쉽게 포기하지 못한다"},{"l":"「이번엔 저 미루나무보다 높이 올릴 거야.」","r":"목표를 정해 두고 해낸다"}],"mis":"K4-2-u6-X23","explanation":["그 말을 한 사람은 어떤 사람일까요?","행동에도 성격이 있어요.","셋 다 이어요."],"asset":{"type":"passage","lines":["경민이는 한번 하기로 한 것은 끝을 봐야 하는 아이였어요.","겨울 방학 내내 연살을 곱게 깎아 연 하나를 만들었지요.","\"이번엔 저 미루나무보다 높이 올릴 거야.\"","바람이 유난히 세게 불던 날, 경민이는 둑에 나가 연을 올렸어요.","얼레를 더 풀었을 때, 툭. 실이 끊어졌어요.","연은 빙글빙글 돌더니 미루나무 꼭대기 가지에 걸리고 말았어요.","경민이는 나무 아래에서 한참을 올려다보기만 했어요.","해는 벌써 둑 너머로 기울고 있었지요."],"title":"연을 놓친 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_L06_basic#6','kor',4,2,'u6','L06','g4_2_kor_u6_L06_basic','lesson_basic','K4-2-u6-C28',2,'mc','auto','「연을 놓친 날」의 흐름에 가장 알맞은 다음 일은 무엇인가요?',ARRAY['K4-2-u6-X24','K4-2-u6-X36']::text[],false,'{"seq":6,"concept":"K4-2-u6-C28","difficulty":2,"kind":"mc","stem":"「연을 놓친 날」의 흐름에 가장 알맞은 다음 일은 무엇인가요?","options":[{"t":"경민이가 연을 내릴 방법을 찾기 시작했다","correct":true},{"t":"경민이가 새 학기에 반장이 되었다","mis":"K4-2-u6-X24"},{"t":"경민이가 집에 가서 저녁을 맛있게 먹었다","mis":"K4-2-u6-X24"},{"t":"갑자기 연이 스스로 날아 내려와 경민이 손에 앉았다","mis":"K4-2-u6-X36"}],"explanation":["지금 이야기가 무엇을 묻나요?","「저 연을 어떻게 할까」예요.","그 물음에 이어져요."],"asset":{"type":"passage","lines":["경민이는 한번 하기로 한 것은 끝을 봐야 하는 아이였어요.","겨울 방학 내내 연살을 곱게 깎아 연 하나를 만들었지요.","\"이번엔 저 미루나무보다 높이 올릴 거야.\"","바람이 유난히 세게 불던 날, 경민이는 둑에 나가 연을 올렸어요.","얼레를 더 풀었을 때, 툭. 실이 끊어졌어요.","연은 빙글빙글 돌더니 미루나무 꼭대기 가지에 걸리고 말았어요.","경민이는 나무 아래에서 한참을 올려다보기만 했어요.","해는 벌써 둑 너머로 기울고 있었지요."],"title":"연을 놓친 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_L06_basic#7','kor',4,2,'u6','L06','g4_2_kor_u6_L06_basic','lesson_basic','K4-2-u6-C31',2,'mc','auto','「경민이가 연을 잊어버리고 다시는 생각하지 않았다」가 알맞지 않은 까닭은 무엇인가요?',ARRAY['K4-2-u6-X27','K4-2-u6-X28','K4-2-u6-X29']::text[],false,'{"seq":7,"concept":"K4-2-u6-C31","difficulty":2,"kind":"mc","stem":"「경민이가 연을 잊어버리고 다시는 생각하지 않았다」가 알맞지 않은 까닭은 무엇인가요?","options":[{"t":"앞에 나온 경민이의 성격·행동과 이어지지 않아서","correct":true},{"t":"너무 평범해서","mis":"K4-2-u6-X27"},{"t":"글자 수가 너무 적어서","mis":"K4-2-u6-X28"},{"t":"연 이야기가 끝나서 재미없어서","mis":"K4-2-u6-X29"}],"explanation":["평범한지는 따지지 않아요.","길이도 따지지 않아요.","끝을 봐야 하는 아이였어요."],"asset":{"type":"passage","lines":["경민이는 한번 하기로 한 것은 끝을 봐야 하는 아이였어요.","겨울 방학 내내 연살을 곱게 깎아 연 하나를 만들었지요.","\"이번엔 저 미루나무보다 높이 올릴 거야.\"","바람이 유난히 세게 불던 날, 경민이는 둑에 나가 연을 올렸어요.","얼레를 더 풀었을 때, 툭. 실이 끊어졌어요.","연은 빙글빙글 돌더니 미루나무 꼭대기 가지에 걸리고 말았어요.","경민이는 나무 아래에서 한참을 올려다보기만 했어요.","해는 벌써 둑 너머로 기울고 있었지요."],"title":"연을 놓친 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_L06_basic#8','kor',4,2,'u6','L06','g4_2_kor_u6_L06_basic','lesson_basic','K4-2-u6-C32',2,'mc','auto','두 친구가 상상한 뒷이야기 가운데 더 자연스럽게 이어지는 쪽과 그 까닭으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u6-X29','K4-2-u6-X28','K4-2-u6-X25']::text[],false,'{"seq":8,"concept":"K4-2-u6-C32","difficulty":2,"kind":"mc","stem":"두 친구가 상상한 뒷이야기 가운데 더 자연스럽게 이어지는 쪽과 그 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"㉮ — 성격도 흐름도 까닭도 앞과 이어지기 때문에","correct":true},{"t":"㉯ — 더 놀랍고 신기하기 때문에","mis":"K4-2-u6-X29"},{"t":"㉮ — 문장이 더 길기 때문에","mis":"K4-2-u6-X28"},{"t":"둘 다 상상이니 견줄 수 없다","mis":"K4-2-u6-X25"}],"explanation":["더 놀라운 쪽이 아니에요.","앞의 경민이와 같은 사람인가요?","더 이어지는 쪽이에요."],"asset":{"type":"passage","lines":["㉮ 경민이는 다음 날 아침 일찍 둑에 나가 긴 장대를 들고 다시 나무 아래에 섰다.","㉯ 그때 하늘에서 커다란 용이 내려와 연을 물어다 경민이에게 주었다."],"title":"두 친구가 상상한 뒷이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_L06_basic#9','kor',4,2,'u6','L06','g4_2_kor_u6_L06_basic','lesson_basic','K4-2-u6-C27',2,'mc','auto','이야기의 흐름을 살피는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u6-X24']::text[],false,'{"seq":9,"concept":"K4-2-u6-C27","difficulty":2,"kind":"mc","stem":"이야기의 흐름을 살피는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"처음 · 가운데 · 지금까지 있었던 일을 차례대로 늘어놓아 본다","correct":true},{"t":"마지막 문장만 다시 읽는다","mis":"K4-2-u6-X24"},{"t":"가장 재미있는 장면만 고른다","mis":"K4-2-u6-X24"},{"t":"인물의 이름만 적어 본다","mis":"K4-2-u6-X24"}],"explanation":["어디까지 왔나요?","차례대로 늘어놓아요.","다음 칸이 보여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_L06_basic#10','kor',4,2,'u6','L06','g4_2_kor_u6_L06_basic','lesson_basic','K4-2-u6-C30',3,'mc','auto','이어질 내용을 상상하는 일에 대해 알맞게 말한 것은 무엇인가요?',ARRAY['K4-2-u6-X26','K4-2-u6-X25','K4-2-u6-X29']::text[],false,'{"seq":10,"concept":"K4-2-u6-C30","difficulty":3,"kind":"mc","stem":"이어질 내용을 상상하는 일에 대해 알맞게 말한 것은 무엇인가요?","options":[{"t":"친구와 아주 다른 이야기여도 앞의 일이 까닭이 되면 괜찮다","correct":true},{"t":"친구와 다른 이야기를 쓰면 틀린 것이다","mis":"K4-2-u6-X26"},{"t":"까닭이 없어도 재미있으면 괜찮다","mis":"K4-2-u6-X25"},{"t":"놀라운 일일수록 더 잘 이어진다","mis":"K4-2-u6-X29"}],"explanation":["정답은 없어요.","아무거나도 아니에요.","가르는 것은 까닭이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_L06_challenge#1','kor',4,2,'u6','L06','g4_2_kor_u6_L06_challenge','lesson_challenge','K4-2-u6-C29',2,'sa','auto','이어질 내용을 상상할 때 살펴볼 세 가지는 인물의 성격, 이야기의 흐름, 「(   )과 결과」예요. 빈칸에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K4-2-u6-C29","difficulty":2,"kind":"sa","stem":"이어질 내용을 상상할 때 살펴볼 세 가지는 인물의 성격, 이야기의 흐름, 「(   )과 결과」예요. 빈칸에 알맞은 말을 쓰세요.","answer":["원인"],"explanation":["까닭을 부르는 말이에요.","결과와 짝이에요.","‘원인’이에요."],"mis":"K4-2-u6-X33"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_L06_challenge#2','kor',4,2,'u6','L06','g4_2_kor_u6_L06_challenge','lesson_challenge','K4-2-u6-C25',2,'mc','auto','「연을 놓친 날」 끝에 「해는 벌써 둑 너머로 기울고 있었지요.」가 나와요. 이 문장이 이어질 일의 까닭이 될 수 있는 것은 무엇인가요?',ARRAY['K4-2-u6-X22','K4-2-u6-X36','K4-2-u6-X32']::text[],false,'{"seq":2,"concept":"K4-2-u6-C25","difficulty":2,"kind":"mc","stem":"「연을 놓친 날」 끝에 「해는 벌써 둑 너머로 기울고 있었지요.」가 나와요. 이 문장이 이어질 일의 까닭이 될 수 있는 것은 무엇인가요?","options":[{"t":"곧 어두워져 오늘은 연을 내리기 어렵다는 것","correct":true},{"t":"바람이 더 세게 분다는 것","mis":"K4-2-u6-X22"},{"t":"연이 저절로 내려온다는 것","mis":"K4-2-u6-X36"},{"t":"경민이가 연을 잊게 된다는 것","mis":"K4-2-u6-X32"}],"explanation":["해가 기울면 어떻게 되나요?","곧 어두워져요.","그것이 다음 일의 까닭이에요."],"asset":{"type":"passage","lines":["경민이는 한번 하기로 한 것은 끝을 봐야 하는 아이였어요.","겨울 방학 내내 연살을 곱게 깎아 연 하나를 만들었지요.","\"이번엔 저 미루나무보다 높이 올릴 거야.\"","바람이 유난히 세게 불던 날, 경민이는 둑에 나가 연을 올렸어요.","얼레를 더 풀었을 때, 툭. 실이 끊어졌어요.","연은 빙글빙글 돌더니 미루나무 꼭대기 가지에 걸리고 말았어요.","경민이는 나무 아래에서 한참을 올려다보기만 했어요.","해는 벌써 둑 너머로 기울고 있었지요."],"title":"연을 놓친 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_L06_challenge#3','kor',4,2,'u6','L06','g4_2_kor_u6_L06_challenge','lesson_challenge','K4-2-u6-C29',3,'mc','auto','「연을 놓친 날」 뒤에 「그래서」를 넣어 이어 읽었을 때 말이 되는 것은 무엇인가요?',ARRAY['K4-2-u6-X51','K4-2-u6-X32','K4-2-u6-X35']::text[],false,'{"seq":3,"concept":"K4-2-u6-C29","difficulty":3,"kind":"mc","stem":"「연을 놓친 날」 뒤에 「그래서」를 넣어 이어 읽었을 때 말이 되는 것은 무엇인가요?","options":[{"t":"해가 져서 내일 다시 오기로 하고 나무에 표시를 해 두었다","correct":true},{"t":"갑자기 연이 스스로 날아 내려와 경민이 손에 앉았다","mis":"K4-2-u6-X51"},{"t":"경민이가 연을 잊어버리고 다시는 생각하지 않았다","mis":"K4-2-u6-X32"},{"t":"경민이 동생이 그날 학교에서 상을 받았다","mis":"K4-2-u6-X35"}],"explanation":["「그래서」를 붙여 읽어요.","앞의 일이 까닭이 되나요?","해가 진 것이 까닭이에요."],"asset":{"type":"passage","lines":["경민이는 한번 하기로 한 것은 끝을 봐야 하는 아이였어요.","겨울 방학 내내 연살을 곱게 깎아 연 하나를 만들었지요.","\"이번엔 저 미루나무보다 높이 올릴 거야.\"","바람이 유난히 세게 불던 날, 경민이는 둑에 나가 연을 올렸어요.","얼레를 더 풀었을 때, 툭. 실이 끊어졌어요.","연은 빙글빙글 돌더니 미루나무 꼭대기 가지에 걸리고 말았어요.","경민이는 나무 아래에서 한참을 올려다보기만 했어요.","해는 벌써 둑 너머로 기울고 있었지요."],"title":"연을 놓친 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_L06_challenge#4','kor',4,2,'u6','L06','g4_2_kor_u6_L06_challenge','lesson_challenge','K4-2-u6-C30',3,'mc','auto','세 친구가 상상한 「빈 새집」의 뒷이야기 가운데 앞 이야기와 자연스럽게 이어지는 것은 무엇인가요?',ARRAY['K4-2-u6-X25','K4-2-u6-X32']::text[],false,'{"seq":4,"concept":"K4-2-u6-C30","difficulty":3,"kind":"mc","stem":"세 친구가 상상한 「빈 새집」의 뒷이야기 가운데 앞 이야기와 자연스럽게 이어지는 것은 무엇인가요?","options":[{"t":"㉮ 담장 쪽 나무로 새집을 옮겼다","correct":true},{"t":"㉯ 새들이 꿈에 나타나 노래를 불러 주었다","mis":"K4-2-u6-X25"},{"t":"㉰ 새집 일은 잊어버리고 그네를 타러 갔다","mis":"K4-2-u6-X32"},{"t":"정답이 없으니 셋 다 똑같이 알맞다","mis":"K4-2-u6-X25"}],"explanation":["새집 아래에 무엇이 있었나요?","아이들이 북적였어요.","그래서 옮겼어요."],"asset":{"type":"passage","lines":["㉮ 하람이는 선생님께 여쭈어 사람이 덜 다니는 담장 쪽 나무로 새집을 옮겼다.","㉯ 그날 밤 새들이 하람이 꿈에 나타나 고맙다고 노래를 불러 주었다.","㉰ 하람이는 새집 일은 잊어버리고 그네를 타러 뛰어갔다."],"title":"세 친구가 상상한 뒷이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_L06_challenge#5','kor',4,2,'u6','L06','g4_2_kor_u6_L06_challenge','lesson_challenge','K4-2-u6-C26',3,'mc','auto','「빈 새집」의 하람이라면 이어질 이야기에서 어떤 행동을 할 것 같나요?',ARRAY['K4-2-u6-X23','K4-2-u6-X24']::text[],false,'{"seq":5,"concept":"K4-2-u6-C26","difficulty":3,"kind":"mc","stem":"「빈 새집」의 하람이라면 이어질 이야기에서 어떤 행동을 할 것 같나요?","options":[{"t":"새가 올 때까지 날마다 새집을 살피며 방법을 바꾸어 본다","correct":true},{"t":"하루 만에 새집을 떼어 버린다","mis":"K4-2-u6-X23"},{"t":"새집 일은 친구에게 다 맡기고 잊는다","mis":"K4-2-u6-X23"},{"t":"새집을 그네 줄에 옮겨 단다","mis":"K4-2-u6-X24"}],"explanation":["하람이는 어떤 아이였나요?","날마다 조금씩이라도 해내요.","그 성격대로 움직여요."],"asset":{"type":"passage","lines":["하람이는 한번 마음먹은 일은 날마다 조금씩이라도 해내는 아이다.","봄에 하람이는 손수 만든 새집을 학교 뒤뜰 나무에 달았다.","그런데 열흘이 지나도 새집에 드나드는 새가 한 마리도 없었다.","새집 바로 아래에는 그네가 있어 쉬는 시간마다 아이들이 북적였다.","하람이는 새집과 그네를 번갈아 바라보았다."],"title":"빈 새집"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_L06_challenge#6','kor',4,2,'u6','L06','g4_2_kor_u6_L06_challenge','lesson_challenge','K4-2-u6-C31',3,'mc','auto','「빈 새집」의 뒷이야기 ㉰가 알맞지 않은 까닭으로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-2-u6-X27','K4-2-u6-X28','K4-2-u6-X29']::text[],false,'{"seq":6,"concept":"K4-2-u6-C31","difficulty":3,"kind":"mc","stem":"「빈 새집」의 뒷이야기 ㉰가 알맞지 않은 까닭으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"날마다 조금씩이라도 해내는 하람이의 성격과 이어지지 않아서","correct":true},{"t":"그네 타기는 너무 평범한 일이라서","mis":"K4-2-u6-X27"},{"t":"문장이 짧아서","mis":"K4-2-u6-X28"},{"t":"새가 나오지 않아 재미없어서","mis":"K4-2-u6-X29"}],"explanation":["평범함 · 길이는 기준이 아니에요.","하람이는 어떤 아이였나요?","성격과 끊어졌어요."],"asset":{"type":"passage","lines":["㉮ 하람이는 선생님께 여쭈어 사람이 덜 다니는 담장 쪽 나무로 새집을 옮겼다.","㉯ 그날 밤 새들이 하람이 꿈에 나타나 고맙다고 노래를 불러 주었다.","㉰ 하람이는 새집 일은 잊어버리고 그네를 타러 뛰어갔다."],"title":"세 친구가 상상한 뒷이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_L06_challenge#7','kor',4,2,'u6','L06','g4_2_kor_u6_L06_challenge','lesson_challenge','K4-2-u6-C32',3,'mc','auto','두 상상을 견주어 고를 때의 기준으로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-2-u6-X29','K4-2-u6-X28','K4-2-u6-X26']::text[],false,'{"seq":7,"concept":"K4-2-u6-C32","difficulty":3,"kind":"mc","stem":"두 상상을 견주어 고를 때의 기준으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"앞 이야기와 더 이어지는 쪽","correct":true},{"t":"더 놀라운 일이 벌어지는 쪽","mis":"K4-2-u6-X29"},{"t":"더 길게 쓴 쪽","mis":"K4-2-u6-X28"},{"t":"더 많은 친구가 고른 쪽","mis":"K4-2-u6-X26"}],"explanation":["놀라움은 기준이 아니에요.","길이도 아니에요.","이어짐을 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_L06_challenge#8','kor',4,2,'u6','L06','g4_2_kor_u6_L06_challenge','lesson_challenge','K4-2-u6-C30',4,'essay','teacher','「연을 놓친 날」의 뒷이야기를 세 문장으로 쓰고, 내가 쓴 뒷이야기의 어느 부분이 앞 이야기(성격·흐름·까닭)와 이어지는지 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K4-2-u6-C30","difficulty":4,"kind":"essay","stem":"「연을 놓친 날」의 뒷이야기를 세 문장으로 쓰고, 내가 쓴 뒷이야기의 어느 부분이 앞 이야기(성격·흐름·까닭)와 이어지는지 쓰세요.","answer_guide":{"answer":"예: 다음 날 아침 경민이는 아버지와 함께 긴 장대를 들고 둑으로 갔다. 장대 끝으로 가지를 살살 흔들자 연이 천천히 미끄러져 내려왔다. 경민이는 찢어진 곳을 붙이고 이번에는 실을 두 겹으로 감았다. — 끝을 봐야 하는 성격이라 다시 왔고, 실이 끊어진 일이 까닭이 되어 실을 두 겹으로 감았다.","scoring_points":["뒷이야기를 세 문장으로 썼는가","인물의 성격이나 흐름과 이어지는 곳을 짚었는가","앞의 일이 까닭이 되는 곳을 짚었는가"]},"explanation":["끝을 봐야 하는 아이예요.","연은 나무에 걸려 있어요.","까닭을 달고 써요."],"asset":{"type":"passage","lines":["경민이는 한번 하기로 한 것은 끝을 봐야 하는 아이였어요.","겨울 방학 내내 연살을 곱게 깎아 연 하나를 만들었지요.","\"이번엔 저 미루나무보다 높이 올릴 거야.\"","바람이 유난히 세게 불던 날, 경민이는 둑에 나가 연을 올렸어요.","얼레를 더 풀었을 때, 툭. 실이 끊어졌어요.","연은 빙글빙글 돌더니 미루나무 꼭대기 가지에 걸리고 말았어요.","경민이는 나무 아래에서 한참을 올려다보기만 했어요.","해는 벌써 둑 너머로 기울고 있었지요."],"title":"연을 놓친 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_L06_challenge#9','kor',4,2,'u6','L06','g4_2_kor_u6_L06_challenge','lesson_challenge','K4-2-u6-C28',4,'essay','teacher','「빈 새집」의 흐름을 처음 · 가운데 · 지금으로 나누어 쓰고, 지금 이야기가 묻고 있는 것이 무엇인지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K4-2-u6-C28","difficulty":4,"kind":"essay","stem":"「빈 새집」의 흐름을 처음 · 가운데 · 지금으로 나누어 쓰고, 지금 이야기가 묻고 있는 것이 무엇인지 쓰세요.","answer_guide":{"answer":"예: 처음 — 하람이가 손수 만든 새집을 뒤뜰 나무에 달았다. 가운데 — 열흘이 지나도 새가 오지 않았고, 새집 아래 그네에는 아이들이 북적였다. 지금 — 하람이가 새집과 그네를 번갈아 본다. 지금 이야기는 「새가 왜 오지 않을까, 어떻게 하면 올까」를 묻고 있다.","scoring_points":["처음 · 가운데 · 지금을 나누어 썼는가","흐름에 맞게 차례대로 썼는가","지금 이야기가 묻는 것을 썼는가"]},"explanation":["차례대로 늘어놓아요.","지금은 어디까지 왔나요?","다음 칸이 보여요."],"asset":{"type":"passage","lines":["하람이는 한번 마음먹은 일은 날마다 조금씩이라도 해내는 아이다.","봄에 하람이는 손수 만든 새집을 학교 뒤뜰 나무에 달았다.","그런데 열흘이 지나도 새집에 드나드는 새가 한 마리도 없었다.","새집 바로 아래에는 그네가 있어 쉬는 시간마다 아이들이 북적였다.","하람이는 새집과 그네를 번갈아 바라보았다."],"title":"빈 새집"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_L06_challenge#10','kor',4,2,'u6','L06','g4_2_kor_u6_L06_challenge','lesson_challenge','K4-2-u6-C31',4,'essay','teacher','「빈 새집」의 뒷이야기 ㉯가 알맞지 않은 까닭을 쓰고, 신기한 느낌은 살리면서 앞 이야기와 이어지도록 ㉯를 고쳐 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K4-2-u6-C31","difficulty":4,"kind":"essay","stem":"「빈 새집」의 뒷이야기 ㉯가 알맞지 않은 까닭을 쓰고, 신기한 느낌은 살리면서 앞 이야기와 이어지도록 ㉯를 고쳐 쓰세요.","answer_guide":{"answer":"예: ㉯는 새가 오지 않은 까닭(그네 아래라 시끄러움)과 상관없이 꿈속 일로 끝나서 이어지지 않는다. 고쳐 쓰면 — 새집을 담장 쪽으로 옮긴 지 사흘째 아침, 하람이는 새집 구멍에서 작은 지푸라기 한 가닥이 삐죽 나와 있는 것을 보았다.","scoring_points":["알맞지 않은 까닭을 앞 이야기와 이어서 썼는가","고쳐 쓴 글이 앞의 일과 이어지는가","신기하거나 궁금한 느낌을 살렸는가"]},"explanation":["무엇과 끊어졌나요?","까닭을 달아요.","새로우면서도 이어지게"],"asset":{"type":"passage","lines":["㉮ 하람이는 선생님께 여쭈어 사람이 덜 다니는 담장 쪽 나무로 새집을 옮겼다.","㉯ 그날 밤 새들이 하람이 꿈에 나타나 고맙다고 노래를 불러 주었다.","㉰ 하람이는 새집 일은 잊어버리고 그네를 타러 뛰어갔다."],"title":"세 친구가 상상한 뒷이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_L08_basic#1','kor',4,2,'u6','L08','g4_2_kor_u6_L08_basic','lesson_basic','K4-2-u6-C34',1,'mc','auto','「돌아온 우산」에서 일어난 일로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u6-X08']::text[],false,'{"seq":1,"concept":"K4-2-u6-C34","difficulty":1,"kind":"mc","stem":"「돌아온 우산」에서 일어난 일로 알맞은 것은 무엇인가요?","options":[{"t":"잃어버린 우산이 돌아왔는데 낯선 매듭이 묶여 있었다","correct":true},{"t":"동규이가 새 우산을 사 왔다","mis":"K4-2-u6-X08"},{"t":"효주가 은행나무에 우산을 걸어 두었다","mis":"K4-2-u6-X08"},{"t":"동규이가 우산을 또 잃어버렸다","mis":"K4-2-u6-X08"}],"explanation":["무엇이 달라졌나요?","우산이 돌아왔어요.","없던 매듭이 생겼어요."],"asset":{"type":"passage","lines":["[앞 이야기] 동규이는 궁금한 것이 생기면 확인해야 잠이 오는 아이다.","지난주 비 오는 날, 동규이는 학원 앞에 두고 온 파란 우산을 잃어버렸다.","손잡이에 이름표가 없었다. 짝 효주는 \"그냥 새로 사\" 하고 말았다.","사흘 뒤 아침, 교문 앞 은행나무 가지에 그 파란 우산이 걸려 있었다.","손잡이에는 처음 보는 빨간 실 매듭이 꽃 모양으로 단단히 묶여 있었다.","동규이는 어리둥절해서 우산을 든 채 교문 앞에서 머뭇거렸다.","그때 효주가 다가와 매듭을 보더니 눈을 크게 떴다. \"어? 이 매듭⋯⋯.\""],"title":"돌아온 우산"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_L08_basic#2','kor',4,2,'u6','L08','g4_2_kor_u6_L08_basic','lesson_basic','K4-2-u6-C35',1,'match','auto','이야기에 나온 낱말과 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":2,"concept":"K4-2-u6-C35","difficulty":1,"kind":"match","stem":"이야기에 나온 낱말과 뜻을 알맞게 이으세요.","pairs":[{"l":"눈여겨보다","r":"주의 깊게 자세히 보다"},{"l":"어리둥절하다","r":"무슨 영문인지 몰라 얼떨떨하다"},{"l":"머뭇거리다","r":"선뜻 하지 못하고 자꾸 망설이다"}],"mis":"K4-2-u6-X30","explanation":["이야기의 어느 대목에 나왔나요?","셋 다 동규이의 마음이에요.","뜻을 넣어 읽어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_L08_basic#3','kor',4,2,'u6','L08','g4_2_kor_u6_L08_basic','lesson_basic','K4-2-u6-C33',1,'mc','auto','뒷이야기를 쓰기 전에 「앞 이야기」 칸을 먼저 읽는 까닭은 무엇인가요?',ARRAY['K4-2-u6-X24','K4-2-u6-X29','K4-2-u6-X28']::text[],false,'{"seq":3,"concept":"K4-2-u6-C33","difficulty":1,"kind":"mc","stem":"뒷이야기를 쓰기 전에 「앞 이야기」 칸을 먼저 읽는 까닭은 무엇인가요?","options":[{"t":"끊긴 대목이 어떤 일들에 이어져 있는지 알려고","correct":true},{"t":"앞 이야기는 뒷이야기와 상관이 없어 건너뛰려고","mis":"K4-2-u6-X24"},{"t":"가장 놀라운 장면을 고르려고","mis":"K4-2-u6-X29"},{"t":"써야 할 글자 수를 알아보려고","mis":"K4-2-u6-X28"}],"explanation":["끊긴 대목에서 시작해요.","여기까지 있었던 일을 붙잡아요.","그래야 이어 쓸 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_L08_basic#4','kor',4,2,'u6','L08','g4_2_kor_u6_L08_basic','lesson_basic','K4-2-u6-C36',1,'ox','auto','「돌아온 우산」에서 같은 일을 보고도 동규이와 효주는 다르게 움직여요.',ARRAY['K4-2-u6-X31']::text[],false,'{"seq":4,"concept":"K4-2-u6-C36","difficulty":1,"kind":"ox","stem":"「돌아온 우산」에서 같은 일을 보고도 동규이와 효주는 다르게 움직여요.","answer":"O","reason_options":[{"t":"동규이는 궁금하면 확인해야 하고, 효주는 「그냥 새로 사」 하고 말았기 때문에","correct":true},{"t":"같은 일을 보면 누구나 똑같이 움직이기 때문에","mis":"K4-2-u6-X31"}],"mis":"K4-2-u6-X31","explanation":["두 사람의 성격을 봐요.","같은 일, 다른 움직임","그래서 O예요."],"asset":{"type":"passage","lines":["[앞 이야기] 동규이는 궁금한 것이 생기면 확인해야 잠이 오는 아이다.","지난주 비 오는 날, 동규이는 학원 앞에 두고 온 파란 우산을 잃어버렸다.","손잡이에 이름표가 없었다. 짝 효주는 \"그냥 새로 사\" 하고 말았다.","사흘 뒤 아침, 교문 앞 은행나무 가지에 그 파란 우산이 걸려 있었다.","손잡이에는 처음 보는 빨간 실 매듭이 꽃 모양으로 단단히 묶여 있었다.","동규이는 어리둥절해서 우산을 든 채 교문 앞에서 머뭇거렸다.","그때 효주가 다가와 매듭을 보더니 눈을 크게 떴다. \"어? 이 매듭⋯⋯.\""],"title":"돌아온 우산"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_L08_basic#5','kor',4,2,'u6','L08','g4_2_kor_u6_L08_basic','lesson_basic','K4-2-u6-C37',2,'mc','auto','동규이의 성격을 이용해 상상한 것으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u6-X32','K4-2-u6-X25']::text[],false,'{"seq":5,"concept":"K4-2-u6-C37","difficulty":2,"kind":"mc","stem":"동규이의 성격을 이용해 상상한 것으로 알맞은 것은 무엇인가요?","options":[{"t":"동규이는 이 매듭을 맬 줄 아는 사람이 누구인지 찾아보기로 했다","correct":true},{"t":"동규이는 매듭을 풀어 버리고 아무에게도 말하지 않았다","mis":"K4-2-u6-X32"},{"t":"동규이는 우산을 그냥 두고 교실로 뛰어 들어갔다","mis":"K4-2-u6-X32"},{"t":"갑자기 매듭이 말을 하기 시작했다","mis":"K4-2-u6-X25"}],"explanation":["동규이는 어떤 아이였나요?","궁금하면 확인해야 잠이 와요.","그 결대로 움직여요."],"asset":{"type":"passage","lines":["[앞 이야기] 동규이는 궁금한 것이 생기면 확인해야 잠이 오는 아이다.","지난주 비 오는 날, 동규이는 학원 앞에 두고 온 파란 우산을 잃어버렸다.","손잡이에 이름표가 없었다. 짝 효주는 \"그냥 새로 사\" 하고 말았다.","사흘 뒤 아침, 교문 앞 은행나무 가지에 그 파란 우산이 걸려 있었다.","손잡이에는 처음 보는 빨간 실 매듭이 꽃 모양으로 단단히 묶여 있었다.","동규이는 어리둥절해서 우산을 든 채 교문 앞에서 머뭇거렸다.","그때 효주가 다가와 매듭을 보더니 눈을 크게 떴다. \"어? 이 매듭⋯⋯.\""],"title":"돌아온 우산"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_L08_basic#6','kor',4,2,'u6','L08','g4_2_kor_u6_L08_basic','lesson_basic','K4-2-u6-C38',2,'match','auto','「돌아온 우산」에서 원인과 결과를 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K4-2-u6-C38","difficulty":2,"kind":"match","stem":"「돌아온 우산」에서 원인과 결과를 알맞게 이으세요.","pairs":[{"l":"우산에 이름표가 없었다","r":"주운 사람이 임자를 바로 알 수 없었다"},{"l":"주운 사람이 손잡이에 매듭을 묶어 두었다","r":"임자가 알아볼 수 있는 표시가 남았다"},{"l":"효주가 그 매듭을 알아보았다","r":"누구인지 찾아볼 실마리가 생겼다"}],"mis":"K4-2-u6-X09","explanation":["그 일 때문에 무엇이 생겼나요?","앞의 결과가 다음 원인이 돼요.","셋 다 이어요."],"asset":{"type":"passage","lines":["[앞 이야기] 동규이는 궁금한 것이 생기면 확인해야 잠이 오는 아이다.","지난주 비 오는 날, 동규이는 학원 앞에 두고 온 파란 우산을 잃어버렸다.","손잡이에 이름표가 없었다. 짝 효주는 \"그냥 새로 사\" 하고 말았다.","사흘 뒤 아침, 교문 앞 은행나무 가지에 그 파란 우산이 걸려 있었다.","손잡이에는 처음 보는 빨간 실 매듭이 꽃 모양으로 단단히 묶여 있었다.","동규이는 어리둥절해서 우산을 든 채 교문 앞에서 머뭇거렸다.","그때 효주가 다가와 매듭을 보더니 눈을 크게 떴다. \"어? 이 매듭⋯⋯.\""],"title":"돌아온 우산"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_L08_basic#7','kor',4,2,'u6','L08','g4_2_kor_u6_L08_basic','lesson_basic','K4-2-u6-C39',2,'mc','auto','세 친구가 상상한 뒷이야기 가운데 가장 자연스럽게 이어지는 것은 무엇인가요?',ARRAY['K4-2-u6-X29','K4-2-u6-X32','K4-2-u6-X25']::text[],false,'{"seq":7,"concept":"K4-2-u6-C39","difficulty":2,"kind":"mc","stem":"세 친구가 상상한 뒷이야기 가운데 가장 자연스럽게 이어지는 것은 무엇인가요?","options":[{"t":"㉮ 효주가 매듭을 알아보고 둘이 할머니를 찾아갔다","correct":true},{"t":"㉯ 매듭이 스스로 풀리며 우산이 하늘로 날아올랐다","mis":"K4-2-u6-X29"},{"t":"㉰ 동규이가 관심 없이 우산을 교실에 넣어 두었다","mis":"K4-2-u6-X32"},{"t":"셋 다 상상이니 똑같이 자연스럽다","mis":"K4-2-u6-X25"}],"explanation":["놀라운 쪽이 아니에요.","매듭이라는 실마리를 봐요.","효주가 알아보았어요."],"asset":{"type":"passage","lines":["㉮ 효주가 \"우리 할머니가 자루를 묶을 때 이렇게 매\" 하고 말했고, 둘은 할머니를 찾아갔다.","㉯ 그 순간 매듭이 스스로 풀리더니 빛이 나며 우산이 하늘로 날아올랐다.","㉰ 동규이는 매듭을 보고도 아무 관심이 없어 우산을 그냥 교실에 넣어 두었다."],"title":"세 친구가 상상한 뒷이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_L08_basic#8','kor',4,2,'u6','L08','g4_2_kor_u6_L08_basic','lesson_basic','K4-2-u6-C40',2,'mc','auto','세 친구의 뒷이야기 ㉰가 알맞지 않은 까닭으로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-2-u6-X28','K4-2-u6-X27','K4-2-u6-X26']::text[],false,'{"seq":8,"concept":"K4-2-u6-C40","difficulty":2,"kind":"mc","stem":"세 친구의 뒷이야기 ㉰가 알맞지 않은 까닭으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"동규이의 성격을 바꿔 놓고 바뀐 까닭은 쓰지 않았기 때문에","correct":true},{"t":"문장이 너무 짧기 때문에","mis":"K4-2-u6-X28"},{"t":"읽는 사람이 재미없어하기 때문에","mis":"K4-2-u6-X27"},{"t":"이어질 내용에는 정해진 답이 있기 때문에","mis":"K4-2-u6-X26"}],"explanation":["앞의 동규이는 어떤 아이였나요?","궁금하면 확인해야 해요.","바뀐 까닭이 없어요."],"asset":{"type":"passage","lines":["㉮ 효주가 \"우리 할머니가 자루를 묶을 때 이렇게 매\" 하고 말했고, 둘은 할머니를 찾아갔다.","㉯ 그 순간 매듭이 스스로 풀리더니 빛이 나며 우산이 하늘로 날아올랐다.","㉰ 동규이는 매듭을 보고도 아무 관심이 없어 우산을 그냥 교실에 넣어 두었다."],"title":"세 친구가 상상한 뒷이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_L08_basic#9','kor',4,2,'u6','L08','g4_2_kor_u6_L08_basic','lesson_basic','K4-2-u6-C39',2,'mc','auto','뒷이야기를 고를 때의 기준으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u6-X05','K4-2-u6-X06','K4-2-u6-X26']::text[],false,'{"seq":9,"concept":"K4-2-u6-C39","difficulty":2,"kind":"mc","stem":"뒷이야기를 고를 때의 기준으로 알맞은 것은 무엇인가요?","options":[{"t":"인물이 앞에서 보인 모습 그대로 움직이는가","correct":true},{"t":"가장 놀라운 일이 벌어지는가","mis":"K4-2-u6-X05"},{"t":"가장 길게 쓸 수 있는가","mis":"K4-2-u6-X06"},{"t":"정해진 답과 같은가","mis":"K4-2-u6-X26"}],"explanation":["놀라움은 기준이 아니에요.","흐름과 까닭도 봐요.","앞의 모습 그대로인가요?"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_L08_basic#10','kor',4,2,'u6','L08','g4_2_kor_u6_L08_basic','lesson_basic','K4-2-u6-C41',3,'mc','auto','뒷이야기를 쓰다가 「이 사람이 이렇게 할 까닭이 앞에 없다」는 것을 알았어요. 어떻게 하면 좋을까요?',ARRAY['K4-2-u6-X33','K4-2-u6-X49','K4-2-u6-X36']::text[],false,'{"seq":10,"concept":"K4-2-u6-C41","difficulty":3,"kind":"mc","stem":"뒷이야기를 쓰다가 「이 사람이 이렇게 할 까닭이 앞에 없다」는 것을 알았어요. 어떻게 하면 좋을까요?","options":[{"t":"그렇게 할 까닭이 되는 일을 먼저 만들어 이야기에 넣는다","correct":true},{"t":"까닭이 없어도 그대로 쓴다","mis":"K4-2-u6-X33"},{"t":"그 생각은 버리고 가장 뻔한 일만 쓴다","mis":"K4-2-u6-X49"},{"t":"까닭 대신 「갑자기」를 넣는다","mis":"K4-2-u6-X36"}],"explanation":["까닭이 있으면 쓰고","없으면?","까닭을 먼저 만들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_L08_challenge#1','kor',4,2,'u6','L08','g4_2_kor_u6_L08_challenge','lesson_challenge','K4-2-u6-C35',2,'blank','auto','「동규이는 우산을 든 채 교문 앞에서 (   ).」 선뜻 하지 못하고 자꾸 망설였다는 뜻이 되도록 알맞은 말을 고르세요.',ARRAY['K4-2-u6-X30','K4-2-u6-X23']::text[],false,'{"seq":1,"concept":"K4-2-u6-C35","difficulty":2,"kind":"blank","stem":"「동규이는 우산을 든 채 교문 앞에서 (   ).」 선뜻 하지 못하고 자꾸 망설였다는 뜻이 되도록 알맞은 말을 고르세요.","options":[{"t":"머뭇거렸다","correct":true},{"t":"눈여겨보았다","mis":"K4-2-u6-X30"},{"t":"어리둥절했다","mis":"K4-2-u6-X30"},{"t":"뛰어 들어갔다","mis":"K4-2-u6-X23"}],"explanation":["망설이는 모습이에요.","선뜻 하지 못했어요.","머뭇거렸어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_L08_challenge#2','kor',4,2,'u6','L08','g4_2_kor_u6_L08_challenge','lesson_challenge','K4-2-u6-C36',2,'mc','auto','「돌아온 우산」에서 효주를 따라 이어지는 이야기가 동규이를 따를 때와 달라질 수 있는 까닭은 무엇인가요?',ARRAY['K4-2-u6-X31','K4-2-u6-X08']::text[],false,'{"seq":2,"concept":"K4-2-u6-C36","difficulty":2,"kind":"mc","stem":"「돌아온 우산」에서 효주를 따라 이어지는 이야기가 동규이를 따를 때와 달라질 수 있는 까닭은 무엇인가요?","options":[{"t":"효주가 매듭을 보고 눈을 크게 떠서, 매듭을 아는 사람일 수 있기 때문에","correct":true},{"t":"누구를 따라가도 이어질 내용은 같기 때문에","mis":"K4-2-u6-X31"},{"t":"효주는 이 이야기에 처음 나오는 인물이기 때문에","mis":"K4-2-u6-X08"},{"t":"효주가 우산의 임자이기 때문에","mis":"K4-2-u6-X08"}],"explanation":["효주가 무엇을 했나요?","눈을 크게 떴어요.","따라가는 사람에 따라 달라져요."],"asset":{"type":"passage","lines":["[앞 이야기] 동규이는 궁금한 것이 생기면 확인해야 잠이 오는 아이다.","지난주 비 오는 날, 동규이는 학원 앞에 두고 온 파란 우산을 잃어버렸다.","손잡이에 이름표가 없었다. 짝 효주는 \"그냥 새로 사\" 하고 말았다.","사흘 뒤 아침, 교문 앞 은행나무 가지에 그 파란 우산이 걸려 있었다.","손잡이에는 처음 보는 빨간 실 매듭이 꽃 모양으로 단단히 묶여 있었다.","동규이는 어리둥절해서 우산을 든 채 교문 앞에서 머뭇거렸다.","그때 효주가 다가와 매듭을 보더니 눈을 크게 떴다. \"어? 이 매듭⋯⋯.\""],"title":"돌아온 우산"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_L08_challenge#3','kor',4,2,'u6','L08','g4_2_kor_u6_L08_challenge','lesson_challenge','K4-2-u6-C40',3,'mc','auto','앞에서와 성격이 달라지는 인물을 쓰고 싶어요. 어떻게 쓰면 좋을까요?',ARRAY['K4-2-u6-X32','K4-2-u6-X26']::text[],false,'{"seq":3,"concept":"K4-2-u6-C40","difficulty":3,"kind":"mc","stem":"앞에서와 성격이 달라지는 인물을 쓰고 싶어요. 어떻게 쓰면 좋을까요?","options":[{"t":"왜 달라졌는지 까닭이 되는 일을 함께 쓴다","correct":true},{"t":"「동규이는 이제 달라졌다」고 한 줄만 쓴다","mis":"K4-2-u6-X32"},{"t":"달라진 까닭은 쓰지 않고 행동만 바꾼다","mis":"K4-2-u6-X32"},{"t":"성격은 이야기 중간에 절대 달라지면 안 된다","mis":"K4-2-u6-X26"}],"explanation":["선언만 하면 끊겨요.","까닭이 있어야 해요.","함께 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_L08_challenge#4','kor',4,2,'u6','L08','g4_2_kor_u6_L08_challenge','lesson_challenge','K4-2-u6-C37',3,'mc','auto','「돌아온 우산」에서 효주의 행동(매듭을 보고 눈을 크게 떴다)을 이용해 상상한 것으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u6-X32','K4-2-u6-X36','K4-2-u6-X23']::text[],false,'{"seq":4,"concept":"K4-2-u6-C37","difficulty":3,"kind":"mc","stem":"「돌아온 우산」에서 효주의 행동(매듭을 보고 눈을 크게 떴다)을 이용해 상상한 것으로 알맞은 것은 무엇인가요?","options":[{"t":"효주가 「이 매듭, 어디서 많이 본 건데.」 하며 기억을 더듬었다","correct":true},{"t":"효주가 매듭에는 관심 없이 먼저 교실로 갔다","mis":"K4-2-u6-X32"},{"t":"효주가 갑자기 우산을 빼앗아 달아났다","mis":"K4-2-u6-X36"},{"t":"효주가 매듭을 보고도 아무 생각을 하지 않았다","mis":"K4-2-u6-X23"}],"explanation":["눈을 크게 뜬 까닭은?","매듭을 알아보았어요.","그 행동에서 이어져요."],"asset":{"type":"passage","lines":["[앞 이야기] 동규이는 궁금한 것이 생기면 확인해야 잠이 오는 아이다.","지난주 비 오는 날, 동규이는 학원 앞에 두고 온 파란 우산을 잃어버렸다.","손잡이에 이름표가 없었다. 짝 효주는 \"그냥 새로 사\" 하고 말았다.","사흘 뒤 아침, 교문 앞 은행나무 가지에 그 파란 우산이 걸려 있었다.","손잡이에는 처음 보는 빨간 실 매듭이 꽃 모양으로 단단히 묶여 있었다.","동규이는 어리둥절해서 우산을 든 채 교문 앞에서 머뭇거렸다.","그때 효주가 다가와 매듭을 보더니 눈을 크게 떴다. \"어? 이 매듭⋯⋯.\""],"title":"돌아온 우산"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_L08_challenge#5','kor',4,2,'u6','L08','g4_2_kor_u6_L08_challenge','lesson_challenge','K4-2-u6-C38',3,'mc','auto','「돌아온 우산」에서 「주운 사람이 손잡이에 매듭을 묶어 두었다」를 바르게 말한 것은 무엇인가요?',ARRAY['K4-2-u6-X02','K4-2-u6-X01','K4-2-u6-X18']::text[],false,'{"seq":5,"concept":"K4-2-u6-C38","difficulty":3,"kind":"mc","stem":"「돌아온 우산」에서 「주운 사람이 손잡이에 매듭을 묶어 두었다」를 바르게 말한 것은 무엇인가요?","options":[{"t":"임자를 바로 알 수 없었던 일의 결과이면서, 실마리가 생긴 일의 원인이다","correct":true},{"t":"원인이기만 하고 결과는 아니다","mis":"K4-2-u6-X02"},{"t":"동규이가 우산을 잃어버린 일의 원인이다","mis":"K4-2-u6-X01"},{"t":"효주가 우산을 새로 산 일의 결과이다","mis":"K4-2-u6-X18"}],"explanation":["이름표가 없어서?","매듭이 있어서?","두 몫을 맡아요."],"asset":{"type":"passage","lines":["[앞 이야기] 동규이는 궁금한 것이 생기면 확인해야 잠이 오는 아이다.","지난주 비 오는 날, 동규이는 학원 앞에 두고 온 파란 우산을 잃어버렸다.","손잡이에 이름표가 없었다. 짝 효주는 \"그냥 새로 사\" 하고 말았다.","사흘 뒤 아침, 교문 앞 은행나무 가지에 그 파란 우산이 걸려 있었다.","손잡이에는 처음 보는 빨간 실 매듭이 꽃 모양으로 단단히 묶여 있었다.","동규이는 어리둥절해서 우산을 든 채 교문 앞에서 머뭇거렸다.","그때 효주가 다가와 매듭을 보더니 눈을 크게 떴다. \"어? 이 매듭⋯⋯.\""],"title":"돌아온 우산"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_L08_challenge#6','kor',4,2,'u6','L08','g4_2_kor_u6_L08_challenge','lesson_challenge','K4-2-u6-C33',3,'mc','auto','「돌아온 우산」의 「앞 이야기」 칸에 들어갈 내용으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u6-X19','K4-2-u6-X24','K4-2-u6-X08']::text[],false,'{"seq":6,"concept":"K4-2-u6-C33","difficulty":3,"kind":"mc","stem":"「돌아온 우산」의 「앞 이야기」 칸에 들어갈 내용으로 알맞은 것은 무엇인가요?","options":[{"t":"지난주 비 오는 날 동규이가 학원 앞에 우산을 두고 와 잃어버렸다","correct":true},{"t":"효주가 매듭을 보고 눈을 크게 떴다","mis":"K4-2-u6-X19"},{"t":"동규이와 효주가 할머니를 찾아갔다","mis":"K4-2-u6-X24"},{"t":"우산이 하늘로 날아올랐다","mis":"K4-2-u6-X08"}],"explanation":["끊긴 대목 앞의 일이에요.","여기까지 있었던 일이에요.","우산을 잃어버린 일이에요."],"asset":{"type":"passage","lines":["[앞 이야기] 동규이는 궁금한 것이 생기면 확인해야 잠이 오는 아이다.","지난주 비 오는 날, 동규이는 학원 앞에 두고 온 파란 우산을 잃어버렸다.","손잡이에 이름표가 없었다. 짝 효주는 \"그냥 새로 사\" 하고 말았다.","사흘 뒤 아침, 교문 앞 은행나무 가지에 그 파란 우산이 걸려 있었다.","손잡이에는 처음 보는 빨간 실 매듭이 꽃 모양으로 단단히 묶여 있었다.","동규이는 어리둥절해서 우산을 든 채 교문 앞에서 머뭇거렸다.","그때 효주가 다가와 매듭을 보더니 눈을 크게 떴다. \"어? 이 매듭⋯⋯.\""],"title":"돌아온 우산"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_L08_challenge#7','kor',4,2,'u6','L08','g4_2_kor_u6_L08_challenge','lesson_challenge','K4-2-u6-C41',3,'mc','auto','뒷이야기를 다 쓴 뒤 스스로에게 물을 말로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-2-u6-X29','K4-2-u6-X28','K4-2-u6-X26']::text[],false,'{"seq":7,"concept":"K4-2-u6-C41","difficulty":3,"kind":"mc","stem":"뒷이야기를 다 쓴 뒤 스스로에게 물을 말로 가장 알맞은 것은 무엇인가요?","options":[{"t":"「이 사람이 이렇게 할 까닭이 앞에 있나?」","correct":true},{"t":"「이 이야기가 가장 놀라운가?」","mis":"K4-2-u6-X29"},{"t":"「글자를 몇 개나 썼나?」","mis":"K4-2-u6-X28"},{"t":"「선생님이 생각한 답과 같은가?」","mis":"K4-2-u6-X26"}],"explanation":["놀라움 · 길이 · 정답은 아니에요.","까닭을 물어요.","있으면 쓰고, 없으면 넣어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_L08_challenge#8','kor',4,2,'u6','L08','g4_2_kor_u6_L08_challenge','lesson_challenge','K4-2-u6-C37',4,'essay','teacher','「돌아온 우산」의 뒷이야기를 서너 문장으로 쓰세요. 동규이의 성격과 매듭이라는 실마리가 둘 다 드러나게 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K4-2-u6-C37","difficulty":4,"kind":"essay","stem":"「돌아온 우산」의 뒷이야기를 서너 문장으로 쓰세요. 동규이의 성격과 매듭이라는 실마리가 둘 다 드러나게 쓰세요.","answer_guide":{"answer":"예: 동규이는 그날 밤 잠이 오지 않아 매듭을 이리저리 살펴보았다. 다음 날 효주가 할머니께 매듭 이야기를 여쭈어 보자고 했다. 할머니께서는 매듭을 보시자마자 학원 옆 수선집 아주머니가 늘 이렇게 맨다고 하셨다. 둘은 학원이 끝나고 수선집으로 달려갔다.","scoring_points":["뒷이야기를 서너 문장으로 썼는가","궁금하면 확인하는 동규이의 성격이 드러나는가","매듭이라는 실마리가 까닭이 되어 다음 일이 생기는가"]},"explanation":["동규이라면?","매듭이 실마리예요.","까닭을 달고 써요."],"asset":{"type":"passage","lines":["[앞 이야기] 동규이는 궁금한 것이 생기면 확인해야 잠이 오는 아이다.","지난주 비 오는 날, 동규이는 학원 앞에 두고 온 파란 우산을 잃어버렸다.","손잡이에 이름표가 없었다. 짝 효주는 \"그냥 새로 사\" 하고 말았다.","사흘 뒤 아침, 교문 앞 은행나무 가지에 그 파란 우산이 걸려 있었다.","손잡이에는 처음 보는 빨간 실 매듭이 꽃 모양으로 단단히 묶여 있었다.","동규이는 어리둥절해서 우산을 든 채 교문 앞에서 머뭇거렸다.","그때 효주가 다가와 매듭을 보더니 눈을 크게 떴다. \"어? 이 매듭⋯⋯.\""],"title":"돌아온 우산"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_L08_challenge#9','kor',4,2,'u6','L08','g4_2_kor_u6_L08_challenge','lesson_challenge','K4-2-u6-C40',4,'essay','teacher','세 친구의 뒷이야기 ㉰(동규이가 관심 없이 우산을 교실에 넣어 두었다)가 자연스럽게 이어지도록, 동규이가 그렇게 한 까닭이 되는 일을 한두 문장 넣어 고쳐 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K4-2-u6-C40","difficulty":4,"kind":"essay","stem":"세 친구의 뒷이야기 ㉰(동규이가 관심 없이 우산을 교실에 넣어 두었다)가 자연스럽게 이어지도록, 동규이가 그렇게 한 까닭이 되는 일을 한두 문장 넣어 고쳐 쓰세요.","answer_guide":{"answer":"예: 동규이가 매듭을 풀려던 순간 수업 종이 울렸다. 동규이는 「쉬는 시간에 꼭 다시 봐야지.」 하고 우산을 교실에 넣어 두었다. — 관심이 없어서가 아니라 종이 울려서 잠시 미룬 것으로 까닭을 넣었다.","scoring_points":["동규이가 그렇게 한 까닭이 되는 일을 넣었는가","궁금하면 확인하는 성격과 어긋나지 않게 썼는가","고친 이야기가 앞과 이어지는가"]},"explanation":["관심 없는 동규이는 앞과 달라요.","까닭을 먼저 넣어요.","성격과 이어지게요."],"asset":{"type":"passage","lines":["㉮ 효주가 \"우리 할머니가 자루를 묶을 때 이렇게 매\" 하고 말했고, 둘은 할머니를 찾아갔다.","㉯ 그 순간 매듭이 스스로 풀리더니 빛이 나며 우산이 하늘로 날아올랐다.","㉰ 동규이는 매듭을 보고도 아무 관심이 없어 우산을 그냥 교실에 넣어 두었다."],"title":"세 친구가 상상한 뒷이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_L08_challenge#10','kor',4,2,'u6','L08','g4_2_kor_u6_L08_challenge','lesson_challenge','K4-2-u6-C35',4,'essay','teacher','눈여겨보다 · 어리둥절하다 · 머뭇거리다 가운데 두 낱말을 골라 내가 겪은 일로 한 문장씩 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K4-2-u6-C35","difficulty":4,"kind":"essay","stem":"눈여겨보다 · 어리둥절하다 · 머뭇거리다 가운데 두 낱말을 골라 내가 겪은 일로 한 문장씩 쓰세요.","answer_guide":{"answer":"예: 눈여겨보다 — 나는 할머니께서 만두 빚으시는 손을 눈여겨보았다. 머뭇거리다 — 처음 간 학원 문 앞에서 한참 머뭇거렸다.","scoring_points":["두 낱말을 골랐는가","뜻에 맞게 문장을 썼는가","내가 겪은 일로 썼는가"]},"explanation":["뜻을 먼저 떠올려요.","내 일로 써요.","두 문장을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_L11_basic#1','kor',4,2,'u6','L11','g4_2_kor_u6_L11_basic','lesson_basic','K4-2-u6-C42',1,'mc','auto','「창밖에 눈이 소복하게 쌓여 있었습니다.」 다음에 이어 말하기로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u6-X35','K4-2-u6-X36','K4-2-u6-X37']::text[],false,'{"seq":1,"concept":"K4-2-u6-C42","difficulty":1,"kind":"mc","stem":"「창밖에 눈이 소복하게 쌓여 있었습니다.」 다음에 이어 말하기로 알맞은 것은 무엇인가요?","options":[{"t":"「그래서 나는 장갑을 챙겨 밖으로 나갔습니다.」","correct":true},{"t":"「어제 저녁에는 미역국을 먹었습니다.」","mis":"K4-2-u6-X35"},{"t":"「갑자기 코끼리가 교실 천장에서 떨어졌습니다.」","mis":"K4-2-u6-X36"},{"t":"「그런데 창밖에는 눈이 하나도 없었습니다.」","mis":"K4-2-u6-X37"}],"explanation":["앞 문장 뒤에 「그래서」를 붙여요.","눈이 까닭이 되나요?","장갑을 챙겼어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_L11_basic#2','kor',4,2,'u6','L11','g4_2_kor_u6_L11_basic','lesson_basic','K4-2-u6-C47',1,'mc','auto','자격이나 신분을 나타내는 말이 바르게 쓰인 문장은 무엇인가요?',ARRAY['K4-2-u6-X42','K4-2-u6-X41']::text[],false,'{"seq":2,"concept":"K4-2-u6-C47","difficulty":1,"kind":"mc","stem":"자격이나 신분을 나타내는 말이 바르게 쓰인 문장은 무엇인가요?","options":[{"t":"나는 도서 도우미로서 책 정리를 맡았다.","correct":true},{"t":"나는 도서 도우미로써 책 정리를 맡았다.","mis":"K4-2-u6-X42"},{"t":"우리는 박수로서 친구를 응원했다.","mis":"K4-2-u6-X41"},{"t":"흙으로서 작은 그릇을 빚었다.","mis":"K4-2-u6-X41"}],"explanation":["누구인가, 무슨 몫인가?","자격이면 (으)로서","도서 도우미로서예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_L11_basic#3','kor',4,2,'u6','L11','g4_2_kor_u6_L11_basic','lesson_basic','K4-2-u6-C50',1,'mc','auto','「앉다」를 바르게 소리 낸 것은 무엇인가요?',ARRAY['K4-2-u6-X44']::text[],false,'{"seq":3,"concept":"K4-2-u6-C50","difficulty":1,"kind":"mc","stem":"「앉다」를 바르게 소리 낸 것은 무엇인가요?","options":[{"t":"[안따]","correct":true},{"t":"[안자]","mis":"K4-2-u6-X44"},{"t":"[앋따]","mis":"K4-2-u6-X44"},{"t":"[안짜]","mis":"K4-2-u6-X44"}],"explanation":["ㄵ은 보통 [ㄴ]으로 소리 나요.","뒤의 ㄷ은 [ㄸ]이 돼요.","[안따]예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_L11_basic#4','kor',4,2,'u6','L11','g4_2_kor_u6_L11_basic','lesson_basic','K4-2-u6-C46',1,'ox','auto','상상해 만든 역할놀이에서는 가장 웃긴 모둠을 먼저 살펴봐요.',ARRAY['K4-2-u6-X39']::text[],false,'{"seq":4,"concept":"K4-2-u6-C46","difficulty":1,"kind":"ox","stem":"상상해 만든 역할놀이에서는 가장 웃긴 모둠을 먼저 살펴봐요.","answer":"X","reason_options":[{"t":"재미보다 인물의 성격과 앞 이야기에 이어지는지가 먼저이기 때문에","correct":true},{"t":"역할놀이는 웃기려고 하는 놀이이기 때문에","mis":"K4-2-u6-X39"}],"mis":"K4-2-u6-X39","explanation":["웃음의 크기는 기준이 아니에요.","이어지는지 봐요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_L11_basic#5','kor',4,2,'u6','L11','g4_2_kor_u6_L11_basic','lesson_basic','K4-2-u6-C43',2,'mc','auto','「교실 문이 잠겨 있었습니다.」 다음에 이어질 수 있는 문장은 무엇인가요?',ARRAY['K4-2-u6-X35','K4-2-u6-X37','K4-2-u6-X36']::text[],false,'{"seq":5,"concept":"K4-2-u6-C43","difficulty":2,"kind":"mc","stem":"「교실 문이 잠겨 있었습니다.」 다음에 이어질 수 있는 문장은 무엇인가요?","options":[{"t":"그래서 우리는 교무실로 열쇠를 가지러 갔습니다.","correct":true},{"t":"지난봄에 우리 반은 소풍을 갔습니다.","mis":"K4-2-u6-X35"},{"t":"그때 교실 문은 처음부터 열려 있었습니다.","mis":"K4-2-u6-X37"},{"t":"갑자기 하늘에서 열쇠가 비처럼 쏟아졌습니다.","mis":"K4-2-u6-X36"}],"explanation":["문이 잠겨서 무엇을 하게 될까요?","앞의 일이 까닭이 돼요.","열쇠를 가지러 갔어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_L11_basic#6','kor',4,2,'u6','L11','g4_2_kor_u6_L11_basic','lesson_basic','K4-2-u6-C44',2,'mc','auto','효주는 일이 생기면 먼저 방법을 찾는 아이예요. 효주의 다음 대사로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u6-X38','K4-2-u6-X35']::text[],false,'{"seq":6,"concept":"K4-2-u6-C44","difficulty":2,"kind":"mc","stem":"효주는 일이 생기면 먼저 방법을 찾는 아이예요. 효주의 다음 대사로 알맞은 것은 무엇인가요?","options":[{"t":"「그럼 같이 찾아보자. 가방 먼저, 그다음 미술실.」","correct":true},{"t":"「거봐, 내 말이 맞잖아. 네가 잘못한 거야.」","mis":"K4-2-u6-X38"},{"t":"「난 몰라. 나 먼저 집에 갈래.」","mis":"K4-2-u6-X38"},{"t":"「색연필 이야기는 그만하고 노래 부르자.」","mis":"K4-2-u6-X35"}],"explanation":["효주는 어떤 아이인가요?","따지기보다 방법을 내놓아요.","같이 찾아보자고 해요."],"asset":{"type":"speech","turns":[{"who":"찬욱","text":"(가방을 뒤지며) 어? 내 색연필 어디 갔지?"},{"who":"효주","text":"아까 미술실에 두고 온 거 아니야?"},{"who":"찬욱","text":"아니야, 분명히 넣었는데⋯⋯."},{"who":"효주","text":"그럼 ⋯⋯"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_L11_basic#7','kor',4,2,'u6','L11','g4_2_kor_u6_L11_basic','lesson_basic','K4-2-u6-C48',2,'mc','auto','재료나 수단을 나타내는 말이 바르게 쓰인 문장은 무엇인가요?',ARRAY['K4-2-u6-X42','K4-2-u6-X41']::text[],false,'{"seq":7,"concept":"K4-2-u6-C48","difficulty":2,"kind":"mc","stem":"재료나 수단을 나타내는 말이 바르게 쓰인 문장은 무엇인가요?","options":[{"t":"우리는 웃음으로써 어색함을 풀었다.","correct":true},{"t":"나는 맏이로써 동생들을 챙겼다.","mis":"K4-2-u6-X42"},{"t":"모둠장으로써 의견을 모았다.","mis":"K4-2-u6-X42"},{"t":"우리는 웃음으로서 어색함을 풀었다.","mis":"K4-2-u6-X41"}],"explanation":["무엇을 써서 했나요?","수단이면 (으)로써","웃음으로써예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_L11_basic#8','kor',4,2,'u6','L11','g4_2_kor_u6_L11_basic','lesson_basic','K4-2-u6-C51',2,'mc','auto','「많다」를 바르게 소리 낸 것은 무엇인가요?',ARRAY['K4-2-u6-X45','K4-2-u6-X44']::text[],false,'{"seq":8,"concept":"K4-2-u6-C51","difficulty":2,"kind":"mc","stem":"「많다」를 바르게 소리 낸 것은 무엇인가요?","options":[{"t":"[만타]","correct":true},{"t":"[만다]","mis":"K4-2-u6-X45"},{"t":"[마나]","mis":"K4-2-u6-X45"},{"t":"[말따]","mis":"K4-2-u6-X44"}],"explanation":["ㄶ의 ㅎ이 뒤 소리와 합쳐져요.","ㅎ + ㄷ → [ㅌ]","[만타]예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_L11_basic#9','kor',4,2,'u6','L11','g4_2_kor_u6_L11_basic','lesson_basic','K4-2-u6-C52',2,'mc','auto','바르게 쓴 낱말은 무엇인가요?',ARRAY['K4-2-u6-X46']::text[],false,'{"seq":9,"concept":"K4-2-u6-C52","difficulty":2,"kind":"mc","stem":"바르게 쓴 낱말은 무엇인가요?","options":[{"t":"괜찮다","correct":true},{"t":"괜찬타","mis":"K4-2-u6-X46"},{"t":"괜찬다","mis":"K4-2-u6-X46"},{"t":"괜찮타","mis":"K4-2-u6-X46"}],"explanation":["소리는 [괜찬타]예요.","쓸 때는 겹받침 그대로","괜찮다예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_L11_basic#10','kor',4,2,'u6','L11','g4_2_kor_u6_L11_basic','lesson_basic','K4-2-u6-C53',3,'mc','auto','이어질 내용을 상상하는 일에 대해 바르게 말한 것은 무엇인가요?',ARRAY['K4-2-u6-X25','K4-2-u6-X26','K4-2-u6-X49']::text[],false,'{"seq":10,"concept":"K4-2-u6-C53","difficulty":3,"kind":"mc","stem":"이어질 내용을 상상하는 일에 대해 바르게 말한 것은 무엇인가요?","options":[{"t":"앞의 일과 이어지면서도 새로울 수 있다","correct":true},{"t":"상상은 앞 이야기와 아주 달라야 재미있다","mis":"K4-2-u6-X25"},{"t":"이어질 내용에도 정해진 답이 하나 있다","mis":"K4-2-u6-X26"},{"t":"이어지려면 뻔한 일만 써야 한다","mis":"K4-2-u6-X49"}],"explanation":["한쪽으로 치우친 말은 오답이에요.","까닭을 달고 가요.","새로우면서도 이어져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_L11_challenge#1','kor',4,2,'u6','L11','g4_2_kor_u6_L11_challenge','lesson_challenge','K4-2-u6-C49',2,'blank','auto','「아영이는 손을 들까 말까 한참 (   ).」에 가장 알맞은 말을 고르세요.',ARRAY['K4-2-u6-X43']::text[],false,'{"seq":1,"concept":"K4-2-u6-C49","difficulty":2,"kind":"blank","stem":"「아영이는 손을 들까 말까 한참 (   ).」에 가장 알맞은 말을 고르세요.","options":[{"t":"머뭇거렸다","correct":true},{"t":"눈여겨보았다","mis":"K4-2-u6-X43"},{"t":"어리둥절했다","mis":"K4-2-u6-X43"},{"t":"반짝거렸다","mis":"K4-2-u6-X43"}],"explanation":["손을 들까 말까 해요.","선뜻 하지 못해요.","머뭇거렸어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_L11_challenge#2','kor',4,2,'u6','L11','g4_2_kor_u6_L11_challenge','lesson_challenge','K4-2-u6-C54',2,'mc','auto','원인과 결과를 생활 속에서 생각한 것으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u6-X48']::text[],false,'{"seq":2,"concept":"K4-2-u6-C54","difficulty":2,"kind":"mc","stem":"원인과 결과를 생활 속에서 생각한 것으로 알맞은 것은 무엇인가요?","options":[{"t":"화분이 시든 까닭을 찾으면 그다음을 바꿀 수 있다","correct":true},{"t":"원인과 결과는 이야기 속에만 있다","mis":"K4-2-u6-X48"},{"t":"까닭을 찾지 않고 화분만 새로 바꾸면 된다","mis":"K4-2-u6-X48"},{"t":"생활 속 일은 까닭 없이 일어난다","mis":"K4-2-u6-X48"}],"explanation":["이야기 밖에도 까닭이 있어요.","줄만 바꾼 마을 사람들을 떠올려요.","까닭을 찾으면 바꿀 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_L11_challenge#3','kor',4,2,'u6','L11','g4_2_kor_u6_L11_challenge','lesson_challenge','K4-2-u6-C45',3,'mc','auto','이어질 내용을 상상해 역할놀이를 연습하기 전에 정할 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-2-u6-X50','K4-2-u6-X39','K4-2-u6-X40']::text[],false,'{"seq":3,"concept":"K4-2-u6-C45","difficulty":3,"kind":"mc","stem":"이어질 내용을 상상해 역할놀이를 연습하기 전에 정할 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"인물마다 성격 한 줄 · 뒤에 벌어질 일의 까닭 · 대사와 함께할 몸짓","correct":true},{"t":"대사만 빠르게 외우기","mis":"K4-2-u6-X50"},{"t":"가장 웃긴 대사 먼저 정하기","mis":"K4-2-u6-X39"},{"t":"대사를 되도록 길게 늘리기","mis":"K4-2-u6-X40"}],"explanation":["성격을 한 줄로","까닭을 붙여요.","몸짓도 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_L11_challenge#4','kor',4,2,'u6','L11','g4_2_kor_u6_L11_challenge','lesson_challenge','K4-2-u6-C44',3,'mc','auto','서진이는 자기 잘못이면 먼저 인정하고 고치는 아이예요. 서진이의 다음 대사로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u6-X38','K4-2-u6-X36']::text[],false,'{"seq":4,"concept":"K4-2-u6-C44","difficulty":3,"kind":"mc","stem":"서진이는 자기 잘못이면 먼저 인정하고 고치는 아이예요. 서진이의 다음 대사로 알맞은 것은 무엇인가요?","options":[{"t":"「내가 다시 붙일게. 이번엔 네 귀퉁이에 다 꽂을게.」","correct":true},{"t":"「내 탓 아니야. 바람이 그런 거야.」","mis":"K4-2-u6-X38"},{"t":"「그림이 떨어지든 말든 난 상관없어.」","mis":"K4-2-u6-X38"},{"t":"「그럼 그림을 그냥 버리자.」","mis":"K4-2-u6-X36"}],"explanation":["서진이는 어떤 아이인가요?","먼저 인정하고 고쳐요.","다시 붙이겠다고 해요."],"asset":{"type":"speech","turns":[{"who":"나래","text":"(게시판 앞에서) 우리 모둠 그림이 바닥에 떨어져 있어."},{"who":"서진","text":"어제 내가 붙였는데, 압정을 하나만 꽂았나 봐."},{"who":"나래","text":"⋯⋯"},{"who":"서진","text":"( ? )"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_L11_challenge#5','kor',4,2,'u6','L11','g4_2_kor_u6_L11_challenge','lesson_challenge','K4-2-u6-C42',3,'mc','auto','이야기 이어 말하기 놀이에 대해 바르게 말한 것은 무엇인가요?',ARRAY['K4-2-u6-X34','K4-2-u6-X51','K4-2-u6-X35']::text[],false,'{"seq":5,"concept":"K4-2-u6-C42","difficulty":3,"kind":"mc","stem":"이야기 이어 말하기 놀이에 대해 바르게 말한 것은 무엇인가요?","options":[{"t":"끊기지 않게 잇는 놀이라서, 앞 문장이 까닭이 되는 문장을 잇는다","correct":true},{"t":"길게 말하는 사람이 이기는 놀이다","mis":"K4-2-u6-X34"},{"t":"「그래서」를 넣어 어색해도 이어 말했으면 된다","mis":"K4-2-u6-X51"},{"t":"앞 문장과 상관없어도 재미있으면 된다","mis":"K4-2-u6-X35"}],"explanation":["이기는 놀이가 아니에요.","「그래서」를 넣어 말이 되나요?","끊기지 않게 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_L11_challenge#6','kor',4,2,'u6','L11','g4_2_kor_u6_L11_challenge','lesson_challenge','K4-2-u6-C47',3,'match','auto','빈칸에 알맞은 표현을 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K4-2-u6-C47","difficulty":3,"kind":"match","stem":"빈칸에 알맞은 표현을 이으세요.","pairs":[{"l":"나는 맏이(  ) 동생들을 챙겼다","r":"로서"},{"l":"우리는 박수(  ) 친구를 응원했다","r":"로써"},{"l":"그는 모둠장(  ) 회의를 이끌었다","r":"으로서"}],"mis":"K4-2-u6-X41","explanation":["누구인가요? → (으)로서","무엇을 써서? → (으)로써","받침이 있으면 「으」가 붙어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_L11_challenge#7','kor',4,2,'u6','L11','g4_2_kor_u6_L11_challenge','lesson_challenge','K4-2-u6-C52',3,'mc','auto','「의자에 (   ) 책을 읽었다.」의 빈칸에 바르게 쓴 것은 무엇인가요?',ARRAY['K4-2-u6-X47','K4-2-u6-X46']::text[],false,'{"seq":7,"concept":"K4-2-u6-C52","difficulty":3,"kind":"mc","stem":"「의자에 (   ) 책을 읽었다.」의 빈칸에 바르게 쓴 것은 무엇인가요?","options":[{"t":"앉아서","correct":true},{"t":"않아서","mis":"K4-2-u6-X47"},{"t":"안자서","mis":"K4-2-u6-X46"},{"t":"앉자서","mis":"K4-2-u6-X46"}],"explanation":["자리에 몸을 두는 일이에요.","앉다와 않다는 뜻이 달라요.","앉아서예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_L11_challenge#8','kor',4,2,'u6','L11','g4_2_kor_u6_L11_challenge','lesson_challenge','K4-2-u6-C42',4,'essay','teacher','「급식실 앞에 긴 줄이 늘어서 있었습니다.」 다음에 두 문장을 원인과 결과로 이어 쓰세요. 그리고 각 문장 앞에 「그래서」나 「왜냐하면」을 넣어 읽어도 말이 되는지 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K4-2-u6-C42","difficulty":4,"kind":"essay","stem":"「급식실 앞에 긴 줄이 늘어서 있었습니다.」 다음에 두 문장을 원인과 결과로 이어 쓰세요. 그리고 각 문장 앞에 「그래서」나 「왜냐하면」을 넣어 읽어도 말이 되는지 쓰세요.","answer_guide":{"answer":"예: 그래서 나는 줄 맨 끝에 서서 차례를 기다렸습니다. 기다리는 동안 배가 고파서 오늘 반찬이 무엇인지 게시판을 올려다보았습니다. — 두 문장 모두 앞에 「그래서」를 넣어 읽어도 말이 된다.","scoring_points":["두 문장을 이어 썼는가","앞 문장이 까닭이 되어 다음 문장이 생기는가","「그래서」·「왜냐하면」으로 확인한 결과를 썼는가"]},"explanation":["앞 문장이 까닭이에요.","두 문장을 이어요.","넣어 읽어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_L11_challenge#9','kor',4,2,'u6','L11','g4_2_kor_u6_L11_challenge','lesson_challenge','K4-2-u6-C48',4,'essay','teacher','(으)로서와 (으)로써를 넣은 문장을 하나씩 지어 쓰고, 각각 왜 그 표현을 골랐는지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K4-2-u6-C48","difficulty":4,"kind":"essay","stem":"(으)로서와 (으)로써를 넣은 문장을 하나씩 지어 쓰고, 각각 왜 그 표현을 골랐는지 쓰세요.","answer_guide":{"answer":"예: 나는 4학년으로서 1학년 동생들의 신발 정리를 도왔다 — 「4학년」이라는 자격이라서 (으)로서. 우리는 투표 대신 대화로써 놀이 규칙을 정했다 — 「대화」를 써서 정했으니 수단이라 (으)로써.","scoring_points":["(으)로서를 넣은 문장을 지었는가","(으)로써를 넣은 문장을 지었는가","자격과 수단으로 고른 까닭을 썼는가"]},"explanation":["누구인가?","무엇을 써서?","까닭을 함께 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_L11_challenge#10','kor',4,2,'u6','L11','g4_2_kor_u6_L11_challenge','lesson_challenge','K4-2-u6-C44',4,'essay','teacher','찬욱이와 효주의 장면에 이어질 대사를 한 줄씩 지어 쓰세요. 한번 아니라고 하면 잘 굽히지 않는 찬욱이와, 일이 생기면 먼저 방법을 찾는 효주의 성격이 드러나게 쓰고 몸짓도 하나씩 붙이세요.','{}'::text[],false,'{"seq":10,"concept":"K4-2-u6-C44","difficulty":4,"kind":"essay","stem":"찬욱이와 효주의 장면에 이어질 대사를 한 줄씩 지어 쓰세요. 한번 아니라고 하면 잘 굽히지 않는 찬욱이와, 일이 생기면 먼저 방법을 찾는 효주의 성격이 드러나게 쓰고 몸짓도 하나씩 붙이세요.","answer_guide":{"answer":"예: 효주 — (가방을 같이 들여다보며) 「그럼 가방부터 다 꺼내 보자. 없으면 미술실에 가 보면 되잖아.」 / 찬욱 — (팔짱을 끼며) 「좋아. 그래도 미술실엔 분명히 없을 거야.」","scoring_points":["효주의 대사에 방법을 찾는 성격이 드러나는가","찬욱이의 대사에 잘 굽히지 않는 성격이 드러나는가","대사마다 몸짓을 붙였는가"]},"explanation":["효주라면?","찬욱이라면?","몸짓도 붙여요."],"asset":{"type":"speech","turns":[{"who":"찬욱","text":"(가방을 뒤지며) 어? 내 색연필 어디 갔지?"},{"who":"효주","text":"아까 미술실에 두고 온 거 아니야?"},{"who":"찬욱","text":"아니야, 분명히 넣었는데⋯⋯."},{"who":"효주","text":"그럼 ⋯⋯"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_review_a#1','kor',4,2,'u6','','g4_2_kor_u6_review_a','unit_review','K4-2-u6-C5',1,'mc','auto','1차시에 만났던 물음이 마지막 차시에 다시 나왔어요. 이어질 내용을 상상할 때 가장 먼저 생각할 것은 무엇인가요?',ARRAY['K4-2-u6-X05','K4-2-u6-X06','K4-2-u6-X26']::text[],false,'{"seq":1,"concept":"K4-2-u6-C5","difficulty":1,"kind":"mc","stem":"1차시에 만났던 물음이 마지막 차시에 다시 나왔어요. 이어질 내용을 상상할 때 가장 먼저 생각할 것은 무엇인가요?","options":[{"t":"앞에서 어떤 일이 왜 일어났는지","correct":true},{"t":"가장 놀라운 일이 무엇인지","mis":"K4-2-u6-X05"},{"t":"어떻게 하면 가장 길게 쓸지","mis":"K4-2-u6-X06"},{"t":"친구들이 가장 많이 고를 일이 무엇인지","mis":"K4-2-u6-X26"}],"explanation":["같은 물음으로 돌아왔어요.","상상은 앞 이야기에서 출발해요.","무슨 일이 왜?"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_review_a#2','kor',4,2,'u6','','g4_2_kor_u6_review_a','unit_review','K4-2-u6-C1',1,'mc','auto','「그래서 벌어진 일」을 무엇이라고 하나요?',ARRAY['K4-2-u6-X01','K4-2-u6-X04']::text[],false,'{"seq":2,"concept":"K4-2-u6-C1","difficulty":1,"kind":"mc","stem":"「그래서 벌어진 일」을 무엇이라고 하나요?","options":[{"t":"결과","correct":true},{"t":"원인","mis":"K4-2-u6-X01"},{"t":"사건","mis":"K4-2-u6-X04"},{"t":"까닭","mis":"K4-2-u6-X01"}],"explanation":["원인은 까닭이에요.","그래서 벌어진 일은?","결과예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_review_a#3','kor',4,2,'u6','','g4_2_kor_u6_review_a','unit_review','K4-2-u6-C47',1,'mc','auto','「나는 우리 반 대표(   ) 대회에 나갔다.」의 빈칸에 알맞은 것은 무엇인가요?',ARRAY['K4-2-u6-X42']::text[],false,'{"seq":3,"concept":"K4-2-u6-C47","difficulty":1,"kind":"mc","stem":"「나는 우리 반 대표(   ) 대회에 나갔다.」의 빈칸에 알맞은 것은 무엇인가요?","options":[{"t":"로서","correct":true},{"t":"로써","mis":"K4-2-u6-X42"},{"t":"에게","mis":"K4-2-u6-X42"},{"t":"처럼","mis":"K4-2-u6-X42"}],"explanation":["대표는 자격이에요.","자격이면 (으)로서","로서예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_review_a#4','kor',4,2,'u6','','g4_2_kor_u6_review_a','unit_review','K4-2-u6-C35',1,'mc','auto','「주의 깊게 자세히 보다」라는 뜻의 낱말은 무엇인가요?',ARRAY['K4-2-u6-X30']::text[],false,'{"seq":4,"concept":"K4-2-u6-C35","difficulty":1,"kind":"mc","stem":"「주의 깊게 자세히 보다」라는 뜻의 낱말은 무엇인가요?","options":[{"t":"눈여겨보다","correct":true},{"t":"어리둥절하다","mis":"K4-2-u6-X30"},{"t":"머뭇거리다","mis":"K4-2-u6-X30"},{"t":"둘러보다","mis":"K4-2-u6-X30"}],"explanation":["자세히 봐요.","주의 깊게요.","눈여겨보다예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_review_a#5','kor',4,2,'u6','','g4_2_kor_u6_review_a','unit_review','K4-2-u6-C50',1,'mc','auto','「얹다」를 바르게 소리 낸 것은 무엇인가요?',ARRAY['K4-2-u6-X44']::text[],false,'{"seq":5,"concept":"K4-2-u6-C50","difficulty":1,"kind":"mc","stem":"「얹다」를 바르게 소리 낸 것은 무엇인가요?","options":[{"t":"[언따]","correct":true},{"t":"[언자]","mis":"K4-2-u6-X44"},{"t":"[엊따]","mis":"K4-2-u6-X44"},{"t":"[언짜]","mis":"K4-2-u6-X44"}],"explanation":["ㄵ은 보통 [ㄴ]","뒤의 ㄷ은 [ㄸ]","[언따]예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_review_a#6','kor',4,2,'u6','','g4_2_kor_u6_review_a','unit_review','K4-2-u6-C8',1,'mc','auto','영상 ㉰에서 일어난 일로 장면에 그대로 나와 있는 것은 무엇인가요?',ARRAY['K4-2-u6-X08']::text[],false,'{"seq":6,"concept":"K4-2-u6-C8","difficulty":1,"kind":"mc","stem":"영상 ㉰에서 일어난 일로 장면에 그대로 나와 있는 것은 무엇인가요?","options":[{"t":"칠판 아래 바닥에 분필 가루가 흩어져 있다","correct":true},{"t":"누가 분필을 일부러 부수었다","mis":"K4-2-u6-X08"},{"t":"당번이 청소를 하지 않았다","mis":"K4-2-u6-X08"},{"t":"바람에 칠판이 넘어졌다","mis":"K4-2-u6-X08"}],"explanation":["장면에 나와 있는 것만","짐작을 덧붙이지 않아요.","분필 가루가 흩어져 있어요."],"asset":{"type":"passage","lines":["[장면] 아침 교실. 칠판 아래 바닥에 하얀 분필 가루가 흩어져 있다.","창문 하나가 활짝 열려 있고 커튼이 크게 펄럭인다.","[말] \"어제 분명히 깨끗하게 치웠는데⋯⋯.\""],"title":"영상 ㉰ 아침 교실"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_review_a#7','kor',4,2,'u6','','g4_2_kor_u6_review_a','unit_review','K4-2-u6-C26',1,'mc','auto','「늦게 가는 시계」에서 다은이의 성격이 드러난 곳은 어디인가요?',ARRAY['K4-2-u6-X20','K4-2-u6-X23']::text[],false,'{"seq":7,"concept":"K4-2-u6-C26","difficulty":1,"kind":"mc","stem":"「늦게 가는 시계」에서 다은이의 성격이 드러난 곳은 어디인가요?","options":[{"t":"선생님께 부탁해 건전지 칸을 직접 열어 본 행동","correct":true},{"t":"이야기의 제목","mis":"K4-2-u6-X20"},{"t":"아이들이 「오래돼서 그래.」 하고 한 말","mis":"K4-2-u6-X23"},{"t":"시계가 걸린 자리","mis":"K4-2-u6-X20"}],"explanation":["다은이가 한 일을 봐요.","행동에 성격이 있어요.","직접 열어 보았어요."],"asset":{"type":"passage","lines":["우리 반 벽시계는 언제부터인가 조금씩 늦게 갔어요.","그래서 시계를 보고 움직인 날은 급식실에 늘 꼴찌로 도착했지요.","\"시계가 오래돼서 그래.\" 아이들은 그렇게만 말했어요.","다은이는 선생님께 시계를 내려 달라고 부탁해 뒤쪽 건전지 칸을 열어 보았어요.","건전지 한 개가 헐겁게 빠져 있었어요.","다은이가 건전지를 꾹 눌러 끼우자 초바늘이 다시 힘차게 돌았어요."],"title":"늦게 가는 시계"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_review_a#8','kor',4,2,'u6','','g4_2_kor_u6_review_a','unit_review','K4-2-u6-C42',1,'mc','auto','「운동장에 커다란 웅덩이가 생겨 있었습니다.」 다음에 이어 말하기로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u6-X35','K4-2-u6-X36','K4-2-u6-X37']::text[],false,'{"seq":8,"concept":"K4-2-u6-C42","difficulty":1,"kind":"mc","stem":"「운동장에 커다란 웅덩이가 생겨 있었습니다.」 다음에 이어 말하기로 알맞은 것은 무엇인가요?","options":[{"t":"「그래서 우리는 웅덩이를 피해 가장자리로 돌아갔습니다.」","correct":true},{"t":"「우리 집 강아지는 하얀색입니다.」","mis":"K4-2-u6-X35"},{"t":"「갑자기 웅덩이에서 고래가 튀어 올랐습니다.」","mis":"K4-2-u6-X36"},{"t":"「그런데 운동장은 처음부터 바싹 말라 있었습니다.」","mis":"K4-2-u6-X37"}],"explanation":["「그래서」를 붙여 봐요.","웅덩이가 까닭이 되나요?","피해서 돌아갔어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_review_a#9','kor',4,2,'u6','','g4_2_kor_u6_review_a','unit_review','K4-2-u6-C14',2,'mc','auto','「넘친 수돗가」에서 「물이 잘 빠지지 않아 개수대에 물이 고였다」를 바르게 말한 것은 무엇인가요?',ARRAY['K4-2-u6-X02','K4-2-u6-X18']::text[],false,'{"seq":9,"concept":"K4-2-u6-C14","difficulty":2,"kind":"mc","stem":"「넘친 수돗가」에서 「물이 잘 빠지지 않아 개수대에 물이 고였다」를 바르게 말한 것은 무엇인가요?","options":[{"t":"거름망이 막힌 일의 결과이면서, 물이 넘친 일의 원인이다","correct":true},{"t":"원인이기만 하다","mis":"K4-2-u6-X02"},{"t":"결과이기만 하다","mis":"K4-2-u6-X02"},{"t":"앞뒤 일과 상관없는 일이다","mis":"K4-2-u6-X18"}],"explanation":["앞을 보고 한 번","뒤를 보고 한 번","두 몫을 맡아요."],"asset":{"type":"passage","lines":["과학실 수돗가 거름망에 종이 조각이 잔뜩 끼어 있었어요.","물이 잘 빠지지 않아 개수대에 물이 고였어요.","고인 물이 넘쳐 바닥으로 흘러내렸어요.","그 바람에 지나가던 지호가 미끄러질 뻔했어요.","지호는 걸레를 가져오기 전에 거름망부터 들여다보았어요."],"title":"넘친 수돗가"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_review_a#10','kor',4,2,'u6','','g4_2_kor_u6_review_a','unit_review','K4-2-u6-C19',2,'mc','auto','「넘친 수돗가」에서 지호가 미끄러질 뻔한 까닭을 가장 알맞게 말한 것은 무엇인가요?',ARRAY['K4-2-u6-X15','K4-2-u6-X16']::text[],false,'{"seq":10,"concept":"K4-2-u6-C19","difficulty":2,"kind":"mc","stem":"「넘친 수돗가」에서 지호가 미끄러질 뻔한 까닭을 가장 알맞게 말한 것은 무엇인가요?","options":[{"t":"거름망이 막혀 고인 물이 넘쳤고, 그 물이 바닥으로 흘렀기 때문에","correct":true},{"t":"지호가 조심하지 않았기 때문에, 하나뿐이다","mis":"K4-2-u6-X15"},{"t":"과학실 바닥이 원래 미끄럽기 때문에","mis":"K4-2-u6-X16"},{"t":"까닭이 여럿이면 잘못 쓴 이야기다","mis":"K4-2-u6-X15"}],"explanation":["하나뿐일까요?","앞으로 거슬러 가 봐요.","여러 일이 이어졌어요."],"asset":{"type":"passage","lines":["과학실 수돗가 거름망에 종이 조각이 잔뜩 끼어 있었어요.","물이 잘 빠지지 않아 개수대에 물이 고였어요.","고인 물이 넘쳐 바닥으로 흘러내렸어요.","그 바람에 지나가던 지호가 미끄러질 뻔했어요.","지호는 걸레를 가져오기 전에 거름망부터 들여다보았어요."],"title":"넘친 수돗가"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_review_a#11','kor',4,2,'u6','','g4_2_kor_u6_review_a','unit_review','K4-2-u6-C10',2,'mc','auto','영상 ㉰를 보고 「바람이 들어와서」라고 예상했는데, 뒷부분에서 당번이 지우개를 털다 흘린 것으로 나왔어요. 견주어 말한 것으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u6-X11','K4-2-u6-X10','K4-2-u6-X03']::text[],false,'{"seq":11,"concept":"K4-2-u6-C10","difficulty":2,"kind":"mc","stem":"영상 ㉰를 보고 「바람이 들어와서」라고 예상했는데, 뒷부분에서 당번이 지우개를 털다 흘린 것으로 나왔어요. 견주어 말한 것으로 알맞은 것은 무엇인가요?","options":[{"t":"「창문이 열린 것을 까닭으로 바람 탓이라 예상했는데, 당번이 흘린 것이어서 그 부분이 달랐다.」","correct":true},{"t":"「예상이 달라서 아쉬웠다.」","mis":"K4-2-u6-X11"},{"t":"「틀렸으니 다음부터 예상하지 않겠다.」","mis":"K4-2-u6-X10"},{"t":"「처음부터 당번이 그랬을 줄 알았다.」","mis":"K4-2-u6-X03"}],"explanation":["무엇을 까닭으로 예상했나요?","어느 부분이 달랐나요?","느낌만으로는 안 돼요."],"asset":{"type":"passage","lines":["[장면] 아침 교실. 칠판 아래 바닥에 하얀 분필 가루가 흩어져 있다.","창문 하나가 활짝 열려 있고 커튼이 크게 펄럭인다.","[말] \"어제 분명히 깨끗하게 치웠는데⋯⋯.\""],"title":"영상 ㉰ 아침 교실"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_review_a#12','kor',4,2,'u6','','g4_2_kor_u6_review_a','unit_review','K4-2-u6-C12',2,'mc','auto','영상 ㉰를 보고 분필 가루가 흩어진 까닭을 예상한 것 가운데 장면에 근거가 있는 것은 무엇인가요?',ARRAY['K4-2-u6-X13','K4-2-u6-X25']::text[],false,'{"seq":12,"concept":"K4-2-u6-C12","difficulty":2,"kind":"mc","stem":"영상 ㉰를 보고 분필 가루가 흩어진 까닭을 예상한 것 가운데 장면에 근거가 있는 것은 무엇인가요?","options":[{"t":"열린 창문으로 센 바람이 들어와 칠판 받침의 가루가 날렸을 것이다","correct":true},{"t":"밤에 분필 요정이 춤을 추었을 것이다","mis":"K4-2-u6-X13"},{"t":"선생님이 화가 나서 분필을 던지셨을 것이다","mis":"K4-2-u6-X13"},{"t":"예상은 저마다 다르니 어떤 까닭이든 근거가 된다","mis":"K4-2-u6-X25"}],"explanation":["장면에 무엇이 나와 있나요?","창문과 커튼이 있어요.","바람이 근거예요."],"asset":{"type":"passage","lines":["[장면] 아침 교실. 칠판 아래 바닥에 하얀 분필 가루가 흩어져 있다.","창문 하나가 활짝 열려 있고 커튼이 크게 펄럭인다.","[말] \"어제 분명히 깨끗하게 치웠는데⋯⋯.\""],"title":"영상 ㉰ 아침 교실"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_review_a#13','kor',4,2,'u6','','g4_2_kor_u6_review_a','unit_review','K4-2-u6-C28',2,'mc','auto','「빈 화분의 싹」의 흐름에 가장 알맞은 다음 일은 무엇인가요?',ARRAY['K4-2-u6-X24','K4-2-u6-X36']::text[],false,'{"seq":13,"concept":"K4-2-u6-C28","difficulty":2,"kind":"mc","stem":"「빈 화분의 싹」의 흐름에 가장 알맞은 다음 일은 무엇인가요?","options":[{"t":"예린이가 싹이 난 까닭을 알아보려고 책을 찾았다","correct":true},{"t":"예린이가 새 학기에 반장이 되었다","mis":"K4-2-u6-X24"},{"t":"예린이가 집에 가서 동생과 놀았다","mis":"K4-2-u6-X24"},{"t":"싹이 갑자기 말을 걸어왔다","mis":"K4-2-u6-X36"}],"explanation":["지금 이야기가 무엇을 묻나요?","「왜 싹이 났을까」예요.","그 물음에 이어져요."],"asset":{"type":"passage","lines":["예린이는 모르는 것이 생기면 책을 찾아보고 나서야 마음이 놓이는 아이다.","봄에 예린이는 흙만 담아 둔 빈 화분을 창가에 놓아두었다.","그런데 열흘쯤 지나자 그 화분에서 작은 싹 하나가 올라왔다.","예린이는 아무것도 심지 않았는데 싹이 난 까닭이 궁금했다."],"title":"빈 화분의 싹"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_review_a#14','kor',4,2,'u6','','g4_2_kor_u6_review_a','unit_review','K4-2-u6-C44',2,'mc','auto','나래는 일이 생기면 까닭부터 살피는 아이예요. 게시판 장면에서 나래의 다음 대사로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u6-X38','K4-2-u6-X35']::text[],false,'{"seq":14,"concept":"K4-2-u6-C44","difficulty":2,"kind":"mc","stem":"나래는 일이 생기면 까닭부터 살피는 아이예요. 게시판 장면에서 나래의 다음 대사로 알맞은 것은 무엇인가요?","options":[{"t":"「압정이 하나라서 무게를 못 버텼나 봐. 귀퉁이마다 꽂아 보자.」","correct":true},{"t":"「네가 잘못했으니 네가 다 해.」","mis":"K4-2-u6-X38"},{"t":"「몰라, 그냥 바닥에 두자.」","mis":"K4-2-u6-X38"},{"t":"「그림 이야기는 그만하고 놀자.」","mis":"K4-2-u6-X35"}],"explanation":["나래는 어떤 아이인가요?","까닭부터 살펴요.","압정 수를 봐요."],"asset":{"type":"speech","turns":[{"who":"나래","text":"(게시판 앞에서) 우리 모둠 그림이 바닥에 떨어져 있어."},{"who":"서진","text":"어제 내가 붙였는데, 압정을 하나만 꽂았나 봐."},{"who":"나래","text":"⋯⋯"},{"who":"서진","text":"( ? )"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_review_a#15','kor',4,2,'u6','','g4_2_kor_u6_review_a','unit_review','K4-2-u6-C24',2,'mc','auto','단원을 마치며 스스로 확인하기 표에 「아니요」가 나왔어요. 알맞게 한 것은 무엇인가요?',ARRAY['K4-2-u6-X21']::text[],false,'{"seq":15,"concept":"K4-2-u6-C24","difficulty":2,"kind":"mc","stem":"단원을 마치며 스스로 확인하기 표에 「아니요」가 나왔어요. 알맞게 한 것은 무엇인가요?","options":[{"t":"그 줄에 해당하는 차시로 돌아가 다시 읽어 보았다","correct":true},{"t":"보기 좋게 「예」로 고쳐 두었다","mis":"K4-2-u6-X21"},{"t":"「아니요」 줄은 넘기고 끝냈다","mis":"K4-2-u6-X21"},{"t":"친구와 점수를 견주었다","mis":"K4-2-u6-X21"}],"explanation":["점수가 없는 표예요.","고칠 곳을 찾아요.","그 줄로 돌아가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_review_a#16','kor',4,2,'u6','','g4_2_kor_u6_review_a','unit_review','K4-2-u6-C16',2,'mc','auto','「넘친 수돗가」에서 같은 일이 되풀이되지 않게 하는 방법으로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-2-u6-X48','K4-2-u6-X17','K4-2-u6-X16']::text[],false,'{"seq":16,"concept":"K4-2-u6-C16","difficulty":2,"kind":"mc","stem":"「넘친 수돗가」에서 같은 일이 되풀이되지 않게 하는 방법으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"거름망의 종이 조각을 걷어 내고 종이를 버리지 않도록 알린다","correct":true},{"t":"바닥의 물만 걸레로 닦아 둔다","mis":"K4-2-u6-X48"},{"t":"수돗가를 꽃으로 꾸민다","mis":"K4-2-u6-X17"},{"t":"지호에게 조심하라고만 말한다","mis":"K4-2-u6-X16"}],"explanation":["물이 넘친 까닭은?","거름망이 막혔어요.","까닭을 없애요."],"asset":{"type":"passage","lines":["과학실 수돗가 거름망에 종이 조각이 잔뜩 끼어 있었어요.","물이 잘 빠지지 않아 개수대에 물이 고였어요.","고인 물이 넘쳐 바닥으로 흘러내렸어요.","그 바람에 지나가던 지호가 미끄러질 뻔했어요.","지호는 걸레를 가져오기 전에 거름망부터 들여다보았어요."],"title":"넘친 수돗가"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_review_a#17','kor',4,2,'u6','','g4_2_kor_u6_review_a','unit_review','K4-2-u6-C53',3,'mc','auto','마지막 차시에 다시 나온 물음이에요. 이어질 내용을 상상하는 일에 대해 바르게 말한 것은 무엇인가요?',ARRAY['K4-2-u6-X25','K4-2-u6-X26','K4-2-u6-X49']::text[],false,'{"seq":17,"concept":"K4-2-u6-C53","difficulty":3,"kind":"mc","stem":"마지막 차시에 다시 나온 물음이에요. 이어질 내용을 상상하는 일에 대해 바르게 말한 것은 무엇인가요?","options":[{"t":"앞의 일과 이어지면서도 새로울 수 있다","correct":true},{"t":"상상은 앞 이야기와 아주 달라야 재미있다","mis":"K4-2-u6-X25"},{"t":"이어질 내용에도 정해진 답이 하나 있다","mis":"K4-2-u6-X26"},{"t":"새로우려면 앞 이야기를 잊어야 한다","mis":"K4-2-u6-X49"}],"explanation":["양쪽 극단은 오답이에요.","까닭을 달고 가요.","둘은 함께 갈 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_review_a#18','kor',4,2,'u6','','g4_2_kor_u6_review_a','unit_review','K4-2-u6-C39',3,'mc','auto','「빈 화분의 싹」을 읽고 세 친구가 상상한 뒷이야기 가운데 가장 자연스럽게 이어지는 것은 무엇인가요?',ARRAY['K4-2-u6-X29','K4-2-u6-X32','K4-2-u6-X25']::text[],false,'{"seq":18,"concept":"K4-2-u6-C39","difficulty":3,"kind":"mc","stem":"「빈 화분의 싹」을 읽고 세 친구가 상상한 뒷이야기 가운데 가장 자연스럽게 이어지는 것은 무엇인가요?","options":[{"t":"㉮ 식물 책을 빌려 잎 모양과 견주어 보았다","correct":true},{"t":"㉯ 싹이 하룻밤 사이에 천장까지 자랐다","mis":"K4-2-u6-X29"},{"t":"㉰ 궁금해하지 않고 화분을 치워 버렸다","mis":"K4-2-u6-X32"},{"t":"정답이 없으니 셋 다 똑같이 자연스럽다","mis":"K4-2-u6-X25"}],"explanation":["예린이는 어떤 아이인가요?","책을 찾아봐요.","그 성격과 이어져요."],"asset":{"type":"passage","lines":["㉮ 예린이는 도서관에서 식물 책을 빌려 싹의 잎 모양과 하나하나 견주어 보았다.","㉯ 싹이 하룻밤 사이에 교실 천장까지 자라 열매가 주렁주렁 열렸다.","㉰ 예린이는 싹이 왜 났는지 궁금해하지 않고 화분을 치워 버렸다."],"title":"세 친구가 상상한 뒷이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_review_a#19','kor',4,2,'u6','','g4_2_kor_u6_review_a','unit_review','K4-2-u6-C31',3,'mc','auto','「빈 화분의 싹」의 뒷이야기 ㉰(궁금해하지 않고 화분을 치워 버렸다)가 알맞지 않은 까닭은 무엇인가요?',ARRAY['K4-2-u6-X27','K4-2-u6-X28','K4-2-u6-X29']::text[],false,'{"seq":19,"concept":"K4-2-u6-C31","difficulty":3,"kind":"mc","stem":"「빈 화분의 싹」의 뒷이야기 ㉰(궁금해하지 않고 화분을 치워 버렸다)가 알맞지 않은 까닭은 무엇인가요?","options":[{"t":"모르면 책을 찾아봐야 마음이 놓이는 예린이의 성격과 이어지지 않아서","correct":true},{"t":"너무 평범한 일이라서","mis":"K4-2-u6-X27"},{"t":"문장이 짧아서","mis":"K4-2-u6-X28"},{"t":"싹이 자라지 않아 재미없어서","mis":"K4-2-u6-X29"}],"explanation":["평범함 · 길이는 기준이 아니에요.","예린이는 어떤 아이였나요?","성격과 끊어졌어요."],"asset":{"type":"passage","lines":["㉮ 예린이는 도서관에서 식물 책을 빌려 싹의 잎 모양과 하나하나 견주어 보았다.","㉯ 싹이 하룻밤 사이에 교실 천장까지 자라 열매가 주렁주렁 열렸다.","㉰ 예린이는 싹이 왜 났는지 궁금해하지 않고 화분을 치워 버렸다."],"title":"세 친구가 상상한 뒷이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_review_a#20','kor',4,2,'u6','','g4_2_kor_u6_review_a','unit_review','K4-2-u6-C40',3,'mc','auto','「빈 새집」에서 하람이가 새집 일을 그만두는 이야기를 자연스럽게 쓰려면 어떻게 해야 하나요?',ARRAY['K4-2-u6-X32','K4-2-u6-X26']::text[],false,'{"seq":20,"concept":"K4-2-u6-C40","difficulty":3,"kind":"mc","stem":"「빈 새집」에서 하람이가 새집 일을 그만두는 이야기를 자연스럽게 쓰려면 어떻게 해야 하나요?","options":[{"t":"하람이가 그만둘 수밖에 없는 까닭이 되는 일을 앞에 함께 쓴다","correct":true},{"t":"「하람이는 이제 새집이 싫어졌다」고만 쓴다","mis":"K4-2-u6-X32"},{"t":"까닭은 쓰지 않고 그만두는 행동만 쓴다","mis":"K4-2-u6-X32"},{"t":"하람이는 성격이 바뀌면 안 되니 쓸 수 없다","mis":"K4-2-u6-X26"}],"explanation":["날마다 해내던 하람이예요.","바뀌려면 까닭이 있어야 해요.","함께 써요."],"asset":{"type":"passage","lines":["하람이는 한번 마음먹은 일은 날마다 조금씩이라도 해내는 아이다.","봄에 하람이는 손수 만든 새집을 학교 뒤뜰 나무에 달았다.","그런데 열흘이 지나도 새집에 드나드는 새가 한 마리도 없었다.","새집 바로 아래에는 그네가 있어 쉬는 시간마다 아이들이 북적였다.","하람이는 새집과 그네를 번갈아 바라보았다."],"title":"빈 새집"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_review_a#21','kor',4,2,'u6','','g4_2_kor_u6_review_a','unit_review','K4-2-u6-C46',3,'mc','auto','역할놀이를 본 뒤 친구에게 해 줄 말로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-2-u6-X39','K4-2-u6-X40','K4-2-u6-X25']::text[],false,'{"seq":21,"concept":"K4-2-u6-C46","difficulty":3,"kind":"mc","stem":"역할놀이를 본 뒤 친구에게 해 줄 말로 가장 알맞은 것은 무엇인가요?","options":[{"t":"「찬욱이가 끝까지 안 굽히는 게 앞 장면이랑 이어져서 좋았어.」","correct":true},{"t":"「너희 모둠이 제일 웃겼으니 제일 잘했어.」","mis":"K4-2-u6-X39"},{"t":"「대사가 제일 길어서 제일 잘했어.」","mis":"K4-2-u6-X40"},{"t":"「앞 이야기랑 달라도 웃기면 다 괜찮아.」","mis":"K4-2-u6-X25"}],"explanation":["웃음 · 길이는 기준이 아니에요.","이어지는지를 봐요.","어디가 이어지나요?"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_review_a#22','kor',4,2,'u6','','g4_2_kor_u6_review_a','unit_review','K4-2-u6-C36',3,'mc','auto','「돌아온 우산」에서 효주를 따라가 이어 쓴다면 어떤 이야기가 자연스러운가요?',ARRAY['K4-2-u6-X31','K4-2-u6-X23','K4-2-u6-X36']::text[],false,'{"seq":22,"concept":"K4-2-u6-C36","difficulty":3,"kind":"mc","stem":"「돌아온 우산」에서 효주를 따라가 이어 쓴다면 어떤 이야기가 자연스러운가요?","options":[{"t":"효주가 매듭을 어디서 보았는지 떠올리며 동규이를 이끌고 간다","correct":true},{"t":"효주를 따라가도 동규이를 따라갈 때와 이야기가 똑같다","mis":"K4-2-u6-X31"},{"t":"효주가 「그냥 새로 사」라며 매듭 이야기를 끝내 버린다","mis":"K4-2-u6-X23"},{"t":"효주가 갑자기 우산 임자가 된다","mis":"K4-2-u6-X36"}],"explanation":["효주는 매듭을 보고 눈을 크게 떴어요.","무언가 알아본 거예요.","그 행동에서 이어져요."],"asset":{"type":"passage","lines":["[앞 이야기] 동규이는 궁금한 것이 생기면 확인해야 잠이 오는 아이다.","지난주 비 오는 날, 동규이는 학원 앞에 두고 온 파란 우산을 잃어버렸다.","손잡이에 이름표가 없었다. 짝 효주는 \"그냥 새로 사\" 하고 말았다.","사흘 뒤 아침, 교문 앞 은행나무 가지에 그 파란 우산이 걸려 있었다.","손잡이에는 처음 보는 빨간 실 매듭이 꽃 모양으로 단단히 묶여 있었다.","동규이는 어리둥절해서 우산을 든 채 교문 앞에서 머뭇거렸다.","그때 효주가 다가와 매듭을 보더니 눈을 크게 떴다. \"어? 이 매듭⋯⋯.\""],"title":"돌아온 우산"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_review_a#23','kor',4,2,'u6','','g4_2_kor_u6_review_a','unit_review','K4-2-u6-C5',4,'essay','teacher','1차시와 마지막 차시에 같은 물음 「이어질 내용을 상상할 때 가장 먼저 생각할 것은?」이 나왔어요. 내 답을 쓰고, 그 답을 이 단원의 이야기 하나에 어떻게 썼는지 예를 들어 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K4-2-u6-C5","difficulty":4,"kind":"essay","stem":"1차시와 마지막 차시에 같은 물음 「이어질 내용을 상상할 때 가장 먼저 생각할 것은?」이 나왔어요. 내 답을 쓰고, 그 답을 이 단원의 이야기 하나에 어떻게 썼는지 예를 들어 쓰세요.","answer_guide":{"answer":"예: 앞에서 어떤 일이 왜 일어났는지를 가장 먼저 생각한다. 「연을 놓친 날」에서 바람이 세서 실이 끊어져 연이 나무에 걸렸고 해가 기울고 있었으니, 다음 날 아침 장대를 들고 다시 오는 이야기를 상상했다.","scoring_points":["앞에서 무슨 일이 왜 일어났는지를 먼저 생각한다고 썼는가","단원의 이야기 하나를 골랐는가","앞의 일이 까닭이 되어 상상한 예를 들었는가"]},"explanation":["처음과 끝이 같은 물음이에요.","앞에서 출발해요.","예를 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_review_a#24','kor',4,2,'u6','','g4_2_kor_u6_review_a','unit_review','K4-2-u6-C30',4,'essay','teacher','「빈 화분의 싹」의 뒷이야기를 세 문장으로 쓰세요. 예린이의 성격 · 이야기의 흐름 · 원인과 결과가 모두 이어지게 쓰고, 어디에서 이어지는지 한 가지 밝히세요.','{}'::text[],false,'{"seq":24,"concept":"K4-2-u6-C30","difficulty":4,"kind":"essay","stem":"「빈 화분의 싹」의 뒷이야기를 세 문장으로 쓰세요. 예린이의 성격 · 이야기의 흐름 · 원인과 결과가 모두 이어지게 쓰고, 어디에서 이어지는지 한 가지 밝히세요.","answer_guide":{"answer":"예: 예린이는 싹의 잎을 공책에 그려 도서관으로 갔다. 식물 책을 넘기다가 잎 모양이 똑같은 그림을 찾았는데, 지난해 우리 반이 기른 해바라기였다. 예린이는 그 흙이 지난해 해바라기 화분의 흙이었다는 것을 알고 무릎을 쳤다. — 책을 찾아봐야 마음이 놓이는 성격과 이어진다.","scoring_points":["뒷이야기를 세 문장으로 썼는가","성격 · 흐름 · 원인과 결과가 이어지는가","이어지는 곳을 한 가지 밝혔는가"]},"explanation":["예린이라면?","싹이 난 까닭은?","어디가 이어지나요?"],"asset":{"type":"passage","lines":["예린이는 모르는 것이 생기면 책을 찾아보고 나서야 마음이 놓이는 아이다.","봄에 예린이는 흙만 담아 둔 빈 화분을 창가에 놓아두었다.","그런데 열흘쯤 지나자 그 화분에서 작은 싹 하나가 올라왔다.","예린이는 아무것도 심지 않았는데 싹이 난 까닭이 궁금했다."],"title":"빈 화분의 싹"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_review_a#25','kor',4,2,'u6','','g4_2_kor_u6_review_a','unit_review','K4-2-u6-C42',4,'essay','teacher','모둠에서 이야기 이어 말하기를 해요. 첫 문장 「쉬는 시간에 공이 체육 창고 지붕 위로 올라갔습니다.」 다음에 세 문장을 원인과 결과로 이어 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K4-2-u6-C42","difficulty":4,"kind":"essay","stem":"모둠에서 이야기 이어 말하기를 해요. 첫 문장 「쉬는 시간에 공이 체육 창고 지붕 위로 올라갔습니다.」 다음에 세 문장을 원인과 결과로 이어 쓰세요.","answer_guide":{"answer":"예: 그래서 우리는 체육 선생님께 공을 내려 달라고 부탁드렸습니다. 선생님께서는 긴 막대를 가져와 공을 살살 밀어 주셨습니다. 공을 되찾은 우리는 다음부터 창고 쪽으로는 공을 차지 않기로 했습니다.","scoring_points":["세 문장을 이어 썼는가","문장마다 앞 문장이 까닭이 되는가","상관없는 일 · 갑자기 큰일 · 끝난 일 되돌리기가 없는가"]},"explanation":["앞 문장이 까닭이에요.","「그래서」를 넣어 봐요.","끊기지 않게요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_review_b#1','kor',4,2,'u6','','g4_2_kor_u6_review_b','unit_review','K4-2-u6-C5',1,'mc','auto','「빈 새집」의 뒷이야기를 쓰려고 해요. 가장 먼저 할 일은 무엇인가요?',ARRAY['K4-2-u6-X05','K4-2-u6-X06','K4-2-u6-X26']::text[],false,'{"seq":1,"concept":"K4-2-u6-C5","difficulty":1,"kind":"mc","stem":"「빈 새집」의 뒷이야기를 쓰려고 해요. 가장 먼저 할 일은 무엇인가요?","options":[{"t":"새가 왜 오지 않았는지 앞 이야기를 다시 살핀다","correct":true},{"t":"가장 신기한 장면부터 떠올린다","mis":"K4-2-u6-X05"},{"t":"세 쪽을 채울 만큼 길게 쓸 거리부터 모은다","mis":"K4-2-u6-X06"},{"t":"친구가 쓴 뒷이야기를 그대로 따라 쓴다","mis":"K4-2-u6-X26"}],"explanation":["앞에서 시작해요.","무슨 일이 왜 일어났나요?","그다음에 상상해요."],"asset":{"type":"passage","lines":["하람이는 한번 마음먹은 일은 날마다 조금씩이라도 해내는 아이다.","봄에 하람이는 손수 만든 새집을 학교 뒤뜰 나무에 달았다.","그런데 열흘이 지나도 새집에 드나드는 새가 한 마리도 없었다.","새집 바로 아래에는 그네가 있어 쉬는 시간마다 아이들이 북적였다.","하람이는 새집과 그네를 번갈아 바라보았다."],"title":"빈 새집"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_review_b#2','kor',4,2,'u6','','g4_2_kor_u6_review_b','unit_review','K4-2-u6-C1',1,'mc','auto','「밤새 비가 많이 내려서 아침에 흙길이 질척였다.」에서 원인은 무엇인가요?',ARRAY['K4-2-u6-X01','K4-2-u6-X04']::text[],false,'{"seq":2,"concept":"K4-2-u6-C1","difficulty":1,"kind":"mc","stem":"「밤새 비가 많이 내려서 아침에 흙길이 질척였다.」에서 원인은 무엇인가요?","options":[{"t":"밤새 비가 많이 내렸다","correct":true},{"t":"아침에 흙길이 질척였다","mis":"K4-2-u6-X01"},{"t":"아침","mis":"K4-2-u6-X04"},{"t":"흙길","mis":"K4-2-u6-X04"}],"explanation":["무엇 때문에 질척였나요?","까닭을 찾아요.","비가 내린 것이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_review_b#3','kor',4,2,'u6','','g4_2_kor_u6_review_b','unit_review','K4-2-u6-C48',1,'mc','auto','「우리는 종이 상자(   ) 작은 집을 만들었다.」의 빈칸에 알맞은 것은 무엇인가요?',ARRAY['K4-2-u6-X41']::text[],false,'{"seq":3,"concept":"K4-2-u6-C48","difficulty":1,"kind":"mc","stem":"「우리는 종이 상자(   ) 작은 집을 만들었다.」의 빈칸에 알맞은 것은 무엇인가요?","options":[{"t":"로써","correct":true},{"t":"로서","mis":"K4-2-u6-X41"},{"t":"에게","mis":"K4-2-u6-X41"},{"t":"처럼","mis":"K4-2-u6-X41"}],"explanation":["종이 상자는 재료예요.","재료면 (으)로써","로써예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_review_b#4','kor',4,2,'u6','','g4_2_kor_u6_review_b','unit_review','K4-2-u6-C35',1,'mc','auto','「어리둥절하다」의 뜻으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u6-X30']::text[],false,'{"seq":4,"concept":"K4-2-u6-C35","difficulty":1,"kind":"mc","stem":"「어리둥절하다」의 뜻으로 알맞은 것은 무엇인가요?","options":[{"t":"무슨 영문인지 몰라 얼떨떨하다","correct":true},{"t":"주의 깊게 자세히 보다","mis":"K4-2-u6-X30"},{"t":"선뜻 하지 못하고 자꾸 망설이다","mis":"K4-2-u6-X30"},{"t":"기분이 좋아 들뜨다","mis":"K4-2-u6-X30"}],"explanation":["동규이가 매듭을 본 순간이에요.","무슨 일인지 몰라요.","얼떨떨해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_review_b#5','kor',4,2,'u6','','g4_2_kor_u6_review_b','unit_review','K4-2-u6-C51',1,'mc','auto','「않다」를 바르게 소리 낸 것은 무엇인가요?',ARRAY['K4-2-u6-X45','K4-2-u6-X44']::text[],false,'{"seq":5,"concept":"K4-2-u6-C51","difficulty":1,"kind":"mc","stem":"「않다」를 바르게 소리 낸 것은 무엇인가요?","options":[{"t":"[안타]","correct":true},{"t":"[안따]","mis":"K4-2-u6-X45"},{"t":"[안나]","mis":"K4-2-u6-X45"},{"t":"[알타]","mis":"K4-2-u6-X44"}],"explanation":["ㄶ의 ㅎ이 뒤와 합쳐져요.","ㅎ + ㄷ → [ㅌ]","[안타]예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_review_b#6','kor',4,2,'u6','','g4_2_kor_u6_review_b','unit_review','K4-2-u6-C34',1,'mc','auto','「빈 화분의 싹」에서 일어난 일은 무엇인가요?',ARRAY['K4-2-u6-X08']::text[],false,'{"seq":6,"concept":"K4-2-u6-C34","difficulty":1,"kind":"mc","stem":"「빈 화분의 싹」에서 일어난 일은 무엇인가요?","options":[{"t":"흙만 담아 둔 화분에서 작은 싹 하나가 올라왔다","correct":true},{"t":"예린이가 화분에 씨앗을 심었다","mis":"K4-2-u6-X08"},{"t":"싹이 교실 천장까지 자랐다","mis":"K4-2-u6-X08"},{"t":"화분이 창가에서 떨어졌다","mis":"K4-2-u6-X08"}],"explanation":["무엇이 달라졌나요?","아무것도 심지 않았어요.","싹이 올라왔어요."],"asset":{"type":"passage","lines":["예린이는 모르는 것이 생기면 책을 찾아보고 나서야 마음이 놓이는 아이다.","봄에 예린이는 흙만 담아 둔 빈 화분을 창가에 놓아두었다.","그런데 열흘쯤 지나자 그 화분에서 작은 싹 하나가 올라왔다.","예린이는 아무것도 심지 않았는데 싹이 난 까닭이 궁금했다."],"title":"빈 화분의 싹"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_review_b#7','kor',4,2,'u6','','g4_2_kor_u6_review_b','unit_review','K4-2-u6-C21',1,'mc','auto','「넘친 수돗가」의 지호가 걸레를 가져오기 전에 거름망부터 들여다본 행동에서 알 수 있는 성격은 무엇인가요?',ARRAY['K4-2-u6-X20','K4-2-u6-X23']::text[],false,'{"seq":7,"concept":"K4-2-u6-C21","difficulty":1,"kind":"mc","stem":"「넘친 수돗가」의 지호가 걸레를 가져오기 전에 거름망부터 들여다본 행동에서 알 수 있는 성격은 무엇인가요?","options":[{"t":"일이 생기면 까닭부터 살피는 성격","correct":true},{"t":"겁이 많아 아무것도 못 하는 성격","mis":"K4-2-u6-X20"},{"t":"장난을 좋아하는 성격","mis":"K4-2-u6-X20"},{"t":"남에게 일을 미루는 성격","mis":"K4-2-u6-X23"}],"explanation":["무엇부터 했나요?","거름망을 보았어요.","까닭부터 살펴요."],"asset":{"type":"passage","lines":["과학실 수돗가 거름망에 종이 조각이 잔뜩 끼어 있었어요.","물이 잘 빠지지 않아 개수대에 물이 고였어요.","고인 물이 넘쳐 바닥으로 흘러내렸어요.","그 바람에 지나가던 지호가 미끄러질 뻔했어요.","지호는 걸레를 가져오기 전에 거름망부터 들여다보았어요."],"title":"넘친 수돗가"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_review_b#8','kor',4,2,'u6','','g4_2_kor_u6_review_b','unit_review','K4-2-u6-C43',1,'mc','auto','이어 말하기에서 이야기가 끊기는 때는 언제인가요?',ARRAY['K4-2-u6-X35','K4-2-u6-X51','K4-2-u6-X34']::text[],false,'{"seq":8,"concept":"K4-2-u6-C43","difficulty":1,"kind":"mc","stem":"이어 말하기에서 이야기가 끊기는 때는 언제인가요?","options":[{"t":"앞과 아무 상관 없는 일을 새로 꺼낼 때","correct":true},{"t":"앞 문장이 까닭이 되는 문장을 이을 때","mis":"K4-2-u6-X35"},{"t":"「그래서」를 넣어도 말이 될 때","mis":"K4-2-u6-X51"},{"t":"앞 사람의 문장을 끝까지 들었을 때","mis":"K4-2-u6-X34"}],"explanation":["끊기는 때를 찾아요.","상관없는 일은?","끊겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_review_b#9','kor',4,2,'u6','','g4_2_kor_u6_review_b','unit_review','K4-2-u6-C2',2,'mc','auto','「거름망에 종이가 끼었다 → ㉠ → 고인 물이 넘쳐 바닥으로 흘렀다」에서 ㉠에 알맞은 것은 무엇인가요?',ARRAY['K4-2-u6-X19','K4-2-u6-X18']::text[],false,'{"seq":9,"concept":"K4-2-u6-C2","difficulty":2,"kind":"mc","stem":"「거름망에 종이가 끼었다 → ㉠ → 고인 물이 넘쳐 바닥으로 흘렀다」에서 ㉠에 알맞은 것은 무엇인가요?","options":[{"t":"물이 잘 빠지지 않아 개수대에 물이 고였다","correct":true},{"t":"지호가 미끄러질 뻔했다","mis":"K4-2-u6-X19"},{"t":"과학실 창문이 열려 있었다","mis":"K4-2-u6-X18"},{"t":"지호가 거름망을 들여다보았다","mis":"K4-2-u6-X19"}],"explanation":["앞 일 때문에 생기고","뒤 일을 생기게 해요.","물이 고였어요."],"asset":{"type":"passage","lines":["과학실 수돗가 거름망에 종이 조각이 잔뜩 끼어 있었어요.","물이 잘 빠지지 않아 개수대에 물이 고였어요.","고인 물이 넘쳐 바닥으로 흘러내렸어요.","그 바람에 지나가던 지호가 미끄러질 뻔했어요.","지호는 걸레를 가져오기 전에 거름망부터 들여다보았어요."],"title":"넘친 수돗가"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_review_b#10','kor',4,2,'u6','','g4_2_kor_u6_review_b','unit_review','K4-2-u6-C18',2,'mc','auto','「넘친 수돗가」에서 찾을 수 있는 원인과 결과의 짝이 아닌 것은 무엇인가요?',ARRAY['K4-2-u6-X18']::text[],false,'{"seq":10,"concept":"K4-2-u6-C18","difficulty":2,"kind":"mc","stem":"「넘친 수돗가」에서 찾을 수 있는 원인과 결과의 짝이 아닌 것은 무엇인가요?","options":[{"t":"과학실이 넓어서 → 거름망이 막혔다","correct":true},{"t":"물이 고여서 → 바닥으로 넘쳤다","mis":"K4-2-u6-X18"},{"t":"물이 넘쳐서 → 지호가 미끄러질 뻔했다","mis":"K4-2-u6-X18"},{"t":"종이가 끼어서 → 물이 잘 빠지지 않았다","mis":"K4-2-u6-X18"}],"explanation":["이야기에 나온 일인가요?","과학실 크기는 나오지 않아요.","그것이 짝이 아니에요."],"asset":{"type":"passage","lines":["과학실 수돗가 거름망에 종이 조각이 잔뜩 끼어 있었어요.","물이 잘 빠지지 않아 개수대에 물이 고였어요.","고인 물이 넘쳐 바닥으로 흘러내렸어요.","그 바람에 지나가던 지호가 미끄러질 뻔했어요.","지호는 걸레를 가져오기 전에 거름망부터 들여다보았어요."],"title":"넘친 수돗가"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_review_b#11','kor',4,2,'u6','','g4_2_kor_u6_review_b','unit_review','K4-2-u6-C10',2,'mc','auto','예상과 실제를 견주어 말할 때 꼭 들어가야 할 것은 무엇인가요?',ARRAY['K4-2-u6-X11','K4-2-u6-X28','K4-2-u6-X26']::text[],false,'{"seq":11,"concept":"K4-2-u6-C10","difficulty":2,"kind":"mc","stem":"예상과 실제를 견주어 말할 때 꼭 들어가야 할 것은 무엇인가요?","options":[{"t":"무엇을 까닭으로 그렇게 예상했는지","correct":true},{"t":"좋았는지 아쉬웠는지","mis":"K4-2-u6-X11"},{"t":"예상이 몇 글자였는지","mis":"K4-2-u6-X28"},{"t":"친구 예상과 같았는지","mis":"K4-2-u6-X26"}],"explanation":["느낌이 아니에요.","까닭이 들어가요.","무엇을 까닭으로?"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_review_b#12','kor',4,2,'u6','','g4_2_kor_u6_review_b','unit_review','K4-2-u6-C12',2,'mc','auto','「빈 화분의 싹」에서 싹이 난 까닭을 예상한 것 가운데 이야기에 근거가 있는 것은 무엇인가요?',ARRAY['K4-2-u6-X13','K4-2-u6-X10']::text[],false,'{"seq":12,"concept":"K4-2-u6-C12","difficulty":2,"kind":"mc","stem":"「빈 화분의 싹」에서 싹이 난 까닭을 예상한 것 가운데 이야기에 근거가 있는 것은 무엇인가요?","options":[{"t":"창가에 둔 화분이라 바깥에서 날아온 씨앗이 떨어졌을 것이다","correct":true},{"t":"화분이 혼자 씨앗을 만들어 냈을 것이다","mis":"K4-2-u6-X13"},{"t":"예린이가 꿈에서 씨앗을 심었을 것이다","mis":"K4-2-u6-X13"},{"t":"싹이 난 까닭은 하나로 정해져 있을 것이다","mis":"K4-2-u6-X10"}],"explanation":["화분이 어디에 있었나요?","창가예요.","근거가 이야기에 있어요."],"asset":{"type":"passage","lines":["예린이는 모르는 것이 생기면 책을 찾아보고 나서야 마음이 놓이는 아이다.","봄에 예린이는 흙만 담아 둔 빈 화분을 창가에 놓아두었다.","그런데 열흘쯤 지나자 그 화분에서 작은 싹 하나가 올라왔다.","예린이는 아무것도 심지 않았는데 싹이 난 까닭이 궁금했다."],"title":"빈 화분의 싹"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_review_b#13','kor',4,2,'u6','','g4_2_kor_u6_review_b','unit_review','K4-2-u6-C27',2,'mc','auto','「넘친 수돗가」를 처음 · 가운데 · 지금으로 늘어놓았을 때 「지금」에 해당하는 것은 무엇인가요?',ARRAY['K4-2-u6-X19','K4-2-u6-X24']::text[],false,'{"seq":13,"concept":"K4-2-u6-C27","difficulty":2,"kind":"mc","stem":"「넘친 수돗가」를 처음 · 가운데 · 지금으로 늘어놓았을 때 「지금」에 해당하는 것은 무엇인가요?","options":[{"t":"지호가 걸레를 가져오기 전에 거름망부터 들여다보았다","correct":true},{"t":"거름망에 종이 조각이 잔뜩 끼어 있었다","mis":"K4-2-u6-X19"},{"t":"물이 잘 빠지지 않아 물이 고였다","mis":"K4-2-u6-X19"},{"t":"지호가 과학실 청소 당번을 정했다","mis":"K4-2-u6-X24"}],"explanation":["맨 마지막에 있었던 일이에요.","지금 어디까지 왔나요?","거름망을 보고 있어요."],"asset":{"type":"passage","lines":["과학실 수돗가 거름망에 종이 조각이 잔뜩 끼어 있었어요.","물이 잘 빠지지 않아 개수대에 물이 고였어요.","고인 물이 넘쳐 바닥으로 흘러내렸어요.","그 바람에 지나가던 지호가 미끄러질 뻔했어요.","지호는 걸레를 가져오기 전에 거름망부터 들여다보았어요."],"title":"넘친 수돗가"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_review_b#14','kor',4,2,'u6','','g4_2_kor_u6_review_b','unit_review','K4-2-u6-C44',2,'mc','auto','찬욱이는 한번 아니라고 하면 잘 굽히지 않는 아이예요. 색연필 장면에서 찬욱이다운 대사는 무엇인가요?',ARRAY['K4-2-u6-X38','K4-2-u6-X35','K4-2-u6-X36']::text[],false,'{"seq":14,"concept":"K4-2-u6-C44","difficulty":2,"kind":"mc","stem":"찬욱이는 한번 아니라고 하면 잘 굽히지 않는 아이예요. 색연필 장면에서 찬욱이다운 대사는 무엇인가요?","options":[{"t":"「미술실엔 분명히 없어. 그래도 네가 가 보자니까 가 볼게.」","correct":true},{"t":"「네 말이 맞아. 내가 두고 왔나 봐.」","mis":"K4-2-u6-X38"},{"t":"「색연필은 됐고, 축구하러 가자.」","mis":"K4-2-u6-X35"},{"t":"「갑자기 색연필이 하늘에서 떨어지면 좋겠다.」","mis":"K4-2-u6-X36"}],"explanation":["찬욱이는 쉽게 굽히지 않아요.","그래도 방법은 따를 수 있어요.","성격이 드러나요."],"asset":{"type":"speech","turns":[{"who":"찬욱","text":"(가방을 뒤지며) 어? 내 색연필 어디 갔지?"},{"who":"효주","text":"아까 미술실에 두고 온 거 아니야?"},{"who":"찬욱","text":"아니야, 분명히 넣었는데⋯⋯."},{"who":"효주","text":"그럼 ⋯⋯"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_review_b#15','kor',4,2,'u6','','g4_2_kor_u6_review_b','unit_review','K4-2-u6-C13',2,'mc','auto','영상을 보며 메모할 때 알맞은 방법은 무엇인가요?',ARRAY['K4-2-u6-X14','K4-2-u6-X07']::text[],false,'{"seq":15,"concept":"K4-2-u6-C13","difficulty":2,"kind":"mc","stem":"영상을 보며 메모할 때 알맞은 방법은 무엇인가요?","options":[{"t":"큰 사건, 그 까닭, 그래서 어떻게 되었는지를 화살표로 짧게 적는다","correct":true},{"t":"나온 말을 모두 그대로 받아 적는다","mis":"K4-2-u6-X14"},{"t":"글자를 다 못 쓰면 아예 적지 않는다","mis":"K4-2-u6-X14"},{"t":"재미있던 장면 하나만 크게 그린다","mis":"K4-2-u6-X07"}],"explanation":["짧게 적어요.","화살표도 좋아요.","사건 · 왜 · 그래서"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_review_b#16','kor',4,2,'u6','','g4_2_kor_u6_review_b','unit_review','K4-2-u6-C54',2,'mc','auto','아침마다 지각하는 까닭을 찾은 친구가 한 일로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u6-X48']::text[],false,'{"seq":16,"concept":"K4-2-u6-C54","difficulty":2,"kind":"mc","stem":"아침마다 지각하는 까닭을 찾은 친구가 한 일로 알맞은 것은 무엇인가요?","options":[{"t":"알람을 끄고 다시 잠드는 것이 까닭이라, 알람을 침대에서 먼 곳에 두었다","correct":true},{"t":"까닭은 찾지 않고 「내일은 일찍 일어나야지」만 되뇌었다","mis":"K4-2-u6-X48"},{"t":"지각은 까닭 없이 생기는 일이라 그냥 두었다","mis":"K4-2-u6-X48"},{"t":"원인과 결과는 이야기에만 있으니 생각하지 않았다","mis":"K4-2-u6-X48"}],"explanation":["생활 속에도 까닭이 있어요.","까닭을 찾아요.","그다음을 바꿔요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_review_b#17','kor',4,2,'u6','','g4_2_kor_u6_review_b','unit_review','K4-2-u6-C53',3,'mc','auto','「빈 화분의 싹」의 뒷이야기로 「앞과 이어지면서도 새로운」 것은 무엇인가요?',ARRAY['K4-2-u6-X25','K4-2-u6-X32','K4-2-u6-X26']::text[],false,'{"seq":17,"concept":"K4-2-u6-C53","difficulty":3,"kind":"mc","stem":"「빈 화분의 싹」의 뒷이야기로 「앞과 이어지면서도 새로운」 것은 무엇인가요?","options":[{"t":"예린이가 책에서 찾은 잎과 견주다가, 그 싹이 지난해 교실에서 기른 해바라기의 씨였다는 것을 알아냈다","correct":true},{"t":"싹이 하룻밤 사이에 교실 천장까지 자라 열매가 열렸다","mis":"K4-2-u6-X25"},{"t":"예린이는 싹을 그냥 두고 아무 생각도 하지 않았다","mis":"K4-2-u6-X32"},{"t":"뒷이야기는 「싹이 자랐다」 하나만 정답이다","mis":"K4-2-u6-X26"}],"explanation":["책을 찾아보는 예린이예요.","새로운 사실이 나왔어요.","그런데 까닭과 이어져요."],"asset":{"type":"passage","lines":["예린이는 모르는 것이 생기면 책을 찾아보고 나서야 마음이 놓이는 아이다.","봄에 예린이는 흙만 담아 둔 빈 화분을 창가에 놓아두었다.","그런데 열흘쯤 지나자 그 화분에서 작은 싹 하나가 올라왔다.","예린이는 아무것도 심지 않았는데 싹이 난 까닭이 궁금했다."],"title":"빈 화분의 싹"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_review_b#18','kor',4,2,'u6','','g4_2_kor_u6_review_b','unit_review','K4-2-u6-C32',3,'mc','auto','「연을 놓친 날」의 두 뒷이야기 ㉮(긴 장대)와 ㉯(용) 가운데 ㉮를 고른 까닭으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u6-X29','K4-2-u6-X28','K4-2-u6-X26']::text[],false,'{"seq":18,"concept":"K4-2-u6-C32","difficulty":3,"kind":"mc","stem":"「연을 놓친 날」의 두 뒷이야기 ㉮(긴 장대)와 ㉯(용) 가운데 ㉮를 고른 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"끝을 봐야 하는 경민이의 성격과 나무에 걸린 연이라는 상황에 이어지기 때문에","correct":true},{"t":"㉯보다 덜 놀랍기 때문에","mis":"K4-2-u6-X29"},{"t":"㉯보다 문장이 길기 때문에","mis":"K4-2-u6-X28"},{"t":"㉮가 정해진 답이기 때문에","mis":"K4-2-u6-X26"}],"explanation":["놀라움은 기준이 아니에요.","성격과 흐름을 봐요.","이어지는 쪽이에요."],"asset":{"type":"passage","lines":["㉮ 경민이는 다음 날 아침 일찍 둑에 나가 긴 장대를 들고 다시 나무 아래에 섰다.","㉯ 그때 하늘에서 커다란 용이 내려와 연을 물어다 경민이에게 주었다."],"title":"두 친구가 상상한 뒷이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_review_b#19','kor',4,2,'u6','','g4_2_kor_u6_review_b','unit_review','K4-2-u6-C31',3,'mc','auto','「넘친 수돗가」 뒤에 「지호는 물에는 관심 없이 그냥 교실로 돌아갔다」를 쓰면 알맞지 않은 까닭은 무엇인가요?',ARRAY['K4-2-u6-X27','K4-2-u6-X28','K4-2-u6-X29']::text[],false,'{"seq":19,"concept":"K4-2-u6-C31","difficulty":3,"kind":"mc","stem":"「넘친 수돗가」 뒤에 「지호는 물에는 관심 없이 그냥 교실로 돌아갔다」를 쓰면 알맞지 않은 까닭은 무엇인가요?","options":[{"t":"까닭부터 살피던 지호의 행동과 이어지지 않아서","correct":true},{"t":"교실로 돌아가는 일은 너무 흔해서","mis":"K4-2-u6-X27"},{"t":"한 문장밖에 안 되어서","mis":"K4-2-u6-X28"},{"t":"물이 넘치는 장면이 더 나오지 않아서","mis":"K4-2-u6-X29"}],"explanation":["지호가 앞에서 무엇을 했나요?","거름망부터 보았어요.","그 행동과 끊어졌어요."],"asset":{"type":"passage","lines":["과학실 수돗가 거름망에 종이 조각이 잔뜩 끼어 있었어요.","물이 잘 빠지지 않아 개수대에 물이 고였어요.","고인 물이 넘쳐 바닥으로 흘러내렸어요.","그 바람에 지나가던 지호가 미끄러질 뻔했어요.","지호는 걸레를 가져오기 전에 거름망부터 들여다보았어요."],"title":"넘친 수돗가"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_review_b#20','kor',4,2,'u6','','g4_2_kor_u6_review_b','unit_review','K4-2-u6-C40',3,'mc','auto','다음 가운데 성격이 바뀐 까닭이 함께 쓰여 자연스럽게 이어지는 것은 무엇인가요?',ARRAY['K4-2-u6-X32']::text[],false,'{"seq":20,"concept":"K4-2-u6-C40","difficulty":3,"kind":"mc","stem":"다음 가운데 성격이 바뀐 까닭이 함께 쓰여 자연스럽게 이어지는 것은 무엇인가요?","options":[{"t":"「그동안 혼자 하던 경민이는 장대를 들어 준 아버지를 보고, 처음으로 남에게 도와 달라고 했다.」","correct":true},{"t":"「경민이는 갑자기 끝까지 하는 아이가 아니게 되었다.」","mis":"K4-2-u6-X32"},{"t":"「경민이는 연을 잊고 축구를 했다.」","mis":"K4-2-u6-X32"},{"t":"「경민이는 이제 다른 아이가 되었다. 끝.」","mis":"K4-2-u6-X32"}],"explanation":["바뀌었다고만 하면 끊겨요.","왜 바뀌었나요?","까닭이 함께 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_review_b#21','kor',4,2,'u6','','g4_2_kor_u6_review_b','unit_review','K4-2-u6-C45',3,'mc','auto','「빈 새집」을 역할놀이로 하려고 해요. 연습하기 전에 정한 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-2-u6-X50','K4-2-u6-X39']::text[],false,'{"seq":21,"concept":"K4-2-u6-C45","difficulty":3,"kind":"mc","stem":"「빈 새집」을 역할놀이로 하려고 해요. 연습하기 전에 정한 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"하람이는 「날마다 조금씩 해내는 아이」, 새집을 옮기는 까닭은 「그네 아래가 시끄러워서」, 몸짓은 「새집을 조심히 떼어 안기」","correct":true},{"t":"하람이 대사를 길게 늘려 모두 외우기","mis":"K4-2-u6-X50"},{"t":"가장 웃긴 장면 하나만 정하기","mis":"K4-2-u6-X39"},{"t":"대사 없이 몸짓만 크게 하기","mis":"K4-2-u6-X50"}],"explanation":["성격 한 줄","까닭 붙이기","몸짓도 함께"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_review_b#22','kor',4,2,'u6','','g4_2_kor_u6_review_b','unit_review','K4-2-u6-C37',3,'mc','auto','「빈 화분의 싹」에서 예린이의 성격을 이용해 상상한 것으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u6-X32','K4-2-u6-X25','K4-2-u6-X23']::text[],false,'{"seq":22,"concept":"K4-2-u6-C37","difficulty":3,"kind":"mc","stem":"「빈 화분의 싹」에서 예린이의 성격을 이용해 상상한 것으로 알맞은 것은 무엇인가요?","options":[{"t":"예린이는 싹의 잎을 그려 두고 도서관에서 비슷한 잎을 찾아보았다","correct":true},{"t":"예린이는 싹을 뽑아 버리고 잊었다","mis":"K4-2-u6-X32"},{"t":"싹이 예린이에게 자기 이름을 알려 주었다","mis":"K4-2-u6-X25"},{"t":"예린이는 친구에게 화분을 그냥 주어 버렸다","mis":"K4-2-u6-X23"}],"explanation":["예린이는 책을 찾아봐요.","그래야 마음이 놓여요.","그 성격대로요."],"asset":{"type":"passage","lines":["예린이는 모르는 것이 생기면 책을 찾아보고 나서야 마음이 놓이는 아이다.","봄에 예린이는 흙만 담아 둔 빈 화분을 창가에 놓아두었다.","그런데 열흘쯤 지나자 그 화분에서 작은 싹 하나가 올라왔다.","예린이는 아무것도 심지 않았는데 싹이 난 까닭이 궁금했다."],"title":"빈 화분의 싹"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_review_b#23','kor',4,2,'u6','','g4_2_kor_u6_review_b','unit_review','K4-2-u6-C53',4,'essay','teacher','「상상은 앞과 아주 달라야 재미있다」는 친구와 「이어질 내용에도 정답이 하나 있다」는 친구에게 각각 해 줄 말을 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K4-2-u6-C53","difficulty":4,"kind":"essay","stem":"「상상은 앞과 아주 달라야 재미있다」는 친구와 「이어질 내용에도 정답이 하나 있다」는 친구에게 각각 해 줄 말을 쓰세요.","answer_guide":{"answer":"예: 첫째 친구에게는 「앞과 아주 다르면 읽는 사람이 왜 그렇게 됐는지 몰라 갸웃해. 까닭을 달면 새로운 일도 이어질 수 있어.」라고 말한다. 둘째 친구에게는 「앞의 일과 이어지기만 하면 친구마다 다른 이야기를 써도 돼. 정답은 없어.」라고 말한다.","scoring_points":["첫째 친구에게 까닭과 이어짐을 들어 말했는가","둘째 친구에게 정답이 없다는 것을 들어 말했는가","이어짐과 새로움이 함께 갈 수 있다는 생각이 드러나는가"]},"explanation":["양쪽 모두 치우쳤어요.","까닭을 달아요.","정답은 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_review_b#24','kor',4,2,'u6','','g4_2_kor_u6_review_b','unit_review','K4-2-u6-C37',4,'essay','teacher','「넘친 수돗가」의 뒷이야기를 서너 문장으로 쓰세요. 까닭부터 살피는 지호의 성격과 거름망이라는 까닭이 드러나게 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K4-2-u6-C37","difficulty":4,"kind":"essay","stem":"「넘친 수돗가」의 뒷이야기를 서너 문장으로 쓰세요. 까닭부터 살피는 지호의 성격과 거름망이라는 까닭이 드러나게 쓰세요.","answer_guide":{"answer":"예: 지호는 거름망에 낀 종이 조각을 집게로 하나씩 걷어 냈다. 그러자 고인 물이 소용돌이치며 빠져나갔다. 지호는 종이가 왜 거기 있었는지 궁금해 둘러보다가, 수돗가 옆에 휴지통이 없다는 것을 알았다. 지호는 선생님께 여쭈어 수돗가 옆에 작은 휴지통을 놓았다.","scoring_points":["서너 문장으로 썼는가","까닭부터 살피는 지호의 성격이 드러나는가","거름망이 까닭이 되어 다음 일이 생기는가"]},"explanation":["지호라면?","거름망이 까닭이에요.","그다음까지 이어요."],"asset":{"type":"passage","lines":["과학실 수돗가 거름망에 종이 조각이 잔뜩 끼어 있었어요.","물이 잘 빠지지 않아 개수대에 물이 고였어요.","고인 물이 넘쳐 바닥으로 흘러내렸어요.","그 바람에 지나가던 지호가 미끄러질 뻔했어요.","지호는 걸레를 가져오기 전에 거름망부터 들여다보았어요."],"title":"넘친 수돗가"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_review_b#25','kor',4,2,'u6','','g4_2_kor_u6_review_b','unit_review','K4-2-u6-C44',4,'essay','teacher','게시판 장면을 역할놀이로 이어 가려고 해요. 까닭부터 살피는 나래와, 자기 잘못이면 먼저 인정하는 서진이의 다음 대사를 한 줄씩 쓰고 몸짓을 하나씩 붙이세요.','{}'::text[],false,'{"seq":25,"concept":"K4-2-u6-C44","difficulty":4,"kind":"essay","stem":"게시판 장면을 역할놀이로 이어 가려고 해요. 까닭부터 살피는 나래와, 자기 잘못이면 먼저 인정하는 서진이의 다음 대사를 한 줄씩 쓰고 몸짓을 하나씩 붙이세요.","answer_guide":{"answer":"예: 서진 — (그림을 주워 들며) 「내가 압정을 하나만 꽂아서 그래. 다시 붙일게.」 / 나래 — (게시판 귀퉁이를 가리키며) 「여기 네 군데에 다 꽂으면 안 떨어질 거야.」","scoring_points":["서진이의 대사에 먼저 인정하는 성격이 드러나는가","나래의 대사에 까닭을 살피는 성격이 드러나는가","대사마다 몸짓을 붙였는가"]},"explanation":["서진이라면?","나래라면?","몸짓도 함께"],"asset":{"type":"speech","turns":[{"who":"나래","text":"(게시판 앞에서) 우리 모둠 그림이 바닥에 떨어져 있어."},{"who":"서진","text":"어제 내가 붙였는데, 압정을 하나만 꽂았나 봐."},{"who":"나래","text":"⋯⋯"},{"who":"서진","text":"( ? )"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_review_c#1','kor',4,2,'u6','','g4_2_kor_u6_review_c','unit_review','K4-2-u6-C5',1,'mc','auto','「빈 화분의 싹」을 읽고 이어질 내용을 상상하려고 해요. 가장 먼저 살펴볼 것은 무엇인가요?',ARRAY['K4-2-u6-X05','K4-2-u6-X06','K4-2-u6-X26']::text[],false,'{"seq":1,"concept":"K4-2-u6-C5","difficulty":1,"kind":"mc","stem":"「빈 화분의 싹」을 읽고 이어질 내용을 상상하려고 해요. 가장 먼저 살펴볼 것은 무엇인가요?","options":[{"t":"아무것도 심지 않았는데 싹이 났다는 앞의 일과 그 까닭","correct":true},{"t":"싹이 얼마나 크게 자라면 가장 놀라울지","mis":"K4-2-u6-X05"},{"t":"이야기를 몇 문장으로 늘릴 수 있을지","mis":"K4-2-u6-X06"},{"t":"선생님이 생각한 정답이 무엇일지","mis":"K4-2-u6-X26"}],"explanation":["앞에 무슨 일이 있었나요?","싹이 났어요.","왜 났을까부터 봐요."],"asset":{"type":"passage","lines":["예린이는 모르는 것이 생기면 책을 찾아보고 나서야 마음이 놓이는 아이다.","봄에 예린이는 흙만 담아 둔 빈 화분을 창가에 놓아두었다.","그런데 열흘쯤 지나자 그 화분에서 작은 싹 하나가 올라왔다.","예린이는 아무것도 심지 않았는데 싹이 난 까닭이 궁금했다."],"title":"빈 화분의 싹"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_review_c#2','kor',4,2,'u6','','g4_2_kor_u6_review_c','unit_review','K4-2-u6-C1',1,'mc','auto','「넘친 수돗가」에서 「고인 물이 넘쳐 바닥으로 흘러내렸다」의 원인은 무엇인가요?',ARRAY['K4-2-u6-X01','K4-2-u6-X19','K4-2-u6-X18']::text[],false,'{"seq":2,"concept":"K4-2-u6-C1","difficulty":1,"kind":"mc","stem":"「넘친 수돗가」에서 「고인 물이 넘쳐 바닥으로 흘러내렸다」의 원인은 무엇인가요?","options":[{"t":"물이 잘 빠지지 않아 개수대에 물이 고였다","correct":true},{"t":"지호가 미끄러질 뻔했다","mis":"K4-2-u6-X01"},{"t":"지호가 거름망을 들여다보았다","mis":"K4-2-u6-X19"},{"t":"과학실이 넓었다","mis":"K4-2-u6-X18"}],"explanation":["넘친 까닭은?","바로 앞의 일을 봐요.","물이 고였어요."],"asset":{"type":"passage","lines":["과학실 수돗가 거름망에 종이 조각이 잔뜩 끼어 있었어요.","물이 잘 빠지지 않아 개수대에 물이 고였어요.","고인 물이 넘쳐 바닥으로 흘러내렸어요.","그 바람에 지나가던 지호가 미끄러질 뻔했어요.","지호는 걸레를 가져오기 전에 거름망부터 들여다보았어요."],"title":"넘친 수돗가"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_review_c#3','kor',4,2,'u6','','g4_2_kor_u6_review_c','unit_review','K4-2-u6-C48',1,'mc','auto','(으)로써를 바르게 쓴 문장은 무엇인가요?',ARRAY['K4-2-u6-X42']::text[],false,'{"seq":3,"concept":"K4-2-u6-C48","difficulty":1,"kind":"mc","stem":"(으)로써를 바르게 쓴 문장은 무엇인가요?","options":[{"t":"우리는 쪽지로써 고마운 마음을 전했다.","correct":true},{"t":"나는 동생의 짝꿍으로써 함께 놀았다.","mis":"K4-2-u6-X42"},{"t":"언니는 반장으로써 회의를 열었다.","mis":"K4-2-u6-X42"},{"t":"형은 우리 집 맏이로써 일찍 일어났다.","mis":"K4-2-u6-X42"}],"explanation":["무엇을 써서 했나요?","쪽지는 수단이에요.","쪽지로써예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_review_c#4','kor',4,2,'u6','','g4_2_kor_u6_review_c','unit_review','K4-2-u6-C49',1,'mc','auto','「머뭇거리다」를 알맞게 쓴 문장은 무엇인가요?',ARRAY['K4-2-u6-X43']::text[],false,'{"seq":4,"concept":"K4-2-u6-C49","difficulty":1,"kind":"mc","stem":"「머뭇거리다」를 알맞게 쓴 문장은 무엇인가요?","options":[{"t":"처음 온 친구는 교실 문 앞에서 한참 머뭇거렸다.","correct":true},{"t":"나는 개미가 가는 길을 머뭇거렸다.","mis":"K4-2-u6-X43"},{"t":"동생이 갑자기 머뭇거리게 웃었다.","mis":"K4-2-u6-X43"},{"t":"하늘이 머뭇거리게 맑았다.","mis":"K4-2-u6-X43"}],"explanation":["뜻을 넣어 읽어 봐요.","망설이는 모습이에요.","문 앞에서 망설였어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_review_c#5','kor',4,2,'u6','','g4_2_kor_u6_review_c','unit_review','K4-2-u6-C52',1,'mc','auto','겹받침을 바르게 살려 쓴 낱말은 무엇인가요?',ARRAY['K4-2-u6-X46']::text[],false,'{"seq":5,"concept":"K4-2-u6-C52","difficulty":1,"kind":"mc","stem":"겹받침을 바르게 살려 쓴 낱말은 무엇인가요?","options":[{"t":"많다","correct":true},{"t":"만타","mis":"K4-2-u6-X46"},{"t":"맜다","mis":"K4-2-u6-X46"},{"t":"맣다","mis":"K4-2-u6-X46"}],"explanation":["소리는 [만타]예요.","쓸 때는 ㄶ 그대로","많다예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_review_c#6','kor',4,2,'u6','','g4_2_kor_u6_review_c','unit_review','K4-2-u6-C8',1,'mc','auto','「넘친 수돗가」에서 이야기에 나와 있는 일은 무엇인가요?',ARRAY['K4-2-u6-X08']::text[],false,'{"seq":6,"concept":"K4-2-u6-C8","difficulty":1,"kind":"mc","stem":"「넘친 수돗가」에서 이야기에 나와 있는 일은 무엇인가요?","options":[{"t":"지나가던 지호가 미끄러질 뻔했다","correct":true},{"t":"지호가 넘어져 다쳤다","mis":"K4-2-u6-X08"},{"t":"누가 일부러 종이를 거름망에 넣었다","mis":"K4-2-u6-X08"},{"t":"선생님이 수돗가를 고치셨다","mis":"K4-2-u6-X08"}],"explanation":["「뻔했다」예요.","나와 있는 것만 골라요.","미끄러질 뻔했어요."],"asset":{"type":"passage","lines":["과학실 수돗가 거름망에 종이 조각이 잔뜩 끼어 있었어요.","물이 잘 빠지지 않아 개수대에 물이 고였어요.","고인 물이 넘쳐 바닥으로 흘러내렸어요.","그 바람에 지나가던 지호가 미끄러질 뻔했어요.","지호는 걸레를 가져오기 전에 거름망부터 들여다보았어요."],"title":"넘친 수돗가"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_review_c#7','kor',4,2,'u6','','g4_2_kor_u6_review_c','unit_review','K4-2-u6-C26',1,'mc','auto','「빈 화분의 싹」에서 예린이는 어떤 아이로 나와 있나요?',ARRAY['K4-2-u6-X23','K4-2-u6-X20']::text[],false,'{"seq":7,"concept":"K4-2-u6-C26","difficulty":1,"kind":"mc","stem":"「빈 화분의 싹」에서 예린이는 어떤 아이로 나와 있나요?","options":[{"t":"모르는 것이 생기면 책을 찾아보고 나서야 마음이 놓이는 아이","correct":true},{"t":"궁금한 것이 있어도 그냥 넘기는 아이","mis":"K4-2-u6-X23"},{"t":"화분을 싫어하는 아이","mis":"K4-2-u6-X20"},{"t":"말을 하지 않으니 알 수 없는 아이","mis":"K4-2-u6-X20"}],"explanation":["앞 이야기 첫 문장을 봐요.","책을 찾아봐요.","그래야 마음이 놓여요."],"asset":{"type":"passage","lines":["예린이는 모르는 것이 생기면 책을 찾아보고 나서야 마음이 놓이는 아이다.","봄에 예린이는 흙만 담아 둔 빈 화분을 창가에 놓아두었다.","그런데 열흘쯤 지나자 그 화분에서 작은 싹 하나가 올라왔다.","예린이는 아무것도 심지 않았는데 싹이 난 까닭이 궁금했다."],"title":"빈 화분의 싹"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_review_c#8','kor',4,2,'u6','','g4_2_kor_u6_review_c','unit_review','K4-2-u6-C42',1,'mc','auto','「복도 불이 모두 꺼져 있었습니다.」 다음에 이어 말하기로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u6-X35','K4-2-u6-X36','K4-2-u6-X37']::text[],false,'{"seq":8,"concept":"K4-2-u6-C42","difficulty":1,"kind":"mc","stem":"「복도 불이 모두 꺼져 있었습니다.」 다음에 이어 말하기로 알맞은 것은 무엇인가요?","options":[{"t":"「그래서 나는 벽을 더듬어 스위치를 찾았습니다.」","correct":true},{"t":"「나는 수학 시험을 잘 보았습니다.」","mis":"K4-2-u6-X35"},{"t":"「갑자기 복도에 무지개가 떴습니다.」","mis":"K4-2-u6-X36"},{"t":"「그런데 복도 불은 아까부터 환하게 켜져 있었습니다.」","mis":"K4-2-u6-X37"}],"explanation":["불이 꺼져서 무엇을 하게 될까요?","앞이 까닭이 돼요.","스위치를 찾았어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_review_c#9','kor',4,2,'u6','','g4_2_kor_u6_review_c','unit_review','K4-2-u6-C14',2,'mc','auto','「늦게 가는 시계」에서 앞 일의 결과이면서 뒤 일의 원인인 것은 무엇인가요?',ARRAY['K4-2-u6-X02','K4-2-u6-X18']::text[],false,'{"seq":9,"concept":"K4-2-u6-C14","difficulty":2,"kind":"mc","stem":"「늦게 가는 시계」에서 앞 일의 결과이면서 뒤 일의 원인인 것은 무엇인가요?","options":[{"t":"시계가 늦게 갔다","correct":true},{"t":"건전지가 헐겁게 빠져 있었다","mis":"K4-2-u6-X02"},{"t":"급식실에 늘 꼴찌로 도착했다","mis":"K4-2-u6-X02"},{"t":"아이들이 「오래돼서 그래.」 하고 말했다","mis":"K4-2-u6-X18"}],"explanation":["가운데에 있는 일이에요.","건전지 → ? → 급식실","시계가 늦게 갔어요."],"asset":{"type":"passage","lines":["우리 반 벽시계는 언제부터인가 조금씩 늦게 갔어요.","그래서 시계를 보고 움직인 날은 급식실에 늘 꼴찌로 도착했지요.","\"시계가 오래돼서 그래.\" 아이들은 그렇게만 말했어요.","다은이는 선생님께 시계를 내려 달라고 부탁해 뒤쪽 건전지 칸을 열어 보았어요.","건전지 한 개가 헐겁게 빠져 있었어요.","다은이가 건전지를 꾹 눌러 끼우자 초바늘이 다시 힘차게 돌았어요."],"title":"늦게 가는 시계"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_review_c#10','kor',4,2,'u6','','g4_2_kor_u6_review_c','unit_review','K4-2-u6-C19',2,'mc','auto','「늦게 가는 시계」에서 아이들이 늘 급식실에 늦은 까닭을 바르게 말한 것은 무엇인가요?',ARRAY['K4-2-u6-X16','K4-2-u6-X18','K4-2-u6-X15']::text[],false,'{"seq":10,"concept":"K4-2-u6-C19","difficulty":2,"kind":"mc","stem":"「늦게 가는 시계」에서 아이들이 늘 급식실에 늦은 까닭을 바르게 말한 것은 무엇인가요?","options":[{"t":"건전지가 헐거워 시계가 늦게 갔고, 아이들이 까닭을 찾지 않고 넘겼기 때문에","correct":true},{"t":"시계가 오래되었기 때문에, 하나뿐이다","mis":"K4-2-u6-X16"},{"t":"급식실이 멀기 때문에","mis":"K4-2-u6-X18"},{"t":"까닭은 언제나 하나만 찾으면 된다","mis":"K4-2-u6-X15"}],"explanation":["「오래돼서」는 겉말이에요.","넘긴 일도 까닭이에요.","까닭이 여럿이에요."],"asset":{"type":"passage","lines":["우리 반 벽시계는 언제부터인가 조금씩 늦게 갔어요.","그래서 시계를 보고 움직인 날은 급식실에 늘 꼴찌로 도착했지요.","\"시계가 오래돼서 그래.\" 아이들은 그렇게만 말했어요.","다은이는 선생님께 시계를 내려 달라고 부탁해 뒤쪽 건전지 칸을 열어 보았어요.","건전지 한 개가 헐겁게 빠져 있었어요.","다은이가 건전지를 꾹 눌러 끼우자 초바늘이 다시 힘차게 돌았어요."],"title":"늦게 가는 시계"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_review_c#11','kor',4,2,'u6','','g4_2_kor_u6_review_c','unit_review','K4-2-u6-C10',2,'mc','auto','「빈 화분의 싹」에서 「새가 씨를 떨어뜨렸을 것」이라고 예상했는데, 뒤에 흙 속에 씨가 섞여 있었던 것으로 나왔어요. 알맞게 견주어 말한 것은 무엇인가요?',ARRAY['K4-2-u6-X11','K4-2-u6-X10']::text[],false,'{"seq":11,"concept":"K4-2-u6-C10","difficulty":2,"kind":"mc","stem":"「빈 화분의 싹」에서 「새가 씨를 떨어뜨렸을 것」이라고 예상했는데, 뒤에 흙 속에 씨가 섞여 있었던 것으로 나왔어요. 알맞게 견주어 말한 것은 무엇인가요?","options":[{"t":"「창가라는 것을 까닭으로 새를 떠올렸는데, 흙에 씨가 섞여 있었던 것이어서 그 부분이 달랐다.」","correct":true},{"t":"「같지 않아서 속상했다.」","mis":"K4-2-u6-X11"},{"t":"「싹이 났다는 것은 같아서 좋았다.」","mis":"K4-2-u6-X11"},{"t":"「예상은 하나만 맞으니 다음엔 하지 않겠다.」","mis":"K4-2-u6-X10"}],"explanation":["무엇을 보고 예상했나요?","어디가 달랐나요?","까닭으로 견주어요."],"asset":{"type":"passage","lines":["예린이는 모르는 것이 생기면 책을 찾아보고 나서야 마음이 놓이는 아이다.","봄에 예린이는 흙만 담아 둔 빈 화분을 창가에 놓아두었다.","그런데 열흘쯤 지나자 그 화분에서 작은 싹 하나가 올라왔다.","예린이는 아무것도 심지 않았는데 싹이 난 까닭이 궁금했다."],"title":"빈 화분의 싹"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_review_c#12','kor',4,2,'u6','','g4_2_kor_u6_review_c','unit_review','K4-2-u6-C12',2,'mc','auto','친구와 다른 예상을 했을 때 알맞은 생각은 무엇인가요?',ARRAY['K4-2-u6-X26','K4-2-u6-X25','K4-2-u6-X29']::text[],false,'{"seq":12,"concept":"K4-2-u6-C12","difficulty":2,"kind":"mc","stem":"친구와 다른 예상을 했을 때 알맞은 생각은 무엇인가요?","options":[{"t":"달라도 되지만, 그렇게 생각한 까닭을 장면 안에서 찾을 수 있어야 한다","correct":true},{"t":"친구와 다르면 내 예상이 틀린 것이다","mis":"K4-2-u6-X26"},{"t":"까닭을 댈 수 없어도 예상은 다 맞다","mis":"K4-2-u6-X25"},{"t":"가장 신기한 예상이 가장 좋은 예상이다","mis":"K4-2-u6-X29"}],"explanation":["예상은 달라도 돼요.","까닭은 장면 안에","아무 말은 예상이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_review_c#13','kor',4,2,'u6','','g4_2_kor_u6_review_c','unit_review','K4-2-u6-C28',2,'mc','auto','「넘친 수돗가」의 흐름에 가장 알맞은 다음 일은 무엇인가요?',ARRAY['K4-2-u6-X24','K4-2-u6-X36','K4-2-u6-X37']::text[],false,'{"seq":13,"concept":"K4-2-u6-C28","difficulty":2,"kind":"mc","stem":"「넘친 수돗가」의 흐름에 가장 알맞은 다음 일은 무엇인가요?","options":[{"t":"지호가 거름망의 종이 조각을 걷어 내자 물이 빠지기 시작했다","correct":true},{"t":"지호가 운동장에 축구를 하러 나갔다","mis":"K4-2-u6-X24"},{"t":"갑자기 개수대에서 물고기가 튀어 올랐다","mis":"K4-2-u6-X36"},{"t":"물이 처음부터 넘치지 않았던 것이 되었다","mis":"K4-2-u6-X37"}],"explanation":["지호가 무엇을 보고 있나요?","거름망이에요.","까닭을 없애요."],"asset":{"type":"passage","lines":["과학실 수돗가 거름망에 종이 조각이 잔뜩 끼어 있었어요.","물이 잘 빠지지 않아 개수대에 물이 고였어요.","고인 물이 넘쳐 바닥으로 흘러내렸어요.","그 바람에 지나가던 지호가 미끄러질 뻔했어요.","지호는 걸레를 가져오기 전에 거름망부터 들여다보았어요."],"title":"넘친 수돗가"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_review_c#14','kor',4,2,'u6','','g4_2_kor_u6_review_c','unit_review','K4-2-u6-C44',2,'mc','auto','역할놀이에서 인물의 대사를 지을 때 가장 먼저 살필 것은 무엇인가요?',ARRAY['K4-2-u6-X40','K4-2-u6-X39','K4-2-u6-X35']::text[],false,'{"seq":14,"concept":"K4-2-u6-C44","difficulty":2,"kind":"mc","stem":"역할놀이에서 인물의 대사를 지을 때 가장 먼저 살필 것은 무엇인가요?","options":[{"t":"그 인물의 성격","correct":true},{"t":"대사의 길이","mis":"K4-2-u6-X40"},{"t":"친구들이 웃을지","mis":"K4-2-u6-X39"},{"t":"앞 이야기와 상관없는 재미있는 말","mis":"K4-2-u6-X35"}],"explanation":["누가 하는 말인가요?","그 사람이라면?","성격을 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_review_c#15','kor',4,2,'u6','','g4_2_kor_u6_review_c','unit_review','K4-2-u6-C22',2,'mc','auto','「넘친 수돗가」를 들으며 메모한 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-2-u6-X14','K4-2-u6-X15']::text[],false,'{"seq":15,"concept":"K4-2-u6-C22","difficulty":2,"kind":"mc","stem":"「넘친 수돗가」를 들으며 메모한 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"거름망 종이 → 물 고임 → 넘침 → 지호 미끄러질 뻔","correct":true},{"t":"과학실 수돗가 거름망에 종이 조각이 잔뜩 끼어 있었어요(한 글자도 빼지 않고)","mis":"K4-2-u6-X14"},{"t":"지호","mis":"K4-2-u6-X15"},{"t":"물이 많았다, 하나만","mis":"K4-2-u6-X15"}],"explanation":["짧게 · 화살표","일과 까닭을 함께","그다음까지"],"asset":{"type":"passage","lines":["과학실 수돗가 거름망에 종이 조각이 잔뜩 끼어 있었어요.","물이 잘 빠지지 않아 개수대에 물이 고였어요.","고인 물이 넘쳐 바닥으로 흘러내렸어요.","그 바람에 지나가던 지호가 미끄러질 뻔했어요.","지호는 걸레를 가져오기 전에 거름망부터 들여다보았어요."],"title":"넘친 수돗가"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_review_c#16','kor',4,2,'u6','','g4_2_kor_u6_review_c','unit_review','K4-2-u6-C16',2,'mc','auto','「두레박 줄」의 범수와 「늦게 가는 시계」의 다은이가 한 일의 같은 점은 무엇인가요?',ARRAY['K4-2-u6-X48','K4-2-u6-X17','K4-2-u6-X23']::text[],false,'{"seq":16,"concept":"K4-2-u6-C16","difficulty":2,"kind":"mc","stem":"「두레박 줄」의 범수와 「늦게 가는 시계」의 다은이가 한 일의 같은 점은 무엇인가요?","options":[{"t":"겉으로 드러난 일만 덮지 않고 까닭을 찾아 없앴다","correct":true},{"t":"둘 다 새 물건으로 바꾸었다","mis":"K4-2-u6-X48"},{"t":"둘 다 꾸며서 보기 좋게 했다","mis":"K4-2-u6-X17"},{"t":"둘 다 어른에게 맡기고 잊었다","mis":"K4-2-u6-X23"}],"explanation":["범수는 돌을 감쌌어요.","다은이는 건전지를 끼웠어요.","까닭을 없앴어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_review_c#17','kor',4,2,'u6','','g4_2_kor_u6_review_c','unit_review','K4-2-u6-C53',3,'mc','auto','두 친구가 다투고 있어요. 한 친구는 「상상은 마음대로니까 아무렇게나 써도 돼.」, 다른 친구는 「앞과 이어지려면 뻔한 이야기밖에 못 써.」라고 해요. 알맞은 생각은 무엇인가요?',ARRAY['K4-2-u6-X25','K4-2-u6-X49','K4-2-u6-X26']::text[],false,'{"seq":17,"concept":"K4-2-u6-C53","difficulty":3,"kind":"mc","stem":"두 친구가 다투고 있어요. 한 친구는 「상상은 마음대로니까 아무렇게나 써도 돼.」, 다른 친구는 「앞과 이어지려면 뻔한 이야기밖에 못 써.」라고 해요. 알맞은 생각은 무엇인가요?","options":[{"t":"둘 다 치우쳤다 — 까닭을 달고 가면 새로우면서도 이어질 수 있다","correct":true},{"t":"첫째 친구가 맞다 — 상상에는 기준이 없다","mis":"K4-2-u6-X25"},{"t":"둘째 친구가 맞다 — 이어지면 새로울 수 없다","mis":"K4-2-u6-X49"},{"t":"둘 다 맞다 — 정해진 답 하나를 찾으면 된다","mis":"K4-2-u6-X26"}],"explanation":["한쪽으로 치우쳤어요.","둘 다 오답이에요.","함께 갈 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_review_c#18','kor',4,2,'u6','','g4_2_kor_u6_review_c','unit_review','K4-2-u6-C39',3,'mc','auto','「넘친 수돗가」의 뒷이야기로 가장 자연스럽게 이어지는 것은 무엇인가요?',ARRAY['K4-2-u6-X29','K4-2-u6-X32','K4-2-u6-X36']::text[],false,'{"seq":18,"concept":"K4-2-u6-C39","difficulty":3,"kind":"mc","stem":"「넘친 수돗가」의 뒷이야기로 가장 자연스럽게 이어지는 것은 무엇인가요?","options":[{"t":"지호가 거름망을 비운 뒤 「종이는 휴지통에」라는 쪽지를 수돗가에 붙였다","correct":true},{"t":"수돗가에서 물이 솟구쳐 분수 쇼가 펼쳐졌다","mis":"K4-2-u6-X29"},{"t":"지호는 물에는 관심 없이 그냥 교실로 돌아갔다","mis":"K4-2-u6-X32"},{"t":"갑자기 과학실이 바다로 변했다","mis":"K4-2-u6-X36"}],"explanation":["지호는 까닭부터 살피는 아이예요.","거름망이 까닭이었어요.","그 일과 이어져요."],"asset":{"type":"passage","lines":["과학실 수돗가 거름망에 종이 조각이 잔뜩 끼어 있었어요.","물이 잘 빠지지 않아 개수대에 물이 고였어요.","고인 물이 넘쳐 바닥으로 흘러내렸어요.","그 바람에 지나가던 지호가 미끄러질 뻔했어요.","지호는 걸레를 가져오기 전에 거름망부터 들여다보았어요."],"title":"넘친 수돗가"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_review_c#19','kor',4,2,'u6','','g4_2_kor_u6_review_c','unit_review','K4-2-u6-C31',3,'mc','auto','친구가 쓴 뒷이야기가 알맞지 않다고 말할 때 살펴야 할 것은 무엇인가요?',ARRAY['K4-2-u6-X27','K4-2-u6-X28','K4-2-u6-X29']::text[],false,'{"seq":19,"concept":"K4-2-u6-C31","difficulty":3,"kind":"mc","stem":"친구가 쓴 뒷이야기가 알맞지 않다고 말할 때 살펴야 할 것은 무엇인가요?","options":[{"t":"앞에 나온 인물의 성격·행동과 이어지는지","correct":true},{"t":"얼마나 평범한지","mis":"K4-2-u6-X27"},{"t":"글자 수가 얼마나 되는지","mis":"K4-2-u6-X28"},{"t":"얼마나 놀라운지","mis":"K4-2-u6-X29"}],"explanation":["평범함은 기준이 아니에요.","길이도 아니에요.","이어지는지를 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_review_c#20','kor',4,2,'u6','','g4_2_kor_u6_review_c','unit_review','K4-2-u6-C40',3,'mc','auto','세 친구의 「돌아온 우산」 뒷이야기 ㉰를 고치려고 해요. 가장 알맞게 고친 것은 무엇인가요?',ARRAY['K4-2-u6-X32','K4-2-u6-X36']::text[],false,'{"seq":20,"concept":"K4-2-u6-C40","difficulty":3,"kind":"mc","stem":"세 친구의 「돌아온 우산」 뒷이야기 ㉰를 고치려고 해요. 가장 알맞게 고친 것은 무엇인가요?","options":[{"t":"수업 종이 울려 동규이는 「쉬는 시간에 꼭 다시 봐야지.」 하고 우산을 교실에 넣어 두었다.","correct":true},{"t":"동규이는 매듭에 아무 관심이 없어서 우산을 교실에 넣어 두었다.","mis":"K4-2-u6-X32"},{"t":"동규이는 갑자기 다른 아이가 되어 우산을 교실에 넣어 두었다.","mis":"K4-2-u6-X32"},{"t":"우산이 스스로 교실로 걸어 들어갔다.","mis":"K4-2-u6-X36"}],"explanation":["관심 없는 동규이는 앞과 달라요.","까닭을 넣어요.","종이 울렸어요."],"asset":{"type":"passage","lines":["㉮ 효주가 \"우리 할머니가 자루를 묶을 때 이렇게 매\" 하고 말했고, 둘은 할머니를 찾아갔다.","㉯ 그 순간 매듭이 스스로 풀리더니 빛이 나며 우산이 하늘로 날아올랐다.","㉰ 동규이는 매듭을 보고도 아무 관심이 없어 우산을 그냥 교실에 넣어 두었다."],"title":"세 친구가 상상한 뒷이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_review_c#21','kor',4,2,'u6','','g4_2_kor_u6_review_c','unit_review','K4-2-u6-C46',3,'mc','auto','역할놀이에서 「너무 장난스럽지 않게」 해야 하는 까닭으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u6-X39','K4-2-u6-X40','K4-2-u6-X26']::text[],false,'{"seq":21,"concept":"K4-2-u6-C46","difficulty":3,"kind":"mc","stem":"역할놀이에서 「너무 장난스럽지 않게」 해야 하는 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"웃기려다 인물의 성격과 앞 이야기에서 벗어나 이야기가 끊기기 쉬워서","correct":true},{"t":"역할놀이는 재미가 없어야 하기 때문에","mis":"K4-2-u6-X39"},{"t":"대사가 짧아지기 때문에","mis":"K4-2-u6-X40"},{"t":"정해진 대본이 하나 있기 때문에","mis":"K4-2-u6-X26"}],"explanation":["재미는 좋아요.","그런데 끊기면 안 돼요.","이어지는 것이 먼저예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_review_c#22','kor',4,2,'u6','','g4_2_kor_u6_review_c','unit_review','K4-2-u6-C36',3,'mc','auto','「넘친 수돗가」에 지나가던 다른 친구 「보람」이 등장해요. 보람이는 일이 생기면 먼저 어른께 알리는 아이예요. 보람이를 따라간 이야기로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u6-X31','K4-2-u6-X23','K4-2-u6-X25']::text[],false,'{"seq":22,"concept":"K4-2-u6-C36","difficulty":3,"kind":"mc","stem":"「넘친 수돗가」에 지나가던 다른 친구 「보람」이 등장해요. 보람이는 일이 생기면 먼저 어른께 알리는 아이예요. 보람이를 따라간 이야기로 알맞은 것은 무엇인가요?","options":[{"t":"보람이는 넘친 물을 보자마자 과학 선생님께 달려가 알렸다","correct":true},{"t":"보람이도 지호와 똑같이 거름망부터 들여다보았다","mis":"K4-2-u6-X31"},{"t":"보람이는 물에 관심 없이 지나갔다","mis":"K4-2-u6-X23"},{"t":"보람이가 넘친 물을 마법으로 없앴다","mis":"K4-2-u6-X25"}],"explanation":["보람이는 어떤 아이인가요?","어른께 먼저 알려요.","사람마다 달라요."],"asset":{"type":"passage","lines":["과학실 수돗가 거름망에 종이 조각이 잔뜩 끼어 있었어요.","물이 잘 빠지지 않아 개수대에 물이 고였어요.","고인 물이 넘쳐 바닥으로 흘러내렸어요.","그 바람에 지나가던 지호가 미끄러질 뻔했어요.","지호는 걸레를 가져오기 전에 거름망부터 들여다보았어요."],"title":"넘친 수돗가"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_review_c#23','kor',4,2,'u6','','g4_2_kor_u6_review_c','unit_review','K4-2-u6-C6',4,'essay','teacher','이 단원에서 배운 두 가지(원인과 결과를 생각하며 보고 듣기 · 이어질 내용 상상해 쓰기)가 어떻게 이어지는지 쓰고, 다음에 책을 읽다가 해 볼 일 하나를 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K4-2-u6-C6","difficulty":4,"kind":"essay","stem":"이 단원에서 배운 두 가지(원인과 결과를 생각하며 보고 듣기 · 이어질 내용 상상해 쓰기)가 어떻게 이어지는지 쓰고, 다음에 책을 읽다가 해 볼 일 하나를 쓰세요.","answer_guide":{"answer":"예: 원인과 결과를 찾을 줄 알아야 앞의 일이 까닭이 되는 뒷이야기를 상상할 수 있다. 다음에 책을 읽다가 다음 장이 궁금해지면 바로 넘기지 말고 한 문장으로 상상해 적은 뒤, 넘겨서 견주어 보겠다.","scoring_points":["두 가지가 이어지는 까닭을 썼는가","원인과 결과가 상상의 바탕이라는 생각이 드러나는가","책을 읽다가 해 볼 일을 썼는가"]},"explanation":["둘 다 까닭을 따져요.","찾아야 이어 써요.","해 볼 일 하나"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_review_c#24','kor',4,2,'u6','','g4_2_kor_u6_review_c','unit_review','K4-2-u6-C41',4,'essay','teacher','친구가 「돌아온 우산」 뒷이야기에 「동규이는 갑자기 매듭 묶는 법을 모두 알게 되었다.」라고 썼어요. 이 문장이 왜 끊기는지 쓰고, 까닭을 먼저 넣어 자연스럽게 고쳐 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K4-2-u6-C41","difficulty":4,"kind":"essay","stem":"친구가 「돌아온 우산」 뒷이야기에 「동규이는 갑자기 매듭 묶는 법을 모두 알게 되었다.」라고 썼어요. 이 문장이 왜 끊기는지 쓰고, 까닭을 먼저 넣어 자연스럽게 고쳐 쓰세요.","answer_guide":{"answer":"예: 동규이가 매듭 묶는 법을 알게 된 까닭이 앞에 없어서 끊긴다. 고치면 — 「동규이는 할머니께 매듭 묶는 법을 여쭈어 밤새 끈을 꼬아 보았다. 다음 날 아침, 동규이는 꽃 모양 매듭을 세 번 꼬아 맬 수 있게 되었다.」","scoring_points":["끊기는 까닭(앞에 까닭 없음)을 썼는가","까닭이 되는 일을 먼저 넣었는가","고친 이야기가 앞과 이어지는가"]},"explanation":["「갑자기」는 까닭이 아니에요.","까닭을 먼저 넣어요.","그러면 이어져요."],"asset":{"type":"passage","lines":["[앞 이야기] 동규이는 궁금한 것이 생기면 확인해야 잠이 오는 아이다.","지난주 비 오는 날, 동규이는 학원 앞에 두고 온 파란 우산을 잃어버렸다.","손잡이에 이름표가 없었다. 짝 효주는 \"그냥 새로 사\" 하고 말았다.","사흘 뒤 아침, 교문 앞 은행나무 가지에 그 파란 우산이 걸려 있었다.","손잡이에는 처음 보는 빨간 실 매듭이 꽃 모양으로 단단히 묶여 있었다.","동규이는 어리둥절해서 우산을 든 채 교문 앞에서 머뭇거렸다.","그때 효주가 다가와 매듭을 보더니 눈을 크게 떴다. \"어? 이 매듭⋯⋯.\""],"title":"돌아온 우산"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_review_c#25','kor',4,2,'u6','','g4_2_kor_u6_review_c','unit_review','K4-2-u6-C48',4,'essay','teacher','「(으)로서」와 「(으)로써」를 하나씩 넣어 「돌아온 우산」 이야기에 어울리는 문장을 지어 쓰고, 각각 그 표현을 고른 까닭을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K4-2-u6-C48","difficulty":4,"kind":"essay","stem":"「(으)로서」와 「(으)로써」를 하나씩 넣어 「돌아온 우산」 이야기에 어울리는 문장을 지어 쓰고, 각각 그 표현을 고른 까닭을 쓰세요.","answer_guide":{"answer":"예: 효주는 동규이의 짝으로서 매듭의 임자를 함께 찾아 주었다 — 「짝」이라는 자격이라서 (으)로서. 동규이는 빨간 실 매듭으로써 우산을 주운 사람을 찾을 수 있었다 — 매듭을 써서 찾았으니 수단이라 (으)로써.","scoring_points":["(으)로서를 자격·신분에 썼는가","(으)로써를 재료·수단에 썼는가","이야기에 어울리는 문장과 고른 까닭을 썼는가"]},"explanation":["누구인가? → (으)로서","무엇을 써서? → (으)로써","까닭도 써요."],"asset":{"type":"passage","lines":["[앞 이야기] 동규이는 궁금한 것이 생기면 확인해야 잠이 오는 아이다.","지난주 비 오는 날, 동규이는 학원 앞에 두고 온 파란 우산을 잃어버렸다.","손잡이에 이름표가 없었다. 짝 효주는 \"그냥 새로 사\" 하고 말았다.","사흘 뒤 아침, 교문 앞 은행나무 가지에 그 파란 우산이 걸려 있었다.","손잡이에는 처음 보는 빨간 실 매듭이 꽃 모양으로 단단히 묶여 있었다.","동규이는 어리둥절해서 우산을 든 채 교문 앞에서 머뭇거렸다.","그때 효주가 다가와 매듭을 보더니 눈을 크게 떴다. \"어? 이 매듭⋯⋯.\""],"title":"돌아온 우산"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_review_d#1','kor',4,2,'u6','','g4_2_kor_u6_review_d','unit_review','K4-2-u6-C5',1,'mc','auto','이야기를 읽다가 다음 장이 궁금해졌어요. 다음 내용을 상상하기 전에 먼저 해야 할 것은 무엇인가요?',ARRAY['K4-2-u6-X05','K4-2-u6-X06','K4-2-u6-X07']::text[],false,'{"seq":1,"concept":"K4-2-u6-C5","difficulty":1,"kind":"mc","stem":"이야기를 읽다가 다음 장이 궁금해졌어요. 다음 내용을 상상하기 전에 먼저 해야 할 것은 무엇인가요?","options":[{"t":"앞에서 일어난 일과 그 까닭을 되짚어 본다","correct":true},{"t":"가장 깜짝 놀랄 결말을 정한다","mis":"K4-2-u6-X05"},{"t":"다음 장을 길게 써 볼 계획을 세운다","mis":"K4-2-u6-X06"},{"t":"바로 넘겨서 답을 확인한다","mis":"K4-2-u6-X07"}],"explanation":["넘기기 전에 한 번","앞의 일을 되짚어요.","그다음 상상해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_review_d#2','kor',4,2,'u6','','g4_2_kor_u6_review_d','unit_review','K4-2-u6-C1',1,'mc','auto','「건전지가 헐겁게 빠져 있어서 시계가 늦게 갔다.」에서 결과는 무엇인가요?',ARRAY['K4-2-u6-X01','K4-2-u6-X04']::text[],false,'{"seq":2,"concept":"K4-2-u6-C1","difficulty":1,"kind":"mc","stem":"「건전지가 헐겁게 빠져 있어서 시계가 늦게 갔다.」에서 결과는 무엇인가요?","options":[{"t":"시계가 늦게 갔다","correct":true},{"t":"건전지가 헐겁게 빠져 있었다","mis":"K4-2-u6-X01"},{"t":"건전지","mis":"K4-2-u6-X04"},{"t":"늦게","mis":"K4-2-u6-X04"}],"explanation":["그래서 어떻게 되었나요?","그것이 결과예요.","시계가 늦게 갔어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_review_d#3','kor',4,2,'u6','','g4_2_kor_u6_review_d','unit_review','K4-2-u6-C47',1,'mc','auto','(으)로서를 바르게 쓴 문장은 무엇인가요?',ARRAY['K4-2-u6-X41']::text[],false,'{"seq":3,"concept":"K4-2-u6-C47","difficulty":1,"kind":"mc","stem":"(으)로서를 바르게 쓴 문장은 무엇인가요?","options":[{"t":"나는 모둠의 기록 담당으로서 회의 내용을 적었다.","correct":true},{"t":"우리는 노래로서 친구를 축하했다.","mis":"K4-2-u6-X41"},{"t":"밀가루로서 반죽을 만들었다.","mis":"K4-2-u6-X41"},{"t":"붓으로서 그림을 그렸다.","mis":"K4-2-u6-X41"}],"explanation":["누구인가요?","기록 담당은 자격이에요.","담당으로서예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_review_d#4','kor',4,2,'u6','','g4_2_kor_u6_review_d','unit_review','K4-2-u6-C49',1,'mc','auto','「눈여겨보다」를 알맞게 쓴 문장은 무엇인가요?',ARRAY['K4-2-u6-X43','K4-2-u6-X30']::text[],false,'{"seq":4,"concept":"K4-2-u6-C49","difficulty":1,"kind":"mc","stem":"「눈여겨보다」를 알맞게 쓴 문장은 무엇인가요?","options":[{"t":"나는 선생님께서 매듭을 묶으시는 손을 눈여겨보았다.","correct":true},{"t":"나는 너무 졸려서 눈여겨보았다.","mis":"K4-2-u6-X43"},{"t":"동생은 무슨 일인지 몰라 눈여겨보았다.","mis":"K4-2-u6-X30"},{"t":"나는 대답을 못 하고 눈여겨보았다.","mis":"K4-2-u6-X43"}],"explanation":["자세히 보는 일이에요.","무엇을 보았나요?","손을 눈여겨보았어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_review_d#5','kor',4,2,'u6','','g4_2_kor_u6_review_d','unit_review','K4-2-u6-C51',1,'mc','auto','「끊다」를 바르게 소리 낸 것은 무엇인가요?',ARRAY['K4-2-u6-X45','K4-2-u6-X44']::text[],false,'{"seq":5,"concept":"K4-2-u6-C51","difficulty":1,"kind":"mc","stem":"「끊다」를 바르게 소리 낸 것은 무엇인가요?","options":[{"t":"[끈타]","correct":true},{"t":"[끈다]","mis":"K4-2-u6-X45"},{"t":"[끄나]","mis":"K4-2-u6-X45"},{"t":"[끌타]","mis":"K4-2-u6-X44"}],"explanation":["ㄶ이에요.","ㅎ + ㄷ → [ㅌ]","[끈타]예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_review_d#6','kor',4,2,'u6','','g4_2_kor_u6_review_d','unit_review','K4-2-u6-C34',1,'mc','auto','「빈 새집」에서 일어난 일로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u6-X08']::text[],false,'{"seq":6,"concept":"K4-2-u6-C34","difficulty":1,"kind":"mc","stem":"「빈 새집」에서 일어난 일로 알맞은 것은 무엇인가요?","options":[{"t":"열흘이 지나도 새집에 드나드는 새가 없었다","correct":true},{"t":"새가 새집에 알을 낳았다","mis":"K4-2-u6-X08"},{"t":"하람이가 새집을 떼어 버렸다","mis":"K4-2-u6-X08"},{"t":"그네가 부서졌다","mis":"K4-2-u6-X08"}],"explanation":["이야기에 나온 일이에요.","새가 오지 않았어요.","열흘이 지났어요."],"asset":{"type":"passage","lines":["하람이는 한번 마음먹은 일은 날마다 조금씩이라도 해내는 아이다.","봄에 하람이는 손수 만든 새집을 학교 뒤뜰 나무에 달았다.","그런데 열흘이 지나도 새집에 드나드는 새가 한 마리도 없었다.","새집 바로 아래에는 그네가 있어 쉬는 시간마다 아이들이 북적였다.","하람이는 새집과 그네를 번갈아 바라보았다."],"title":"빈 새집"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_review_d#7','kor',4,2,'u6','','g4_2_kor_u6_review_d','unit_review','K4-2-u6-C26',1,'mc','auto','「연을 놓친 날」에서 「겨울 방학 내내 연 하나를 만들었다」는 행동으로 짐작되는 성격은 무엇인가요?',ARRAY['K4-2-u6-X23','K4-2-u6-X20']::text[],false,'{"seq":7,"concept":"K4-2-u6-C26","difficulty":1,"kind":"mc","stem":"「연을 놓친 날」에서 「겨울 방학 내내 연 하나를 만들었다」는 행동으로 짐작되는 성격은 무엇인가요?","options":[{"t":"한번 시작하면 끝까지 한다","correct":true},{"t":"금방 다른 일로 옮겨 간다","mis":"K4-2-u6-X23"},{"t":"남이 시키는 일만 한다","mis":"K4-2-u6-X23"},{"t":"겁이 없고 힘이 세다","mis":"K4-2-u6-X20"}],"explanation":["겨울 내내 했어요.","오래 했어요.","끝까지 해요."],"asset":{"type":"passage","lines":["경민이는 한번 하기로 한 것은 끝을 봐야 하는 아이였어요.","겨울 방학 내내 연살을 곱게 깎아 연 하나를 만들었지요.","\"이번엔 저 미루나무보다 높이 올릴 거야.\"","바람이 유난히 세게 불던 날, 경민이는 둑에 나가 연을 올렸어요.","얼레를 더 풀었을 때, 툭. 실이 끊어졌어요.","연은 빙글빙글 돌더니 미루나무 꼭대기 가지에 걸리고 말았어요.","경민이는 나무 아래에서 한참을 올려다보기만 했어요.","해는 벌써 둑 너머로 기울고 있었지요."],"title":"연을 놓친 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_review_d#8','kor',4,2,'u6','','g4_2_kor_u6_review_d','unit_review','K4-2-u6-C43',1,'mc','auto','「교실 문이 잠겨 있었습니다.」 다음에 이야기가 끊기는 문장은 무엇인가요?',ARRAY['K4-2-u6-X37','K4-2-u6-X35']::text[],false,'{"seq":8,"concept":"K4-2-u6-C43","difficulty":1,"kind":"mc","stem":"「교실 문이 잠겨 있었습니다.」 다음에 이야기가 끊기는 문장은 무엇인가요?","options":[{"t":"「그때 교실 문은 처음부터 활짝 열려 있었습니다.」","correct":true},{"t":"「그래서 우리는 교무실로 열쇠를 가지러 갔습니다.」","mis":"K4-2-u6-X37"},{"t":"「먼저 온 친구가 창문 쪽이 열려 있는지 살펴보았습니다.」","mis":"K4-2-u6-X35"},{"t":"「복도에서 기다리는 동안 아침 바람이 몹시 찼습니다.」","mis":"K4-2-u6-X35"}],"explanation":["이미 끝난 일을 되돌리면?","앞과 어긋나요.","끊기는 문장이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_review_d#9','kor',4,2,'u6','','g4_2_kor_u6_review_d','unit_review','K4-2-u6-C2',2,'mc','auto','이야기가 한 줄로 길게 이어지는 까닭으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u6-X15','K4-2-u6-X02','K4-2-u6-X01']::text[],false,'{"seq":9,"concept":"K4-2-u6-C2","difficulty":2,"kind":"mc","stem":"이야기가 한 줄로 길게 이어지는 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"어떤 일의 결과가 다음 일의 원인이 되기 때문에","correct":true},{"t":"일마다 원인이 하나씩만 있기 때문에","mis":"K4-2-u6-X15"},{"t":"일은 원인이거나 결과 하나만 되기 때문에","mis":"K4-2-u6-X02"},{"t":"뒤의 일이 앞의 일의 까닭이 되기 때문에","mis":"K4-2-u6-X01"}],"explanation":["결과가 다시 원인이 돼요.","사슬처럼 이어져요.","그래서 길게 이어져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_review_d#10','kor',4,2,'u6','','g4_2_kor_u6_review_d','unit_review','K4-2-u6-C18',2,'mc','auto','한 이야기에서 원인과 결과의 짝을 찾을 때 알맞은 태도는 무엇인가요?',ARRAY['K4-2-u6-X15','K4-2-u6-X18','K4-2-u6-X07']::text[],false,'{"seq":10,"concept":"K4-2-u6-C18","difficulty":2,"kind":"mc","stem":"한 이야기에서 원인과 결과의 짝을 찾을 때 알맞은 태도는 무엇인가요?","options":[{"t":"이야기에 나온 일끼리 짝을 여러 개 찾아본다","correct":true},{"t":"짝을 하나 찾으면 바로 끝낸다","mis":"K4-2-u6-X15"},{"t":"이야기에 없어도 그럴듯한 일을 끌어와 잇는다","mis":"K4-2-u6-X18"},{"t":"가장 재미있는 장면 하나만 고른다","mis":"K4-2-u6-X07"}],"explanation":["짝은 여러 겹이에요.","나온 일끼리만","여러 개 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_review_d#11','kor',4,2,'u6','','g4_2_kor_u6_review_d','unit_review','K4-2-u6-C10',2,'mc','auto','「같아서 좋았다.」처럼 말하면 무엇이 빠지나요?',ARRAY['K4-2-u6-X11','K4-2-u6-X07','K4-2-u6-X04']::text[],false,'{"seq":11,"concept":"K4-2-u6-C10","difficulty":2,"kind":"mc","stem":"「같아서 좋았다.」처럼 말하면 무엇이 빠지나요?","options":[{"t":"무엇을 까닭으로 예상했는지와 어느 부분이 같았는지","correct":true},{"t":"말하는 사람의 기분","mis":"K4-2-u6-X11"},{"t":"영상의 길이","mis":"K4-2-u6-X07"},{"t":"예상한 사람의 이름","mis":"K4-2-u6-X04"}],"explanation":["기분은 들어 있어요.","까닭이 빠졌어요.","어느 부분인지도요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_review_d#12','kor',4,2,'u6','','g4_2_kor_u6_review_d','unit_review','K4-2-u6-C12',2,'mc','auto','「늦게 가는 시계」에서 시계가 늦게 간 까닭을 다은이가 알아보기 전에 예상한다면, 근거가 있는 것은 무엇인가요?',ARRAY['K4-2-u6-X13','K4-2-u6-X18','K4-2-u6-X16']::text[],false,'{"seq":12,"concept":"K4-2-u6-C12","difficulty":2,"kind":"mc","stem":"「늦게 가는 시계」에서 시계가 늦게 간 까닭을 다은이가 알아보기 전에 예상한다면, 근거가 있는 것은 무엇인가요?","options":[{"t":"시계 안의 무언가가 제대로 움직이지 않을 것이다","correct":true},{"t":"시계가 아이들을 골탕 먹이려고 일부러 늦게 갈 것이다","mis":"K4-2-u6-X13"},{"t":"급식실이 시계보다 빨리 열릴 것이다","mis":"K4-2-u6-X18"},{"t":"시계는 원래 늦게 가는 물건이다","mis":"K4-2-u6-X16"}],"explanation":["시계가 늦게 가요.","시계 안을 떠올려요.","근거가 있는 예상이에요."],"asset":{"type":"passage","lines":["우리 반 벽시계는 언제부터인가 조금씩 늦게 갔어요.","그래서 시계를 보고 움직인 날은 급식실에 늘 꼴찌로 도착했지요.","\"시계가 오래돼서 그래.\" 아이들은 그렇게만 말했어요.","다은이는 선생님께 시계를 내려 달라고 부탁해 뒤쪽 건전지 칸을 열어 보았어요.","건전지 한 개가 헐겁게 빠져 있었어요.","다은이가 건전지를 꾹 눌러 끼우자 초바늘이 다시 힘차게 돌았어요."],"title":"늦게 가는 시계"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_review_d#13','kor',4,2,'u6','','g4_2_kor_u6_review_d','unit_review','K4-2-u6-C27',2,'mc','auto','이야기의 흐름을 정리할 때 「지금」 칸에 써야 할 것은 무엇인가요?',ARRAY['K4-2-u6-X24','K4-2-u6-X33']::text[],false,'{"seq":13,"concept":"K4-2-u6-C27","difficulty":2,"kind":"mc","stem":"이야기의 흐름을 정리할 때 「지금」 칸에 써야 할 것은 무엇인가요?","options":[{"t":"끊긴 대목에서 인물이 놓여 있는 상황","correct":true},{"t":"이야기의 맨 처음 일","mis":"K4-2-u6-X24"},{"t":"내가 상상한 뒷이야기","mis":"K4-2-u6-X33"},{"t":"가장 재미있었던 장면","mis":"K4-2-u6-X24"}],"explanation":["어디까지 왔나요?","끊긴 대목이에요.","지금 놓인 상황이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_review_d#14','kor',4,2,'u6','','g4_2_kor_u6_review_d','unit_review','K4-2-u6-C44',2,'mc','auto','「빈 새집」을 역할놀이로 만들 때, 하람이의 대사로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u6-X38','K4-2-u6-X36']::text[],false,'{"seq":14,"concept":"K4-2-u6-C44","difficulty":2,"kind":"mc","stem":"「빈 새집」을 역할놀이로 만들 때, 하람이의 대사로 알맞은 것은 무엇인가요?","options":[{"t":"「여기는 너무 시끄러운가 봐. 조용한 데로 옮겨서 내일도 와 봐야지.」","correct":true},{"t":"「새가 안 오면 말지 뭐. 이제 새집은 버릴래.」","mis":"K4-2-u6-X38"},{"t":"「나는 원래 새를 싫어해.」","mis":"K4-2-u6-X38"},{"t":"「새집이 갑자기 하늘을 날면 좋겠다.」","mis":"K4-2-u6-X36"}],"explanation":["하람이는 날마다 조금씩 해내요.","까닭도 살펴요.","내일도 와 봐요."],"asset":{"type":"passage","lines":["하람이는 한번 마음먹은 일은 날마다 조금씩이라도 해내는 아이다.","봄에 하람이는 손수 만든 새집을 학교 뒤뜰 나무에 달았다.","그런데 열흘이 지나도 새집에 드나드는 새가 한 마리도 없었다.","새집 바로 아래에는 그네가 있어 쉬는 시간마다 아이들이 북적였다.","하람이는 새집과 그네를 번갈아 바라보았다."],"title":"빈 새집"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_review_d#15','kor',4,2,'u6','','g4_2_kor_u6_review_d','unit_review','K4-2-u6-C24',2,'mc','auto','스스로 확인하기 표를 채우는 까닭으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u6-X21']::text[],false,'{"seq":15,"concept":"K4-2-u6-C24","difficulty":2,"kind":"mc","stem":"스스로 확인하기 표를 채우는 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"다시 읽어 볼 곳을 찾으려고","correct":true},{"t":"점수를 받으려고","mis":"K4-2-u6-X21"},{"t":"「예」가 많아 보이게 하려고","mis":"K4-2-u6-X21"},{"t":"선생님께 잘한 것처럼 보이려고","mis":"K4-2-u6-X21"}],"explanation":["이 표는 점수가 없어요.","「아니요」를 찾아요.","돌아갈 곳을 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_review_d#16','kor',4,2,'u6','','g4_2_kor_u6_review_d','unit_review','K4-2-u6-C54',2,'mc','auto','창가 화분이 자꾸 시들었어요. 원인과 결과를 생각해 알맞게 한 일은 무엇인가요?',ARRAY['K4-2-u6-X48','K4-2-u6-X17']::text[],false,'{"seq":16,"concept":"K4-2-u6-C54","difficulty":2,"kind":"mc","stem":"창가 화분이 자꾸 시들었어요. 원인과 결과를 생각해 알맞게 한 일은 무엇인가요?","options":[{"t":"흙이 말라 있는 것을 보고 물 주는 날을 정했다","correct":true},{"t":"까닭은 찾지 않고 새 화분으로 바꾸었다","mis":"K4-2-u6-X48"},{"t":"화분이 시든 것은 까닭이 없다고 여겼다","mis":"K4-2-u6-X48"},{"t":"화분에 예쁜 리본을 달아 주었다","mis":"K4-2-u6-X17"}],"explanation":["왜 시들었나요?","흙이 말라 있었어요.","까닭을 찾아 바꿔요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_review_d#17','kor',4,2,'u6','','g4_2_kor_u6_review_d','unit_review','K4-2-u6-C30',3,'mc','auto','「늦게 가는 시계」의 뒷이야기를 쓴 세 친구 가운데 알맞게 생각한 친구는 누구인가요?',ARRAY['K4-2-u6-X25','K4-2-u6-X26','K4-2-u6-X29']::text[],false,'{"seq":17,"concept":"K4-2-u6-C30","difficulty":3,"kind":"mc","stem":"「늦게 가는 시계」의 뒷이야기를 쓴 세 친구 가운데 알맞게 생각한 친구는 누구인가요?","options":[{"t":"「건전지 칸을 연 다은이가 다른 교실 시계도 살펴보는 이야기를 썼어. 성격과 이어지니까.」","correct":true},{"t":"「정답이 없으니까 시계가 노래하는 이야기를 아무렇게나 썼어.」","mis":"K4-2-u6-X25"},{"t":"「선생님이 생각한 답을 맞히려고 그대로 다시 썼어.」","mis":"K4-2-u6-X26"},{"t":"「가장 놀라운 게 좋으니 시계가 폭발하는 이야기를 썼어.」","mis":"K4-2-u6-X29"}],"explanation":["정답은 없어요.","아무거나도 아니에요.","성격과 이어져요."],"asset":{"type":"passage","lines":["우리 반 벽시계는 언제부터인가 조금씩 늦게 갔어요.","그래서 시계를 보고 움직인 날은 급식실에 늘 꼴찌로 도착했지요.","\"시계가 오래돼서 그래.\" 아이들은 그렇게만 말했어요.","다은이는 선생님께 시계를 내려 달라고 부탁해 뒤쪽 건전지 칸을 열어 보았어요.","건전지 한 개가 헐겁게 빠져 있었어요.","다은이가 건전지를 꾹 눌러 끼우자 초바늘이 다시 힘차게 돌았어요."],"title":"늦게 가는 시계"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_review_d#18','kor',4,2,'u6','','g4_2_kor_u6_review_d','unit_review','K4-2-u6-C39',3,'mc','auto','뒷이야기 세 가지 가운데 하나를 고를 때 기준이 아닌 것은 무엇인가요?',ARRAY['K4-2-u6-X05']::text[],false,'{"seq":18,"concept":"K4-2-u6-C39","difficulty":3,"kind":"mc","stem":"뒷이야기 세 가지 가운데 하나를 고를 때 기준이 아닌 것은 무엇인가요?","options":[{"t":"가장 놀라운 일이 벌어지는가","correct":true},{"t":"인물이 앞의 모습 그대로 움직이는가","mis":"K4-2-u6-X05"},{"t":"지금까지의 흐름에서 이어지는가","mis":"K4-2-u6-X05"},{"t":"그 일이 생길 까닭이 앞에 있는가","mis":"K4-2-u6-X05"}],"explanation":["기준 셋을 떠올려요.","성격 · 흐름 · 까닭","놀라움은 기준이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_review_d#19','kor',4,2,'u6','','g4_2_kor_u6_review_d','unit_review','K4-2-u6-C31',3,'mc','auto','「늦게 가는 시계」 뒤에 「다은이는 시계가 어떻게 되든 상관없다며 모른 척했다」를 쓰면 알맞지 않은 까닭은 무엇인가요?',ARRAY['K4-2-u6-X27','K4-2-u6-X28','K4-2-u6-X29']::text[],false,'{"seq":19,"concept":"K4-2-u6-C31","difficulty":3,"kind":"mc","stem":"「늦게 가는 시계」 뒤에 「다은이는 시계가 어떻게 되든 상관없다며 모른 척했다」를 쓰면 알맞지 않은 까닭은 무엇인가요?","options":[{"t":"직접 까닭을 살펴보던 다은이의 행동과 이어지지 않아서","correct":true},{"t":"모른 척하는 일은 너무 평범해서","mis":"K4-2-u6-X27"},{"t":"문장이 너무 길어서","mis":"K4-2-u6-X28"},{"t":"시계가 더 신기하게 바뀌지 않아서","mis":"K4-2-u6-X29"}],"explanation":["다은이는 무엇을 했나요?","건전지 칸을 열었어요.","그 행동과 끊어졌어요."],"asset":{"type":"passage","lines":["우리 반 벽시계는 언제부터인가 조금씩 늦게 갔어요.","그래서 시계를 보고 움직인 날은 급식실에 늘 꼴찌로 도착했지요.","\"시계가 오래돼서 그래.\" 아이들은 그렇게만 말했어요.","다은이는 선생님께 시계를 내려 달라고 부탁해 뒤쪽 건전지 칸을 열어 보았어요.","건전지 한 개가 헐겁게 빠져 있었어요.","다은이가 건전지를 꾹 눌러 끼우자 초바늘이 다시 힘차게 돌았어요."],"title":"늦게 가는 시계"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_review_d#20','kor',4,2,'u6','','g4_2_kor_u6_review_d','unit_review','K4-2-u6-C40',3,'mc','auto','이어질 이야기에서 인물이 앞과 다르게 움직일 때 가장 먼저 확인할 것은 무엇인가요?',ARRAY['K4-2-u6-X29','K4-2-u6-X28','K4-2-u6-X32']::text[],false,'{"seq":20,"concept":"K4-2-u6-C40","difficulty":3,"kind":"mc","stem":"이어질 이야기에서 인물이 앞과 다르게 움직일 때 가장 먼저 확인할 것은 무엇인가요?","options":[{"t":"왜 다르게 움직이는지 까닭이 쓰여 있는가","correct":true},{"t":"더 놀라운 쪽으로 바뀌었는가","mis":"K4-2-u6-X29"},{"t":"문장이 더 길어졌는가","mis":"K4-2-u6-X28"},{"t":"인물이 바뀌었다고 한 줄 적었는가","mis":"K4-2-u6-X32"}],"explanation":["선언만으로는 안 돼요.","까닭을 확인해요.","있으면 이어져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_review_d#21','kor',4,2,'u6','','g4_2_kor_u6_review_d','unit_review','K4-2-u6-C45',3,'mc','auto','역할놀이 준비에서 「뒤에 벌어질 일에 까닭 붙이기」를 하는 까닭은 무엇인가요?',ARRAY['K4-2-u6-X40','K4-2-u6-X50','K4-2-u6-X29']::text[],false,'{"seq":21,"concept":"K4-2-u6-C45","difficulty":3,"kind":"mc","stem":"역할놀이 준비에서 「뒤에 벌어질 일에 까닭 붙이기」를 하는 까닭은 무엇인가요?","options":[{"t":"까닭이 있어야 보는 사람이 이야기가 이어진다고 느끼기 때문에","correct":true},{"t":"대사를 더 길게 만들려고","mis":"K4-2-u6-X40"},{"t":"까닭은 정하지 않아도 되지만 시간을 채우려고","mis":"K4-2-u6-X50"},{"t":"가장 놀라운 결말을 만들려고","mis":"K4-2-u6-X29"}],"explanation":["까닭이 있으면?","이어져요.","보는 사람도 알아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_review_d#22','kor',4,2,'u6','','g4_2_kor_u6_review_d','unit_review','K4-2-u6-C37',3,'mc','auto','「늦게 가는 시계」 뒤에 다은이의 성격을 이용해 상상한 것으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u6-X32','K4-2-u6-X25','K4-2-u6-X23']::text[],false,'{"seq":22,"concept":"K4-2-u6-C37","difficulty":3,"kind":"mc","stem":"「늦게 가는 시계」 뒤에 다은이의 성격을 이용해 상상한 것으로 알맞은 것은 무엇인가요?","options":[{"t":"다은이가 옆 반 시계도 늦게 가는지 알아보자고 했다","correct":true},{"t":"다은이가 시계 일은 잊고 다시는 생각하지 않았다","mis":"K4-2-u6-X32"},{"t":"시계가 다은이에게 고맙다고 인사했다","mis":"K4-2-u6-X25"},{"t":"다은이가 시계를 일부러 늦게 맞추어 두었다","mis":"K4-2-u6-X23"}],"explanation":["다은이는 직접 살펴보는 아이예요.","다른 시계도?","그 결대로 움직여요."],"asset":{"type":"passage","lines":["우리 반 벽시계는 언제부터인가 조금씩 늦게 갔어요.","그래서 시계를 보고 움직인 날은 급식실에 늘 꼴찌로 도착했지요.","\"시계가 오래돼서 그래.\" 아이들은 그렇게만 말했어요.","다은이는 선생님께 시계를 내려 달라고 부탁해 뒤쪽 건전지 칸을 열어 보았어요.","건전지 한 개가 헐겁게 빠져 있었어요.","다은이가 건전지를 꾹 눌러 끼우자 초바늘이 다시 힘차게 돌았어요."],"title":"늦게 가는 시계"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_review_d#23','kor',4,2,'u6','','g4_2_kor_u6_review_d','unit_review','K4-2-u6-C54',4,'essay','teacher','내 생활에서 일어난 일 하나를 골라 원인과 결과를 쓰고, 까닭을 알고 나서 그다음을 어떻게 바꿀 수 있는지 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K4-2-u6-C54","difficulty":4,"kind":"essay","stem":"내 생활에서 일어난 일 하나를 골라 원인과 결과를 쓰고, 까닭을 알고 나서 그다음을 어떻게 바꿀 수 있는지 쓰세요.","answer_guide":{"answer":"예: 지난주에 숙제를 두 번 빠뜨렸는데, 알림장을 가방 맨 아래에 넣어 두어서 꺼내 보지 않았기 때문이다. 그래서 알림장을 필통 바로 옆 칸에 넣기로 했고, 이번 주에는 한 번도 빠뜨리지 않았다.","scoring_points":["생활 속 일 하나의 원인을 썼는가","그 일의 결과를 썼는가","까닭을 알고 바꾼 그다음을 썼는가"]},"explanation":["생활 속에도 까닭이 있어요.","왜? 그래서?","그다음을 바꿔요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_review_d#24','kor',4,2,'u6','','g4_2_kor_u6_review_d','unit_review','K4-2-u6-C39',4,'essay','teacher','「빈 화분의 싹」을 읽은 세 친구의 뒷이야기 ㉮ · ㉯ · ㉰ 가운데 가장 자연스러운 것을 고르고, 나머지 둘이 왜 덜 자연스러운지 각각 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K4-2-u6-C39","difficulty":4,"kind":"essay","stem":"「빈 화분의 싹」을 읽은 세 친구의 뒷이야기 ㉮ · ㉯ · ㉰ 가운데 가장 자연스러운 것을 고르고, 나머지 둘이 왜 덜 자연스러운지 각각 쓰세요.","answer_guide":{"answer":"예: ㉮가 가장 자연스럽다. 책을 찾아봐야 마음이 놓이는 예린이의 성격과 이어지기 때문이다. ㉯는 놀랍지만 싹이 하룻밤에 천장까지 자랄 까닭이 앞에 없다. ㉰는 궁금해하던 예린이가 왜 갑자기 궁금해하지 않는지 까닭 없이 성격만 바뀌었다.","scoring_points":["가장 자연스러운 것을 골랐는가","㉯가 덜 자연스러운 까닭을 썼는가","㉰가 덜 자연스러운 까닭을 썼는가"]},"explanation":["놀라운 쪽이 아니에요.","성격 · 흐름 · 까닭","하나씩 따져요."],"asset":{"type":"passage","lines":["㉮ 예린이는 도서관에서 식물 책을 빌려 싹의 잎 모양과 하나하나 견주어 보았다.","㉯ 싹이 하룻밤 사이에 교실 천장까지 자라 열매가 주렁주렁 열렸다.","㉰ 예린이는 싹이 왜 났는지 궁금해하지 않고 화분을 치워 버렸다."],"title":"세 친구가 상상한 뒷이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u6_review_d#25','kor',4,2,'u6','','g4_2_kor_u6_review_d','unit_review','K4-2-u6-C52',4,'essay','teacher','「앉다」와 「않다」가 모두 들어가는 문장을 하나 지어 쓰고, 두 낱말의 소리와 뜻이 어떻게 다른지 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K4-2-u6-C52","difficulty":4,"kind":"essay","stem":"「앉다」와 「않다」가 모두 들어가는 문장을 하나 지어 쓰고, 두 낱말의 소리와 뜻이 어떻게 다른지 쓰세요.","answer_guide":{"answer":"예: 「동생은 의자에 앉지 않고 서서 밥을 먹었다.」 앉다는 [안따]로 소리 나고 자리에 몸을 두는 일이며, 않다는 [안타]로 소리 나고 어떤 일을 하지 않는다는 뜻이다.","scoring_points":["앉다와 않다가 모두 들어간 문장을 바르게 썼는가","두 낱말의 소리를 썼는가","두 낱말의 뜻을 구별해 썼는가"]},"explanation":["ㄵ과 ㄶ이에요.","[안따] · [안타]","뜻이 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
